module cpu0_ipgen_cfu_mux #(parameter CFU_LI_VERSION = 1,
        parameter CFU_N_CFUS = 2,
        parameter CFU_N_STATES = 1,
        parameter CFU_CFU_ID_W = 4,
        parameter CFU_STATE_ID_W = 3,
        parameter CFU_FUNC_ID_W = 4,
        parameter CFU_INSN_W = 32,
        parameter CFU_DATA_W = 32,
        parameter CFU_STATUS_W = 0) (
    input cmd_valid,
    output reg cmd_ready,
    input [(CFU_CFU_ID_W - 1):0] cmd_payload_function_id,
    input [31:0] cmd_payload_inputs_0,
    input [31:0] cmd_payload_inputs_1,
    input [2:0] cmd_payload_state_index,
    input [3:0] cmd_payload_cfu_index,
    input [31:0] cmd_payload_raw_insn,
    output reg rsp_valid,
    input rsp_ready,
    output reg [31:0] rsp_payload_outputs_0,
    output reg [2:0] rsp_payload_status,
    output [(CFU_N_CFUS - 1):0] req_valid,
    input [(CFU_N_CFUS - 1):0] req_ready,
    output [(CFU_CFU_ID_W - 1):0] req_func [(CFU_N_CFUS - 1):0],
    output [31:0] req_data0 [(CFU_N_CFUS - 1):0],
    output [31:0] req_data1 [(CFU_N_CFUS - 1):0],
    output [2:0] req_state [(CFU_N_CFUS - 1):0],
    output [3:0] req_cfu [(CFU_N_CFUS - 1):0],
    output [31:0] req_insn [(CFU_N_CFUS - 1):0],
    input [(CFU_N_CFUS - 1):0] resp_valid,
    output [(CFU_N_CFUS - 1):0] resp_ready,
    input [31:0] resp_data [(CFU_N_CFUS - 1):0],
    input [2:0] resp_status [(CFU_N_CFUS - 1):0],
    input clk,
    input reset) ;
    genvar CFU_ID ;
    generate
        for (CFU_ID = 0;(CFU_ID < CFU_N_CFUS);CFU_ID = (CFU_ID + 1))
        begin : gen_cfu_req_cmd
            assign req_valid[CFU_ID] = ((CFU_ID == cmd_payload_cfu_index) ? cmd_valid : 0) ;
            assign req_func[CFU_ID] = cmd_payload_function_id ;
            assign req_data0[CFU_ID] = cmd_payload_inputs_0 ;
            assign req_data1[CFU_ID] = cmd_payload_inputs_1 ;
            assign req_state[CFU_ID] = cmd_payload_state_index ;
            assign req_cfu[CFU_ID] = cmd_payload_cfu_index ;
            assign req_insn[CFU_ID] = cmd_payload_raw_insn ;
            assign resp_ready[CFU_ID] = ((CFU_ID == cmd_payload_cfu_index) ? rsp_ready : 0) ;
        end
    endgenerate
    integer cfu_id ;
    always
        @(*)
        begin
            cmd_ready = 1'b0 ;
            rsp_valid = 1'b0 ;
            rsp_payload_outputs_0 = 32'b0 ;
            rsp_payload_status = 3'b0 ;
            for (cfu_id = 0 ; (cfu_id < CFU_N_CFUS) ; cfu_id = (cfu_id + 1))
                begin
                    if ((req_valid[cfu_id] & req_ready[cfu_id]))
                        begin
                            cmd_ready = 1'b1 ;
                        end
                    if (resp_valid[cfu_id])
                        begin
                            rsp_valid = 1'b1 ;
                            rsp_payload_outputs_0 = resp_data[cfu_id] ;
                            rsp_payload_status = rsp_payload_status[cfu_id] ;
                        end
                end
        end
endmodule



/*
|      Address      | Description |                      Note                      |
|-------------------|-------------|------------------------------------------------|
| `BASE` + `0x0`    | msip        | Machine mode software interrupt (IPI)          |
| `BASE` + `0x4000` | mtimecmp    | Machine mode timer compare register for Hart 0 |
| `BASE` + `0xBFF8` | mtime       | Timer register                                 |
| `BASE` + `0xD000` | wdt_wdcsr   | watch dog csr register                         |
*/
module cpu0_ipgen_top_clint_wdt #(parameter integer DATA_WIDTH = 32,
        parameter integer ADDR_WIDTH = 16) (
    //fix to 32bit
    input rst_n,
    input sys_clk,
    input rtc_clk,  //32.768K, but actually 32K
    //local bus
    input cmd_valid,
    output cmd_ready,
    input cmd_payload_wr,
    input [(ADDR_WIDTH - 1):0] cmd_payload_address,
    input [(DATA_WIDTH - 1):0] cmd_payload_data,
    input [1:0] cmd_payload_size,
    output rsp_ready,
    output rsp_error,
    output [(DATA_WIDTH - 1):0] rsp_data,
    //user port
    output clint_msip_irq,
    output clint_tim_irq,
    output wdt_s1_to,
    output wdt_s2_to) ;
    localparam BYTE_WIDTH = (DATA_WIDTH / 8) ;
    // HSIZE transactions
    localparam [1:0] X32_WORD = 2'b10 ;
    localparam [1:0] X16_HALFWORD = 2'b01 ;
    localparam [1:0] X8_BYTE = 2'b00 ;
    //signals
    wire [(ADDR_WIDTH - 1):0] bus_addr ;
    wire [(ADDR_WIDTH - 1):0] bus_addr_trim ;
    wire [(DATA_WIDTH - 1):0] bus_wr_data ;
    // reg  [(DATA_WIDTH-1):0]      bus_rd_data      ;
    reg [(DATA_WIDTH - 1):0] rd_data_reg ;
    reg rd_data_ready ;
    wire [1:0] bus_size ;
    wire [(BYTE_WIDTH - 1):0] byte_en ;
    wire bus_read ;
    wire bus_write ;
    wire rtc_clk_sync_r ;
    wire tick_1 ;
    reg wdt_tick ;
    //registers
    reg clint_msip0 ;
    reg [63:0] clint_cmp = 64'hffffffffffffffff ;
    reg [63:0] clint_tim_reg ;
    reg [63:0] clint_tim ;
    reg clint_tim_load ;
    reg timer_irq_r ;
    reg [9:0] wdt_cnt_load ;
    reg [10:0] wdt_cnter ;
    reg wdt_s2wto ;
    reg wdt_s1wto ;
    reg wdt_wden ;
    integer byte_index ;
    assign bus_read = ((cmd_valid == 1) && (cmd_payload_wr == 0)) ;
    assign bus_write = ((cmd_valid == 1) && (cmd_payload_wr == 1)) ;
    assign bus_size = cmd_payload_size ;
    assign bus_addr = cmd_payload_address ;
    assign bus_addr_trim = ((DATA_WIDTH == 32) ? {2'b0,
                bus_addr[(ADDR_WIDTH - 1):2]} : ((DATA_WIDTH == 16) ? {1'b0,
                bus_addr[(ADDR_WIDTH - 1):1]} : bus_addr[(ADDR_WIDTH - 1):0])) ;
    assign bus_wr_data = cmd_payload_data ;
    assign byte_en = ((DATA_WIDTH == 32) ? ((bus_size == X32_WORD) ? {4{1'b1}} : ((bus_size == X16_HALFWORD) ? ((bus_addr[1] == 1) ? {{2{1'b1}},
                {2{1'b0}}} : {{2{1'b0}},
                {2{1'b1}}}) : ((bus_addr[1:0] == 3) ? {/*(bus_size == X8_BYTE)?*/ 1'b1,
                {3{1'b0}}} : ((bus_addr[1:0] == 2) ? {1'b0,
                1'b1,
                {2{1'b0}}} : ((bus_addr[1:0] == 1) ? {{2{1'b0}},
                1'b1,
                1'b0} : {{3{1'b0}},
                1'b1}))))) : ((DATA_WIDTH == 16) ? ((bus_size == X16_HALFWORD) ? {2{1'b1}} : ((bus_addr[1] == 1) ? {/*(bus_size == X8_BYTE)?*/ 1'b1,
                1'b0} : {1'b0,
                1'b1})) : {BYTE_WIDTH{/*(DATA_WIDTH == 8)*/ 1'b1}})) ;
    assign rsp_data = rd_data_reg ;
    assign rsp_ready = rd_data_ready ;
    assign rsp_error = 0 ; //to do add error handle
    assign cmd_ready = 1 ; //valid does not depend on ready
    always
        @(posedge sys_clk)
        begin
            if ((rst_n == 1'b0))
                begin
                    clint_msip0 <=  0 ;
                    clint_tim_reg <=  0 ;
                    clint_tim <=  0 ;
                    clint_tim_load <=  0 ;
                    wdt_cnt_load <=  0 ;
                    wdt_cnter <=  0 ;
                    wdt_s2wto <=  0 ;
                    wdt_s1wto <=  0 ;
                    wdt_wden <=  0 ;
                end
            else
                begin
                    if (bus_write)
                        begin
                            case (bus_addr_trim)
                            'h0000 :
                                clint_msip0 <=  bus_wr_data[0] ;
                            'h1000 :
                                for (byte_index = 0 ; (byte_index <= (BYTE_WIDTH - 1)) ; byte_index = (byte_index + 1))
                                    begin
                                        if ((byte_en[byte_index] == 1))
                                            begin
                                                clint_cmp[(byte_index * 8) +: 8] <=  bus_wr_data[(byte_index * 8) +: 8] ;
                                            end
                                    end
                            'h1001 :
                                for (byte_index = 0 ; (byte_index <= (BYTE_WIDTH - 1)) ; byte_index = (byte_index + 1))
                                    begin
                                        if ((byte_en[byte_index] == 1))
                                            begin
                                                clint_cmp[((byte_index * 8) + 32) +: 8] <=  bus_wr_data[(byte_index * 8) +: 8] ;
                                            end
                                    end
                            'h2ffe :
                                for (byte_index = 0 ; (byte_index <= (BYTE_WIDTH - 1)) ; byte_index = (byte_index + 1))
                                    begin
                                        if ((byte_en[byte_index] == 1))
                                            begin
                                                clint_tim_reg[(byte_index * 8) +: 8] <=  bus_wr_data[(byte_index * 8) +: 8] ;
                                                clint_tim_load <=  1'b1 ;
                                            end
                                    end
                            'h2fff :
                                for (byte_index = 0 ; (byte_index <= (BYTE_WIDTH - 1)) ; byte_index = (byte_index + 1))
                                    begin
                                        if ((byte_en[byte_index] == 1))
                                            begin
                                                clint_tim_reg[((byte_index * 8) + 32) +: 8] <=  bus_wr_data[(byte_index * 8) +: 8] ;
                                                clint_tim_load <=  1'b1 ;
                                            end
                                    end
                            'h3400 :
                                begin
                                    wdt_cnt_load <=  bus_wr_data[13:4] ;
                                    wdt_cnter <=  {1'b1,
                                            bus_wr_data[13:4]} ;
                                    wdt_s2wto <=  bus_wr_data[3] ;
                                    wdt_s1wto <=  bus_wr_data[2] ;
                                    wdt_wden <=  bus_wr_data[0] ;
                                end
                            default :
                                begin
                                    clint_msip0 <=  clint_msip0 ;
                                    clint_cmp <=  clint_cmp ;
                                    clint_tim_reg <=  clint_tim_reg ;
                                    clint_tim_load <=  clint_tim_load ;
                                    wdt_cnt_load <=  wdt_cnt_load ;
                                    wdt_s2wto <=  wdt_s2wto ;
                                    wdt_s1wto <=  wdt_s1wto ;
                                    wdt_wden <=  wdt_wden ;
                                end
                            endcase
                        end
                    else
                        begin
                            //counter
                            clint_tim_load <=  1'b0 ;
                            //msip counter
                            if (clint_tim_load)
                                begin
                                    clint_tim <=  clint_tim_reg ;
                                end
                            else
                                if (rtc_clk_sync_r)
                                    begin
                                        clint_tim <=  (clint_tim + 1) ;
                                    end
                            //watch dog counter
                            if (((tick_1 & wdt_wden) & wdt_cnter[10]))
                                begin
                                    wdt_cnter <=  (wdt_cnter - 1) ;
                                end
                            if ((wdt_wden & (wdt_cnter[10] == 0)))
                                begin
                                    //load initial value
                                    wdt_cnter <=  {1'b1,
                                            wdt_cnt_load} ;
                                end
                            wdt_s2wto <=  (wdt_wden & ((wdt_s1wto & (wdt_cnter[10] == 0)) | wdt_s2wto)) ;
                            wdt_s1wto <=  (wdt_wden & ((wdt_cnter[10] == 0) | wdt_s1wto)) ;
                        end
                end
        end
    always
        @(posedge sys_clk)
        begin
            if ((rst_n == 1'b0))
                begin
                    timer_irq_r <=  1'b0 ;
                end
            if ((clint_tim >= clint_cmp))
                begin
                    timer_irq_r <=  1'b1 ;
                end
            else
                begin
                    timer_irq_r <=  1'b0 ;
                end
        end
    always
        @(posedge sys_clk)
        begin
            if ((rst_n == 1'b0))
                begin
                    wdt_tick <=  1'b0 ;
                end
            begin
                wdt_tick <=  clint_tim[14] ;
            end
        end
    assign clint_msip_irq = clint_msip0 ;
    assign clint_tim_irq = timer_irq_r ;
    assign tick_1 = (wdt_tick != clint_tim[14]) ;
    assign wdt_s1_to = wdt_s1wto ;
    assign wdt_s2_to = wdt_s2wto ;
    // always @(*)begin
    //     // Address decoding for reading registers
    //     case ( bus_addr_trim )
    //     'h0000   : bus_rd_data <= {31'b0, clint_msip0};
    //     'h1000   : bus_rd_data <= clint_cmp[31:0];
    //     'h1001   : bus_rd_data <= clint_cmp[63:32];
    //     'h2ffe   : bus_rd_data <= clint_tim[31:0];
    //     'h2fff   : bus_rd_data <= clint_tim[63:32];
    //     'h3400   : bus_rd_data <= {18'b0,wdt_cnter[9:0],wdt_s2wto,wdt_s1wto,1'b0,wdt_wden};
    //     default  : bus_rd_data <= 0;
    //     endcase
    // end
    always
        @(posedge sys_clk)
        begin
            if ((rst_n == 1'b0))
                begin
                    rd_data_reg <=  0 ;
                    rd_data_ready <=  0 ;
                end
            else
                begin
                    if (bus_read)
                        begin
                            // rd_data_reg   <= bus_rd_data;
                            case (bus_addr_trim)
                            'h0000 :
                                rd_data_reg <=  {31'b0,
                                        clint_msip0} ;
                            'h1000 :
                                rd_data_reg <=  clint_cmp[31:0] ;
                            'h1001 :
                                rd_data_reg <=  clint_cmp[63:32] ;
                            'h2ffe :
                                rd_data_reg <=  clint_tim[31:0] ;
                            'h2fff :
                                rd_data_reg <=  clint_tim[63:32] ;
                            'h3400 :
                                rd_data_reg <=  {18'b0,
                                        wdt_cnter[9:0],
                                        wdt_s2wto,
                                        wdt_s1wto,
                                        1'b0,
                                        wdt_wden} ;
                            default :
                                rd_data_reg <=  0 ;
                            endcase
                            rd_data_ready <=  1 ;
                        end
                    else
                        begin
                            rd_data_ready <=  0 ;
                        end
                end
        end
    // -----------------------------
    // RTC time tracking facilities
    // -----------------------------
    // 1. Put the RTC input through a classic two stage edge-triggered synchronizer to filter out any
    //    metastability effects (or at least make them unlikely :-))
    cpu0_ipgen_clint_sync_wedge i_sync_edge (.clk_i(sys_clk),
                .rst_ni(rst_n),
                .serial_i(rtc_clk),
                .r_edge_o(rtc_clk_sync_r),
                .f_edge_o(),
                .serial_o()) ;
endmodule



module cpu0_ipgen_clint_sync_wedge #(parameter STAGES = 2) (
    input clk_i,
    input rst_ni,
    input serial_i,
    output r_edge_o,
    output f_edge_o,
    output serial_o) ;
    wire serial ;
    reg serial_q ;
    assign serial_o = serial_q ;
    assign f_edge_o = ((~serial) & serial_q) ;
    assign r_edge_o = (serial & (~serial_q)) ;
    cpu0_ipgen_clint_sync #(.STAGES(STAGES)) i_sync (.clk_i(clk_i),
                .rst_ni(rst_ni),
                .serial_i(serial_i),
                .serial_o(serial)) ;
    always
        @(posedge clk_i or
            negedge rst_ni)
        begin
            if ((!rst_ni))
                begin
                    serial_q <=  1'b0 ;
                end
            else
                begin
                    serial_q <=  serial ;
                end
        end
endmodule



module cpu0_ipgen_clint_sync #(parameter STAGES = 2) (
    input clk_i,
    input rst_ni,
    input serial_i,
    output serial_o) ;
    reg reg_q ;
    always
        @(posedge clk_i or
            negedge rst_ni)
        begin
            if ((!rst_ni))
                begin
                    reg_q <=  'h0 ;
                end
            else
                begin
                    reg_q <=  serial_i ;
                end
        end
    assign serial_o = reg_q ;
endmodule



