module cpu0_ipgen_d_ff_plain_rst_t #(parameter integer bit_width = 32'sd8,
        parameter [(bit_width - 1):0] default_value = {bit_width{1'b0}},
        parameter [0:0] reset_level = 1'b0,
        parameter [0:0] reset_sync = 1'b0) (
    input wire CLK,
    input wire RST,
    input wire [(bit_width - 1):0] D,
    output wire [(bit_width - 1):0] Q) ;
    // local register holding the value
    reg [(bit_width - 1):0] Q_reg ;
    generate
        if (reset_sync)
            begin : SYNC
                always
                    @(posedge CLK)
                    begin
                        if ((RST == reset_level))
                            begin
                                Q_reg <=  default_value ;
                            end
                        else
                            begin
                                Q_reg <=  D ;
                            end
                    end
            end
        else
            if (reset_level)
                begin : ASYNC_HIGH
                    always
                        @(posedge CLK or
                            posedge RST)
                        begin
                            if ((RST == 1'b1))
                                begin
                                    Q_reg <=  default_value ;
                                end
                            else
                                begin
                                    Q_reg <=  D ;
                                end
                        end
                end
            else
                begin : ASYNC_LOW
                    always
                        @(posedge CLK or
                            negedge RST)
                        begin
                            if ((RST == 1'b0))
                                begin
                                    Q_reg <=  default_value ;
                                end
                            else
                                begin
                                    Q_reg <=  D ;
                                end
                        end
                end
    endgenerate
    assign Q = Q_reg ;

// d_ff_plain_rst_t
endmodule



