                .Q(TMS_reg_Q0)) ;
    // instance of 'TDI_reg' register:
    cpu0_ipgen_d_ff_plain_rst_we_t #(.bit_width(32'd1),
            .default_value(1'b0),
            .reset_level(1'b0),
            .reset_sync(1'b0)) TDI_reg (.CLK(TDI_reg_CLK),
