    cpu0_ipgen_d_ff_plain_rst_we_t #(.bit_width(32'd2),
            .default_value(2'b00),
            .reset_level(1'b0),
            .reset_sync(1'b0)) TCK_counter_reg (.CLK(TCK_counter_reg_CLK),
                .RST(TCK_counter_reg_RST),
                .WE(TCK_counter_reg_WE0),
                .D(TCK_counter_reg_D0),
                .Q(TCK_counter_reg_Q0)) ;
    // data-path code:
    assign bscan_SHIFT = shift_delay2_reg_Q0 ;
    assign bscan_SEL = ((ip_enable & ce_delay2_reg_Q0) & tracy_enable) ;
    assign shift_delay_reg_CLK = (~bscan_DRCK) ;
    assign shift_delay_reg_RST = bscan_RESET ;
    assign shift_delay_reg_D0 = jshift ;
    assign shift_delay2_reg_CLK = bscan_DRCK ;
    assign shift_delay2_reg_RST = bscan_RESET ;
    assign shift_delay2_reg_D0 = shift_delay_reg_Q0 ;
    assign ce_delay_reg_CLK = (~bscan_DRCK) ;
    assign ce_delay_reg_RST = bscan_RESET ;
    assign ce_delay_reg_D0 = jce2 ;
    assign ce_delay2_reg_CLK = bscan_DRCK ;
    assign ce_delay2_reg_RST = bscan_RESET ;
    assign ce_delay2_reg_D0 = ce_delay_reg_Q0 ;
    assign TCK_buff_I = bscan_DRCK ;
    assign TCK_buff_CE = (TCK_counter_reg_Q0 == 2'd3) ;
    assign shift_enable_wire = (((bscan_SHIFT & bscan_SEL) == 1'd1) && ((TCK_counter_reg_Q0 != 2'd0) || ((TCK_counter_reg_Q0 == 2'd0) && (TDI_reg2_Q0 == 1'd1)))) ;
    assign TMS_reg_CLK = (~bscan_DRCK) ;
    assign TMS_reg_RST = bscan_RESET ;
    assign TMS_reg_D0 = bscan_TDI ;
    assign TMS_reg_WE0 = ((shift_enable_wire == 1'd1) && (TCK_counter_reg_Q0 == 2'd2)) ;
    assign TDI_reg_CLK = (~bscan_DRCK) ;
    assign TDI_reg_RST = bscan_RESET ;
    assign TDI_reg_D0 = bscan_TDI ;
    assign TDI_reg_WE0 = ((shift_enable_wire == 1'd1) && (TCK_counter_reg_Q0 == 2'd1)) ;
    assign TDI_reg2_CLK = (~bscan_DRCK) ;
    assign TDI_reg2_RST = bscan_RESET ;
    assign TDI_reg2_D0 = bscan_TDI ;
    assign TCK_counter_reg_CLK = bscan_DRCK ;
    assign TCK_counter_reg_RST = bscan_RESET ;
    assign TCK_counter_reg_D0 = (TCK_counter_reg_Q0 + 2'd1) ;
    assign TCK_counter_reg_WE0 = shift_enable_wire ;
    assign TCK = TCK_buff_O ;
    assign TRST = bscan_RESET ;
    assign TMS = TMS_reg_Q0 ;
    assign TDI = TDI_reg_Q0 ;
endmodule



`timescale 1ns/1ps
module cpu0_ipgen_JtagBridge (
    input io_jtag_tms,
    input io_jtag_tdi,
    output io_jtag_tdo,
    input io_jtag_tck,
    output io_remote_cmd_valid,
    input io_remote_cmd_ready,
    output io_remote_cmd_payload_last,
    output [0:0] io_remote_cmd_payload_fragment,
    input io_remote_rsp_valid,
    output io_remote_rsp_ready,
    input io_remote_rsp_payload_error,
    input [31:0] io_remote_rsp_payload_data,
    input io_mainClk,
    input resetCtrl_mainClkReset) ;
    wire flowCCByToggle_1__io_output_valid ;
    wire flowCCByToggle_1__io_output_payload_last ;
    wire [0:0] flowCCByToggle_1__io_output_payload_fragment ;
    wire _zz_2_ ;
    wire _zz_3_ ;
    wire [3:0] _zz_4_ ;
    wire [3:0] _zz_5_ ;
    wire [3:0] _zz_6_ ;
    wire system_cmd_valid ;
    wire system_cmd_payload_last ;
    wire [0:0] system_cmd_payload_fragment ;
    reg system_rsp_valid ;
    reg system_rsp_payload_error ;
    reg [31:0] system_rsp_payload_data ;
    wire [3:0] jtag_tap_fsm_stateNext ;
    reg [3:0] jtag_tap_fsm_state = 4'b0000 ;
    reg [3:0] _zz_1_ ;
    reg [3:0] jtag_tap_instruction ;
    reg [3:0] jtag_tap_instructionShift ;
    reg jtag_tap_bypass ;
    reg jtag_tap_tdoUnbufferd ;
    reg jtag_tap_tdoUnbufferd_regNext ;
    wire [0:0] jtag_idcodeArea_instructionId ;
    wire jtag_idcodeArea_instructionHit ;
    reg [31:0] jtag_idcodeArea_shifter ;
    wire [1:0] jtag_writeArea_instructionId ;
    wire jtag_writeArea_instructionHit ;
    reg jtag_writeArea_source_valid ;
    wire jtag_writeArea_source_payload_last ;
    wire [0:0] jtag_writeArea_source_payload_fragment ;
    wire [1:0] jtag_readArea_instructionId ;
    wire jtag_readArea_instructionHit ;
    reg [33:0] jtag_readArea_shifter ;
    reg [79:0] jtag_tap_fsm_stateNext_string ;
    reg [79:0] jtag_tap_fsm_state_string ;
    reg [79:0] _zz_1__string ;
    assign _zz_2_ = (jtag_tap_fsm_state == 4'b1011) ;
    assign _zz_3_ = (jtag_tap_fsm_state == 4'b1011) ;
    assign _zz_4_ = {3'd0,
                jtag_idcodeArea_instructionId} ;
    assign _zz_5_ = {2'd0,
                jtag_writeArea_instructionId} ;
    assign _zz_6_ = {2'd0,
                jtag_readArea_instructionId} ;
    cpu0_ipgen_FlowCCByToggle flowCCByToggle_1_ (.io_input_valid(jtag_writeArea_source_valid),
                .io_input_payload_last(jtag_writeArea_source_payload_last),
                .io_input_payload_fragment(jtag_writeArea_source_payload_fragment),
                .io_output_valid(flowCCByToggle_1__io_output_valid),
                .io_output_payload_last(flowCCByToggle_1__io_output_payload_last),
                .io_output_payload_fragment(flowCCByToggle_1__io_output_payload_fragment),
                .io_jtag_tck(io_jtag_tck),
                .io_mainClk(io_mainClk),
                .resetCtrl_mainClkReset(resetCtrl_mainClkReset)) ;
    always
        @(*)
        begin
            case (jtag_tap_fsm_stateNext)
            4'b0000 :
                jtag_tap_fsm_stateNext_string = "RESET     " ;
            4'b0001 :
                jtag_tap_fsm_stateNext_string = "IDLE      " ;
            4'b0010 :
                jtag_tap_fsm_stateNext_string = "IR_SELECT " ;
            4'b0011 :
                jtag_tap_fsm_stateNext_string = "IR_CAPTURE" ;
            4'b0100 :
                jtag_tap_fsm_stateNext_string = "IR_SHIFT  " ;
            4'b0101 :
                jtag_tap_fsm_stateNext_string = "IR_EXIT1  " ;
            4'b0110 :
                jtag_tap_fsm_stateNext_string = "IR_PAUSE  " ;
            4'b0111 :
                jtag_tap_fsm_stateNext_string = "IR_EXIT2  " ;
            4'b1000 :
                jtag_tap_fsm_stateNext_string = "IR_UPDATE " ;
            4'b1001 :
                jtag_tap_fsm_stateNext_string = "DR_SELECT " ;
            4'b1010 :
                jtag_tap_fsm_stateNext_string = "DR_CAPTURE" ;
            4'b1011 :
                jtag_tap_fsm_stateNext_string = "DR_SHIFT  " ;
            4'b1100 :
                jtag_tap_fsm_stateNext_string = "DR_EXIT1  " ;
            4'b1101 :
                jtag_tap_fsm_stateNext_string = "DR_PAUSE  " ;
            4'b1110 :
                jtag_tap_fsm_stateNext_string = "DR_EXIT2  " ;
            4'b1111 :
                jtag_tap_fsm_stateNext_string = "DR_UPDATE " ;
            default :
                jtag_tap_fsm_stateNext_string = "??????????" ;
            endcase
        end
    always
        @(*)
        begin
            case (jtag_tap_fsm_state)
            4'b0000 :
                jtag_tap_fsm_state_string = "RESET     " ;
            4'b0001 :
                jtag_tap_fsm_state_string = "IDLE      " ;
            4'b0010 :
                jtag_tap_fsm_state_string = "IR_SELECT " ;
            4'b0011 :
