// Language: Verilog 2001
//`default_nettype none
/*
 * AXI4 register (write)
 */
module cpu0_ipgen_axi_register_wr #(parameter DATA_WIDTH = 32,
        parameter ADDR_WIDTH = 32,
        parameter STRB_WIDTH = (DATA_WIDTH / 8),
        parameter ID_WIDTH = 8,
        parameter AWUSER_ENABLE = 0,
        parameter AWUSER_WIDTH = 1,
        parameter WUSER_ENABLE = 0,
        parameter WUSER_WIDTH = 1,
        parameter BUSER_ENABLE = 0,
        parameter BUSER_WIDTH = 1,
        parameter AW_REG_TYPE = 1,
        parameter W_REG_TYPE = 2,
        parameter B_REG_TYPE = 1) (
    // Width of data bus in bits
    // Width of address bus in bits
    // Width of wstrb (width of data bus in words)
    // Width of ID signal
    // Propagate awuser signal
    // Width of awuser signal
    // Propagate wuser signal
    // Width of wuser signal
    // Propagate buser signal
    // Width of buser signal
    // AW channel register type
    // 0 to bypass, 1 for simple buffer, 2 for skid buffer
    // W channel register type
    // 0 to bypass, 1 for simple buffer, 2 for skid buffer
    // B channel register type
    // 0 to bypass, 1 for simple buffer, 2 for skid buffer
    input wire clk,
    input wire rst,
    /*
     * AXI slave interface
     */ input wire [(ID_WIDTH - 1):0] s_axi_awid,
    input wire [(ADDR_WIDTH - 1):0] s_axi_awaddr,
    input wire [7:0] s_axi_awlen,
    input wire [2:0] s_axi_awsize,
    input wire [1:0] s_axi_awburst,
    input wire s_axi_awlock,
    input wire [3:0] s_axi_awcache,
    input wire [2:0] s_axi_awprot,
    input wire [3:0] s_axi_awqos,
    input wire [3:0] s_axi_awregion,
    input wire [(AWUSER_WIDTH - 1):0] s_axi_awuser,
    input wire s_axi_awvalid,
    output wire s_axi_awready,
    input wire [(DATA_WIDTH - 1):0] s_axi_wdata,
    input wire [(STRB_WIDTH - 1):0] s_axi_wstrb,
    input wire s_axi_wlast,
    input wire [(WUSER_WIDTH - 1):0] s_axi_wuser,
    input wire s_axi_wvalid,
    output wire s_axi_wready,
    output wire [(ID_WIDTH - 1):0] s_axi_bid,
    output wire [1:0] s_axi_bresp,
    output wire [(BUSER_WIDTH - 1):0] s_axi_buser,
    output wire s_axi_bvalid,
    input wire s_axi_bready,
    /*
     * AXI master interface
     */ output wire [(ID_WIDTH - 1):0] m_axi_awid,
    output wire [(ADDR_WIDTH - 1):0] m_axi_awaddr,
    output wire [7:0] m_axi_awlen,
    output wire [2:0] m_axi_awsize,
    output wire [1:0] m_axi_awburst,
    output wire m_axi_awlock,
    output wire [3:0] m_axi_awcache,
    output wire [2:0] m_axi_awprot,
    output wire [3:0] m_axi_awqos,
    output wire [3:0] m_axi_awregion,
    output wire [(AWUSER_WIDTH - 1):0] m_axi_awuser,
    output wire m_axi_awvalid,
    input wire m_axi_awready,
    output wire [(DATA_WIDTH - 1):0] m_axi_wdata,
    output wire [(STRB_WIDTH - 1):0] m_axi_wstrb,
    output wire m_axi_wlast,
    output wire [(WUSER_WIDTH - 1):0] m_axi_wuser,
    output wire m_axi_wvalid,
    input wire m_axi_wready,
    input wire [(ID_WIDTH - 1):0] m_axi_bid,
    input wire [1:0] m_axi_bresp,
    input wire [(BUSER_WIDTH - 1):0] m_axi_buser,
    input wire m_axi_bvalid,
    output wire m_axi_bready) ;
    generate
        // AW channel
        if ((AW_REG_TYPE > 1))
            begin : genblk1
                // skid buffer, no bubble cycles
                // datapath registers
                reg s_axi_awready_reg = 1'b0 ;
                reg [(ID_WIDTH - 1):0] m_axi_awid_reg = {ID_WIDTH{1'b0}} ;
                reg [(ADDR_WIDTH - 1):0] m_axi_awaddr_reg = {ADDR_WIDTH{1'b0}} ;
                reg [7:0] m_axi_awlen_reg = 8'd0 ;
                reg [2:0] m_axi_awsize_reg = 3'd0 ;
                reg [1:0] m_axi_awburst_reg = 2'd0 ;
                reg m_axi_awlock_reg = 1'b0 ;
                reg [3:0] m_axi_awcache_reg = 4'd0 ;
                reg [2:0] m_axi_awprot_reg = 3'd0 ;
                reg [3:0] m_axi_awqos_reg = 4'd0 ;
                reg [3:0] m_axi_awregion_reg = 4'd0 ;
                reg [(AWUSER_WIDTH - 1):0] m_axi_awuser_reg = {AWUSER_WIDTH{1'b0}} ;
                reg m_axi_awvalid_reg = 1'b0,
                    m_axi_awvalid_next ;
                reg [(ID_WIDTH - 1):0] temp_m_axi_awid_reg = {ID_WIDTH{1'b0}} ;
                reg [(ADDR_WIDTH - 1):0] temp_m_axi_awaddr_reg = {ADDR_WIDTH{1'b0}} ;
                reg [7:0] temp_m_axi_awlen_reg = 8'd0 ;
                reg [2:0] temp_m_axi_awsize_reg = 3'd0 ;
                reg [1:0] temp_m_axi_awburst_reg = 2'd0 ;
                reg temp_m_axi_awlock_reg = 1'b0 ;
                reg [3:0] temp_m_axi_awcache_reg = 4'd0 ;
                reg [2:0] temp_m_axi_awprot_reg = 3'd0 ;
                reg [3:0] temp_m_axi_awqos_reg = 4'd0 ;
                reg [3:0] temp_m_axi_awregion_reg = 4'd0 ;
                reg [(AWUSER_WIDTH - 1):0] temp_m_axi_awuser_reg = {AWUSER_WIDTH{1'b0}} ;
                reg temp_m_axi_awvalid_reg = 1'b0,
                    temp_m_axi_awvalid_next ;
                // datapath control
                reg store_axi_aw_input_to_output ;
                reg store_axi_aw_input_to_temp ;
                reg store_axi_aw_temp_to_output ;
                assign s_axi_awready = s_axi_awready_reg ;
                assign m_axi_awid = m_axi_awid_reg ;
                assign m_axi_awaddr = m_axi_awaddr_reg ;
                assign m_axi_awlen = m_axi_awlen_reg ;
                assign m_axi_awsize = m_axi_awsize_reg ;
                assign m_axi_awburst = m_axi_awburst_reg ;
                assign m_axi_awlock = m_axi_awlock_reg ;
                assign m_axi_awcache = m_axi_awcache_reg ;
                assign m_axi_awprot = m_axi_awprot_reg ;
                assign m_axi_awqos = m_axi_awqos_reg ;
                assign m_axi_awregion = m_axi_awregion_reg ;
                assign m_axi_awuser = (AWUSER_ENABLE ? m_axi_awuser_reg : {AWUSER_WIDTH{1'b0}}) ;
                assign m_axi_awvalid = m_axi_awvalid_reg ;
                // enable ready input next cycle if output is ready or the temp reg will not be filled on the next cycle (output reg empty or no input)
                wire s_axi_awready_early = (m_axi_awready | ((~temp_m_axi_awvalid_reg) & ((~m_axi_awvalid_reg) | (~s_axi_awvalid)))) ;
                always
                    @(*)
                    begin
                        // transfer sink ready state to source
                        m_axi_awvalid_next = m_axi_awvalid_reg ;
                        temp_m_axi_awvalid_next = temp_m_axi_awvalid_reg ;
                        store_axi_aw_input_to_output = 1'b0 ;
                        store_axi_aw_input_to_temp = 1'b0 ;
                        store_axi_aw_temp_to_output = 1'b0 ;
                        if (s_axi_awready_reg)
                            begin
                                // input is ready
                                if ((m_axi_awready | (~m_axi_awvalid_reg)))
                                    begin
                                        // output is ready or currently not valid, transfer data to output
                                        m_axi_awvalid_next = s_axi_awvalid ;
                                        store_axi_aw_input_to_output = 1'b1 ;
                                    end
                                else
                                    begin
                                        // output is not ready, store input in temp
                                        temp_m_axi_awvalid_next = s_axi_awvalid ;
                                        store_axi_aw_input_to_temp = 1'b1 ;
                                    end
                            end
                        else
                            if (m_axi_awready)
                                begin
                                    // input is not ready, but output is ready
                                    m_axi_awvalid_next = temp_m_axi_awvalid_reg ;
                                    temp_m_axi_awvalid_next = 1'b0 ;
                                    store_axi_aw_temp_to_output = 1'b1 ;
                                end
                    end
                always
                    @(posedge clk)
                    begin
                        if (rst)
                            begin
                                s_axi_awready_reg <=  1'b0 ;
                                m_axi_awvalid_reg <=  1'b0 ;
                                temp_m_axi_awvalid_reg <=  1'b0 ;
                            end
                        else
                            begin
                                s_axi_awready_reg <=  s_axi_awready_early ;
                                m_axi_awvalid_reg <=  m_axi_awvalid_next ;
                                temp_m_axi_awvalid_reg <=  temp_m_axi_awvalid_next ;
                            end
                        // datapath
                        if (store_axi_aw_input_to_output)
                            begin
                                m_axi_awid_reg <=  s_axi_awid ;
                                m_axi_awaddr_reg <=  s_axi_awaddr ;
                                m_axi_awlen_reg <=  s_axi_awlen ;
                                m_axi_awsize_reg <=  s_axi_awsize ;
                                m_axi_awburst_reg <=  s_axi_awburst ;
                                m_axi_awlock_reg <=  s_axi_awlock ;
                                m_axi_awcache_reg <=  s_axi_awcache ;
                                m_axi_awprot_reg <=  s_axi_awprot ;
                                m_axi_awqos_reg <=  s_axi_awqos ;
                                m_axi_awregion_reg <=  s_axi_awregion ;
                                m_axi_awuser_reg <=  s_axi_awuser ;
                            end
                        else
                            if (store_axi_aw_temp_to_output)
                                begin
                                    m_axi_awid_reg <=  temp_m_axi_awid_reg ;
                                    m_axi_awaddr_reg <=  temp_m_axi_awaddr_reg ;
                                    m_axi_awlen_reg <=  temp_m_axi_awlen_reg ;
                                    m_axi_awsize_reg <=  temp_m_axi_awsize_reg ;
                                    m_axi_awburst_reg <=  temp_m_axi_awburst_reg ;
                                    m_axi_awlock_reg <=  temp_m_axi_awlock_reg ;
                                    m_axi_awcache_reg <=  temp_m_axi_awcache_reg ;
                                    m_axi_awprot_reg <=  temp_m_axi_awprot_reg ;
                                    m_axi_awqos_reg <=  temp_m_axi_awqos_reg ;
                                    m_axi_awregion_reg <=  temp_m_axi_awregion_reg ;
                                    m_axi_awuser_reg <=  temp_m_axi_awuser_reg ;
                                end
                        if (store_axi_aw_input_to_temp)
                            begin
                                temp_m_axi_awid_reg <=  s_axi_awid ;
                                temp_m_axi_awaddr_reg <=  s_axi_awaddr ;
                                temp_m_axi_awlen_reg <=  s_axi_awlen ;
                                temp_m_axi_awsize_reg <=  s_axi_awsize ;
                                temp_m_axi_awburst_reg <=  s_axi_awburst ;
                                temp_m_axi_awlock_reg <=  s_axi_awlock ;
                                temp_m_axi_awcache_reg <=  s_axi_awcache ;
                                temp_m_axi_awprot_reg <=  s_axi_awprot ;
                                temp_m_axi_awqos_reg <=  s_axi_awqos ;
                                temp_m_axi_awregion_reg <=  s_axi_awregion ;
                                temp_m_axi_awuser_reg <=  s_axi_awuser ;
                            end
                    end
            end
        else
            if ((AW_REG_TYPE == 1))
                begin : genblk1
                    // simple register, inserts bubble cycles
                    // datapath registers
                    reg s_axi_awready_reg = 1'b0 ;
                    reg [(ID_WIDTH - 1):0] m_axi_awid_reg = {ID_WIDTH{1'b0}} ;
                    reg [(ADDR_WIDTH - 1):0] m_axi_awaddr_reg = {ADDR_WIDTH{1'b0}} ;
                    reg [7:0] m_axi_awlen_reg = 8'd0 ;
                    reg [2:0] m_axi_awsize_reg = 3'd0 ;
                    reg [1:0] m_axi_awburst_reg = 2'd0 ;
                    reg m_axi_awlock_reg = 1'b0 ;
                    reg [3:0] m_axi_awcache_reg = 4'd0 ;
                    reg [2:0] m_axi_awprot_reg = 3'd0 ;
                    reg [3:0] m_axi_awqos_reg = 4'd0 ;
                    reg [3:0] m_axi_awregion_reg = 4'd0 ;
                    reg [(AWUSER_WIDTH - 1):0] m_axi_awuser_reg = {AWUSER_WIDTH{1'b0}} ;
                    reg m_axi_awvalid_reg = 1'b0,
                        m_axi_awvalid_next ;
                    // datapath control
                    reg store_axi_aw_input_to_output ;
                    assign s_axi_awready = s_axi_awready_reg ;
                    assign m_axi_awid = m_axi_awid_reg ;
                    assign m_axi_awaddr = m_axi_awaddr_reg ;
                    assign m_axi_awlen = m_axi_awlen_reg ;
                    assign m_axi_awsize = m_axi_awsize_reg ;
                    assign m_axi_awburst = m_axi_awburst_reg ;
                    assign m_axi_awlock = m_axi_awlock_reg ;
                    assign m_axi_awcache = m_axi_awcache_reg ;
                    assign m_axi_awprot = m_axi_awprot_reg ;
                    assign m_axi_awqos = m_axi_awqos_reg ;
                    assign m_axi_awregion = m_axi_awregion_reg ;
                    assign m_axi_awuser = (AWUSER_ENABLE ? m_axi_awuser_reg : {AWUSER_WIDTH{1'b0}}) ;
                    assign m_axi_awvalid = m_axi_awvalid_reg ;
                    // enable ready input next cycle if output buffer will be empty
                    wire s_axi_awready_eawly = (!m_axi_awvalid_next) ;
                    always
                        @(*)
                        begin
                            // transfer sink ready state to source
                            m_axi_awvalid_next = m_axi_awvalid_reg ;
                            store_axi_aw_input_to_output = 1'b0 ;
                            if (s_axi_awready_reg)
                                begin
                                    m_axi_awvalid_next = s_axi_awvalid ;
                                    store_axi_aw_input_to_output = 1'b1 ;
                                end
                            else
                                if (m_axi_awready)
                                    begin
                                        m_axi_awvalid_next = 1'b0 ;
                                    end
                        end
                    always
                        @(posedge clk)
                        begin
                            if (rst)
                                begin
                                    s_axi_awready_reg <=  1'b0 ;
                                    m_axi_awvalid_reg <=  1'b0 ;
                                end
                            else
                                begin
                                    s_axi_awready_reg <=  s_axi_awready_eawly ;
                                    m_axi_awvalid_reg <=  m_axi_awvalid_next ;
                                end
                            // datapath
                            if (store_axi_aw_input_to_output)
                                begin
                                    m_axi_awid_reg <=  s_axi_awid ;
                                    m_axi_awaddr_reg <=  s_axi_awaddr ;
                                    m_axi_awlen_reg <=  s_axi_awlen ;
                                    m_axi_awsize_reg <=  s_axi_awsize ;
                                    m_axi_awburst_reg <=  s_axi_awburst ;
                                    m_axi_awlock_reg <=  s_axi_awlock ;
                                    m_axi_awcache_reg <=  s_axi_awcache ;
                                    m_axi_awprot_reg <=  s_axi_awprot ;
                                    m_axi_awqos_reg <=  s_axi_awqos ;
                                    m_axi_awregion_reg <=  s_axi_awregion ;
                                    m_axi_awuser_reg <=  s_axi_awuser ;
                                end
                        end
                end
            else
                begin : genblk1
                    // bypass AW channel
                    assign m_axi_awid = s_axi_awid ;
                    assign m_axi_awaddr = s_axi_awaddr ;
                    assign m_axi_awlen = s_axi_awlen ;
                    assign m_axi_awsize = s_axi_awsize ;
                    assign m_axi_awburst = s_axi_awburst ;
                    assign m_axi_awlock = s_axi_awlock ;
                    assign m_axi_awcache = s_axi_awcache ;
                    assign m_axi_awprot = s_axi_awprot ;
                    assign m_axi_awqos = s_axi_awqos ;
                    assign m_axi_awregion = s_axi_awregion ;
                    assign m_axi_awuser = (AWUSER_ENABLE ? s_axi_awuser : {AWUSER_WIDTH{1'b0}}) ;
                    assign m_axi_awvalid = s_axi_awvalid ;
                    assign s_axi_awready = m_axi_awready ;
                end
        // W channel
        if ((W_REG_TYPE > 1))
            begin : genblk2
                // skid buffer, no bubble cycles
                // datapath registers
                reg s_axi_wready_reg = 1'b0 ;
                reg [(DATA_WIDTH - 1):0] m_axi_wdata_reg = {DATA_WIDTH{1'b0}} ;
                reg [(STRB_WIDTH - 1):0] m_axi_wstrb_reg = {STRB_WIDTH{1'b0}} ;
                reg m_axi_wlast_reg = 1'b0 ;
                reg [(WUSER_WIDTH - 1):0] m_axi_wuser_reg = {WUSER_WIDTH{1'b0}} ;
                reg m_axi_wvalid_reg = 1'b0,
                    m_axi_wvalid_next ;
                reg [(DATA_WIDTH - 1):0] temp_m_axi_wdata_reg = {DATA_WIDTH{1'b0}} ;
                reg [(STRB_WIDTH - 1):0] temp_m_axi_wstrb_reg = {STRB_WIDTH{1'b0}} ;
                reg temp_m_axi_wlast_reg = 1'b0 ;
                reg [(WUSER_WIDTH - 1):0] temp_m_axi_wuser_reg = {WUSER_WIDTH{1'b0}} ;
                reg temp_m_axi_wvalid_reg = 1'b0,
                    temp_m_axi_wvalid_next ;
                // datapath control
                reg store_axi_w_input_to_output ;
                reg store_axi_w_input_to_temp ;
                reg store_axi_w_temp_to_output ;
                assign s_axi_wready = s_axi_wready_reg ;
                assign m_axi_wdata = m_axi_wdata_reg ;
                assign m_axi_wstrb = m_axi_wstrb_reg ;
                assign m_axi_wlast = m_axi_wlast_reg ;
                assign m_axi_wuser = (WUSER_ENABLE ? m_axi_wuser_reg : {WUSER_WIDTH{1'b0}}) ;
                assign m_axi_wvalid = m_axi_wvalid_reg ;
                // enable ready input next cycle if output is ready or the temp reg will not be filled on the next cycle (output reg empty or no input)
                wire s_axi_wready_early = (m_axi_wready | ((~temp_m_axi_wvalid_reg) & ((~m_axi_wvalid_reg) | (~s_axi_wvalid)))) ;
                always
                    @(*)
                    begin
                        // transfer sink ready state to source
                        m_axi_wvalid_next = m_axi_wvalid_reg ;
                        temp_m_axi_wvalid_next = temp_m_axi_wvalid_reg ;
                        store_axi_w_input_to_output = 1'b0 ;
                        store_axi_w_input_to_temp = 1'b0 ;
                        store_axi_w_temp_to_output = 1'b0 ;
                        if (s_axi_wready_reg)
                            begin
                                // input is ready
                                if ((m_axi_wready | (~m_axi_wvalid_reg)))
                                    begin
                                        // output is ready or currently not valid, transfer data to output
                                        m_axi_wvalid_next = s_axi_wvalid ;
                                        store_axi_w_input_to_output = 1'b1 ;
                                    end
                                else
                                    begin
                                        // output is not ready, store input in temp
                                        temp_m_axi_wvalid_next = s_axi_wvalid ;
                                        store_axi_w_input_to_temp = 1'b1 ;
                                    end
                            end
                        else
                            if (m_axi_wready)
                                begin
                                    // input is not ready, but output is ready
                                    m_axi_wvalid_next = temp_m_axi_wvalid_reg ;
                                    temp_m_axi_wvalid_next = 1'b0 ;
                                    store_axi_w_temp_to_output = 1'b1 ;
                                end
                    end
                always
                    @(posedge clk)
                    begin
                        if (rst)
                            begin
                                s_axi_wready_reg <=  1'b0 ;
                                m_axi_wvalid_reg <=  1'b0 ;
                                temp_m_axi_wvalid_reg <=  1'b0 ;
                            end
                        else
                            begin
                                s_axi_wready_reg <=  s_axi_wready_early ;
                                m_axi_wvalid_reg <=  m_axi_wvalid_next ;
                                temp_m_axi_wvalid_reg <=  temp_m_axi_wvalid_next ;
                            end
                        // datapath
                        if (store_axi_w_input_to_output)
                            begin
                                m_axi_wdata_reg <=  s_axi_wdata ;
                                m_axi_wstrb_reg <=  s_axi_wstrb ;
                                m_axi_wlast_reg <=  s_axi_wlast ;
                                m_axi_wuser_reg <=  s_axi_wuser ;
                            end
                        else
                            if (store_axi_w_temp_to_output)
                                begin
                                    m_axi_wdata_reg <=  temp_m_axi_wdata_reg ;
                                    m_axi_wstrb_reg <=  temp_m_axi_wstrb_reg ;
                                    m_axi_wlast_reg <=  temp_m_axi_wlast_reg ;
                                    m_axi_wuser_reg <=  temp_m_axi_wuser_reg ;
                                end
                        if (store_axi_w_input_to_temp)
                            begin
                                temp_m_axi_wdata_reg <=  s_axi_wdata ;
                                temp_m_axi_wstrb_reg <=  s_axi_wstrb ;
                                temp_m_axi_wlast_reg <=  s_axi_wlast ;
                                temp_m_axi_wuser_reg <=  s_axi_wuser ;
                            end
                    end
            end
        else
            if ((W_REG_TYPE == 1))
                begin : genblk2
                    // simple register, inserts bubble cycles
                    // datapath registers
                    reg s_axi_wready_reg = 1'b0 ;
                    reg [(DATA_WIDTH - 1):0] m_axi_wdata_reg = {DATA_WIDTH{1'b0}} ;
                    reg [(STRB_WIDTH - 1):0] m_axi_wstrb_reg = {STRB_WIDTH{1'b0}} ;
                    reg m_axi_wlast_reg = 1'b0 ;
                    reg [(WUSER_WIDTH - 1):0] m_axi_wuser_reg = {WUSER_WIDTH{1'b0}} ;
                    reg m_axi_wvalid_reg = 1'b0,
                        m_axi_wvalid_next ;
                    // datapath control
                    reg store_axi_w_input_to_output ;
                    assign s_axi_wready = s_axi_wready_reg ;
                    assign m_axi_wdata = m_axi_wdata_reg ;
                    assign m_axi_wstrb = m_axi_wstrb_reg ;
                    assign m_axi_wlast = m_axi_wlast_reg ;
                    assign m_axi_wuser = (WUSER_ENABLE ? m_axi_wuser_reg : {WUSER_WIDTH{1'b0}}) ;
                    assign m_axi_wvalid = m_axi_wvalid_reg ;
                    // enable ready input next cycle if output buffer will be empty
                    wire s_axi_wready_ewly = (!m_axi_wvalid_next) ;
                    always
                        @(*)
                        begin
                            // transfer sink ready state to source
                            m_axi_wvalid_next = m_axi_wvalid_reg ;
                            store_axi_w_input_to_output = 1'b0 ;
                            if (s_axi_wready_reg)
                                begin
                                    m_axi_wvalid_next = s_axi_wvalid ;
                                    store_axi_w_input_to_output = 1'b1 ;
                                end
                            else
                                if (m_axi_wready)
                                    begin
                                        m_axi_wvalid_next = 1'b0 ;
                                    end
                        end
                    always
                        @(posedge clk)
                        begin
                            if (rst)
                                begin
                                    s_axi_wready_reg <=  1'b0 ;
                                    m_axi_wvalid_reg <=  1'b0 ;
                                end
                            else
                                begin
                                    s_axi_wready_reg <=  s_axi_wready_ewly ;
                                    m_axi_wvalid_reg <=  m_axi_wvalid_next ;
                                end
                            // datapath
                            if (store_axi_w_input_to_output)
                                begin
                                    m_axi_wdata_reg <=  s_axi_wdata ;
                                    m_axi_wstrb_reg <=  s_axi_wstrb ;
                                    m_axi_wlast_reg <=  s_axi_wlast ;
                                    m_axi_wuser_reg <=  s_axi_wuser ;
                                end
                        end
                end
            else
                begin : genblk2
                    // bypass W channel
                    assign m_axi_wdata = s_axi_wdata ;
                    assign m_axi_wstrb = s_axi_wstrb ;
                    assign m_axi_wlast = s_axi_wlast ;
                    assign m_axi_wuser = (WUSER_ENABLE ? s_axi_wuser : {WUSER_WIDTH{1'b0}}) ;
                    assign m_axi_wvalid = s_axi_wvalid ;
                    assign s_axi_wready = m_axi_wready ;
                end
        // B channel
        if ((B_REG_TYPE > 1))
            begin : genblk3
                // skid buffer, no bubble cycles
                // datapath registers
                reg m_axi_bready_reg = 1'b0 ;
                reg [(ID_WIDTH - 1):0] s_axi_bid_reg = {ID_WIDTH{1'b0}} ;
                reg [1:0] s_axi_bresp_reg = 2'b0 ;
                reg [(BUSER_WIDTH - 1):0] s_axi_buser_reg = {BUSER_WIDTH{1'b0}} ;
                reg s_axi_bvalid_reg = 1'b0,
                    s_axi_bvalid_next ;
                reg [(ID_WIDTH - 1):0] temp_s_axi_bid_reg = {ID_WIDTH{1'b0}} ;
                reg [1:0] temp_s_axi_bresp_reg = 2'b0 ;
                reg [(BUSER_WIDTH - 1):0] temp_s_axi_buser_reg = {BUSER_WIDTH{1'b0}} ;
                reg temp_s_axi_bvalid_reg = 1'b0,
                    temp_s_axi_bvalid_next ;
                // datapath control
                reg store_axi_b_input_to_output ;
                reg store_axi_b_input_to_temp ;
                reg store_axi_b_temp_to_output ;
                assign m_axi_bready = m_axi_bready_reg ;
                assign s_axi_bid = s_axi_bid_reg ;
                assign s_axi_bresp = s_axi_bresp_reg ;
                assign s_axi_buser = (BUSER_ENABLE ? s_axi_buser_reg : {BUSER_WIDTH{1'b0}}) ;
                assign s_axi_bvalid = s_axi_bvalid_reg ;
                // enable ready input next cycle if output is ready or the temp reg will not be filled on the next cycle (output reg empty or no input)
                wire m_axi_bready_early = (s_axi_bready | ((~temp_s_axi_bvalid_reg) & ((~s_axi_bvalid_reg) | (~m_axi_bvalid)))) ;
                always
                    @(*)
                    begin
                        // transfer sink ready state to source
                        s_axi_bvalid_next = s_axi_bvalid_reg ;
                        temp_s_axi_bvalid_next = temp_s_axi_bvalid_reg ;
                        store_axi_b_input_to_output = 1'b0 ;
                        store_axi_b_input_to_temp = 1'b0 ;
                        store_axi_b_temp_to_output = 1'b0 ;
                        if (m_axi_bready_reg)
                            begin
                                // input is ready
                                if ((s_axi_bready | (~s_axi_bvalid_reg)))
                                    begin
                                        // output is ready or currently not valid, transfer data to output
                                        s_axi_bvalid_next = m_axi_bvalid ;
                                        store_axi_b_input_to_output = 1'b1 ;
                                    end
                                else
                                    begin
                                        // output is not ready, store input in temp
                                        temp_s_axi_bvalid_next = m_axi_bvalid ;
                                        store_axi_b_input_to_temp = 1'b1 ;
                                    end
                            end
                        else
                            if (s_axi_bready)
                                begin
                                    // input is not ready, but output is ready
                                    s_axi_bvalid_next = temp_s_axi_bvalid_reg ;
                                    temp_s_axi_bvalid_next = 1'b0 ;
                                    store_axi_b_temp_to_output = 1'b1 ;
                                end
                    end
                always
                    @(posedge clk)
                    begin
                        if (rst)
                            begin
                                m_axi_bready_reg <=  1'b0 ;
                                s_axi_bvalid_reg <=  1'b0 ;
                                temp_s_axi_bvalid_reg <=  1'b0 ;
                            end
                        else
                            begin
                                m_axi_bready_reg <=  m_axi_bready_early ;
                                s_axi_bvalid_reg <=  s_axi_bvalid_next ;
                                temp_s_axi_bvalid_reg <=  temp_s_axi_bvalid_next ;
                            end
                        // datapath
                        if (store_axi_b_input_to_output)
                            begin
                                s_axi_bid_reg <=  m_axi_bid ;
                                s_axi_bresp_reg <=  m_axi_bresp ;
                                s_axi_buser_reg <=  m_axi_buser ;
                            end
                        else
                            if (store_axi_b_temp_to_output)
                                begin
                                    s_axi_bid_reg <=  temp_s_axi_bid_reg ;
                                    s_axi_bresp_reg <=  temp_s_axi_bresp_reg ;
                                    s_axi_buser_reg <=  temp_s_axi_buser_reg ;
                                end
                        if (store_axi_b_input_to_temp)
                            begin
                                temp_s_axi_bid_reg <=  m_axi_bid ;
                                temp_s_axi_bresp_reg <=  m_axi_bresp ;
                                temp_s_axi_buser_reg <=  m_axi_buser ;
                            end
                    end
            end
        else
            if ((B_REG_TYPE == 1))
                begin : genblk3
                    // simple register, inserts bubble cycles
                    // datapath registers
                    reg m_axi_bready_reg = 1'b0 ;
                    reg [(ID_WIDTH - 1):0] s_axi_bid_reg = {ID_WIDTH{1'b0}} ;
                    reg [1:0] s_axi_bresp_reg = 2'b0 ;
                    reg [(BUSER_WIDTH - 1):0] s_axi_buser_reg = {BUSER_WIDTH{1'b0}} ;
                    reg s_axi_bvalid_reg = 1'b0,
                        s_axi_bvalid_next ;
                    // datapath control
                    reg store_axi_b_input_to_output ;
                    assign m_axi_bready = m_axi_bready_reg ;
                    assign s_axi_bid = s_axi_bid_reg ;
                    assign s_axi_bresp = s_axi_bresp_reg ;
                    assign s_axi_buser = (BUSER_ENABLE ? s_axi_buser_reg : {BUSER_WIDTH{1'b0}}) ;
                    assign s_axi_bvalid = s_axi_bvalid_reg ;
                    // enable ready input next cycle if output buffer will be empty
                    wire m_axi_bready_early = (!s_axi_bvalid_next) ;
                    always
                        @(*)
                        begin
                            // transfer sink ready state to source
                            s_axi_bvalid_next = s_axi_bvalid_reg ;
                            store_axi_b_input_to_output = 1'b0 ;
                            if (m_axi_bready_reg)
                                begin
                                    s_axi_bvalid_next = m_axi_bvalid ;
                                    store_axi_b_input_to_output = 1'b1 ;
                                end
                            else
                                if (s_axi_bready)
                                    begin
                                        s_axi_bvalid_next = 1'b0 ;
                                    end
                        end
                    always
                        @(posedge clk)
                        begin
                            if (rst)
                                begin
                                    m_axi_bready_reg <=  1'b0 ;
                                    s_axi_bvalid_reg <=  1'b0 ;
                                end
                            else
                                begin
                                    m_axi_bready_reg <=  m_axi_bready_early ;
                                    s_axi_bvalid_reg <=  s_axi_bvalid_next ;
                                end
                            // datapath
                            if (store_axi_b_input_to_output)
                                begin
                                    s_axi_bid_reg <=  m_axi_bid ;
                                    s_axi_bresp_reg <=  m_axi_bresp ;
                                    s_axi_buser_reg <=  m_axi_buser ;
                                end
                        end
                end
            else
                begin : genblk3
                    // bypass B channel
                    assign s_axi_bid = m_axi_bid ;
                    assign s_axi_bresp = m_axi_bresp ;
                    assign s_axi_buser = (BUSER_ENABLE ? m_axi_buser : {BUSER_WIDTH{1'b0}}) ;
                    assign s_axi_bvalid = m_axi_bvalid ;
                    assign m_axi_bready = s_axi_bready ;
                end
    endgenerate
endmodule



`resetall
//Author:Pengfei Zhao PengLiu
//Date:10/13/2022
//Component:dbus2axi
//Version:2011.1
module cpu0_ipgen_dbus2axi #(parameter AXI_ID_WIDTH = 1,
        parameter AXI_ID_NUM = 0,
        parameter MODE = "Balanced") (
    input clk,
    input rst_n,
    //dbus interface
    input dBus_cmd_valid,
    output dBus_cmd_ready,
    input dBus_cmd_payload_wr,
    input dBus_cmd_payload_uncached,
    input [31:0] dBus_cmd_payload_address,
    input [31:0] dBus_cmd_payload_data,
    input [3:0] dBus_cmd_payload_mask,
    input [2:0] dBus_cmd_payload_size,
    input dBus_cmd_payload_last,
    output dBus_rsp_valid,
    output dBus_rsp_payload_last,
    output [31:0] dBus_rsp_payload_data,
    output dBus_rsp_payload_error,
    //AXI interface
    output [2:0] awsize_o,
    output [1:0] awburst_o,
    output awlock_o,
    output [3:0] awcache_o,
    output [2:0] awprot_o,
    output [3:0] awqos_o,
    output [3:0] awregion_o,
    output awuser_o,
    output [2:0] arsize_o,
    output [1:0] arburst_o,
    output arlock_o,
    output [3:0] arcache_o,
    output [2:0] arprot_o,
    output [3:0] arqos_o,
    output [3:0] arregion_o,
    output aruser_o,
    output wuser_o,
    input buser_i,
    input ruser_i,
    output [31:0] awaddr_o,
    output [(AXI_ID_WIDTH - 1):0] awid_o,
    output [7:0] awlen_o,
    output awvalid_o,
    input awready_i,
    output [31:0] wdata_o,
    output [3:0] wstrb_o,
    output wlast_o,
    output wvalid_o,
    input wready_i,
    input [(AXI_ID_WIDTH - 1):0] bid_i,
    input [1:0] bresp_i,
    input bvalid_i,
    output bready_o,
    output [31:0] araddr_o,
    output [(AXI_ID_WIDTH - 1):0] arid_o,
    output [7:0] arlen_o,
    output arvalid_o,
    input arready_i,
    input [31:0] rdata_i,
    input [(AXI_ID_WIDTH - 1):0] rid_i,
    input [1:0] rresp_i,
    input rlast_i,
    input rvalid_i,
    output rready_o) ;
    reg awr_fire_window ;
    reg w_fire_window ;
    reg r_fire_window ;
    wire cmd_fire ;
    wire rsp_fire ;
    reg awrvalid_r ;
    reg [1:0] wrvalid_r ; //bit1 for b channel, bit0 for w channel
    reg rvalid_r ;
    wire awrready ;
    wire wready ;
    //prots with constant value
    assign awuser_o = 1'b0 ;
    assign wuser_o = 1'b0 ;
    assign awburst_o = 2'b01 ;
    assign arburst_o = 2'b01 ;
    assign awlock_o = 1'b0 ;
    assign arlock_o = 1'b0 ;
    assign awprot_o = 3'b010 ;
    assign arprot_o = 3'b010 ;
    assign awcache_o = 4'b1111 ;
    assign arcache_o = 4'b1111 ;
    assign awqos_o = 4'b0000 ;
    assign arqos_o = 4'b0000 ;
    assign awregion_o = 4'b0000 ;
    assign arregion_o = 4'b0000 ;
    assign awid_o = AXI_ID_NUM ;
    assign arid_o = AXI_ID_NUM ;
    assign rready_o = 1'b1 ;
    assign bready_o = 1'b1 ;
    //direct assign ports
    assign wdata_o = dBus_cmd_payload_data ;
    assign wlast_o = dBus_cmd_payload_last ;
    assign dBus_rsp_valid = (rvalid_i || (wrvalid_r == 2'b10)) ;
    assign dBus_rsp_payload_last = (rlast_i || (wrvalid_r == 2'b10)) ;
    assign dBus_rsp_payload_data = rdata_i ;
    //address
    assign awaddr_o = dBus_cmd_payload_address ;
    assign araddr_o = dBus_cmd_payload_address ;
    //size
    assign awsize_o = ((dBus_cmd_payload_size == 3'b101) ? 3'b010 : dBus_cmd_payload_size) ;
    assign arsize_o = ((dBus_cmd_payload_size == 3'b101) ? 3'b010 : dBus_cmd_payload_size) ;
    assign wstrb_o = dBus_cmd_payload_mask ;
    //error resp = 10 || 11
    assign dBus_rsp_payload_error = (((rresp_i[1] == 1) && rvalid_i) || (wrvalid_r[1] && (bresp_i[1] == 1))) ;
    //len
    assign awlen_o = ((dBus_cmd_payload_size == 3'b101) ? 8'b111 : 8'b000) ;
    assign arlen_o = ((dBus_cmd_payload_size == 3'b101) ? 8'b111 : 8'b000) ;
    //address valid
    assign awvalid_o = (awr_fire_window && dBus_cmd_payload_wr) ;
    assign wvalid_o = (w_fire_window && dBus_cmd_payload_wr) ;
    assign arvalid_o = (awr_fire_window && (!dBus_cmd_payload_wr)) ;
    always
        @(*)
        begin
            awr_fire_window = dBus_cmd_valid ;
            if (awrvalid_r)
                awr_fire_window = 1'b0 ;
        end
    always
        @(*)
        begin
            w_fire_window = dBus_cmd_valid ;
            if (((wrvalid_r == 2'b01) || (wrvalid_r == 2'b10)))
                //if (wrvalid_r[0])
                w_fire_window = 1'b0 ;
        end
    //ready
    assign awrready = (dBus_cmd_payload_wr ? awready_i : arready_i) ;
    assign wready = (dBus_cmd_payload_wr ? wready_i : 1'b0) ;
    //for write: both aw, w and b fires; for read, ar fires.
    assign cmd_fire = (wrvalid_r[1] || (awrvalid_r && (!dBus_cmd_payload_wr))) ;
    assign rsp_fire = (rvalid_i && rlast_i) ;
    always
        @(posedge clk or
            negedge rst_n)
        begin
            if ((!rst_n))
                awrvalid_r <=  1'b0 ;
            else
                if (((dBus_cmd_valid & awrready) & (~awrvalid_r)))
                    //aw or ar fire (valid and ready)
                    awrvalid_r <=  1'b1 ;
                else
                    if (cmd_fire)
                        awrvalid_r <=  1'b0 ;
        end
    always
        @(posedge clk or
            negedge rst_n)
        begin
            if ((!rst_n))
                wrvalid_r <=  2'b00 ;
            else
                if ((((wrvalid_r == 2'b00) && dBus_cmd_valid) && wready))
                    //w fire (valid and ready)
                    wrvalid_r <=  2'b01 ;
                else
                    if (((wrvalid_r == 2'b01) && bvalid_i))
                        wrvalid_r <=  2'b10 ;
                    else
                        if ((wrvalid_r == 2'b10))
                            wrvalid_r <=  2'b00 ;
        end
    //for read: ar valid and read fire; for write: both aw and w's valid and read fire
    //assign dBus_cmd_ready = ((awrready && (!dBus_cmd_payload_wr) ) || (awrvalid_r && wrvalid_r==2'b10));
    assign dBus_cmd_ready = (((MODE == "Advanced") || (MODE == "Balanced")) ? ((awrready && (!dBus_cmd_payload_wr)) || (awrvalid_r && (wrvalid_r == 2'b10))) : ((awrready && (!dBus_cmd_payload_wr)) || (awrvalid_r && (wrvalid_r == 2'b01)))) ;
endmodule



`resetall
