    input m0_dBus_rsp_exclusive,
    //dbus interface master1
    output m1_dBus_cmd_valid,
    input m1_dBus_cmd_ready,
    output m1_dBus_cmd_payload_wr,
    output [31:0] m1_dBus_cmd_payload_address,
    output [31:0] m1_dBus_cmd_payload_data,
    output [3:0] m1_dBus_cmd_payload_mask,
    output [2:0] m1_dBus_cmd_payload_size,
    output m1_dBus_cmd_payload_last,
    input m1_dBus_rsp_valid,
