    input m4_dBus_rsp_last,
    input m4_dBus_rsp_error,
    input [31:0] m4_dBus_rsp_data,
    //dbus interface master5
    output m5_dBus_cmd_valid,
    input m5_dBus_cmd_ready,
    output m5_dBus_cmd_payload_wr,
    output [31:0] m5_dBus_cmd_payload_address,
    output [31:0] m5_dBus_cmd_payload_data,
    output [3:0] m5_dBus_cmd_payload_mask,
    output [2:0] m5_dBus_cmd_payload_size,
    output m5_dBus_cmd_payload_last,
    input m5_dBus_rsp_valid,
