    input m5_dBus_rsp_error,
    input [31:0] m5_dBus_rsp_data,
    //dbus interface master6
    output m6_dBus_cmd_valid,
    input m6_dBus_cmd_ready,
    output m6_dBus_cmd_payload_wr,
    output [31:0] m6_dBus_cmd_payload_address,
    output [31:0] m6_dBus_cmd_payload_data,
    output [3:0] m6_dBus_cmd_payload_mask,
    output [2:0] m6_dBus_cmd_payload_size,
    output m6_dBus_cmd_payload_last,
    input m6_dBus_rsp_valid,
    input m6_dBus_rsp_last,
    input m6_dBus_rsp_error,
    input [31:0] m6_dBus_rsp_data,
    //dbus interface master7
    output m7_dBus_cmd_valid,
    input m7_dBus_cmd_ready,
    output m7_dBus_cmd_payload_wr,
    output [31:0] m7_dBus_cmd_payload_address,
    output [31:0] m7_dBus_cmd_payload_data,
    output [3:0] m7_dBus_cmd_payload_mask,
    output [2:0] m7_dBus_cmd_payload_size,
    output m7_dBus_cmd_payload_last,
    input m7_dBus_rsp_valid,
    input m7_dBus_rsp_last,
    input m7_dBus_rsp_error,
    input [31:0] m7_dBus_rsp_data,
    //dbus interface master8
    output m8_dBus_cmd_valid,
    input m8_dBus_cmd_ready,
    output m8_dBus_cmd_payload_wr,
    output [31:0] m8_dBus_cmd_payload_address,
    output [31:0] m8_dBus_cmd_payload_data,
    output [3:0] m8_dBus_cmd_payload_mask,
    output [2:0] m8_dBus_cmd_payload_size,
    output m8_dBus_cmd_payload_last,
    input m8_dBus_rsp_valid,
    input m8_dBus_rsp_last,
    input m8_dBus_rsp_error,
    input [31:0] m8_dBus_rsp_data,
    //dbus interface master9
    output m9_dBus_cmd_valid,
    input m9_dBus_cmd_ready,
    output m9_dBus_cmd_payload_wr,
    output [31:0] m9_dBus_cmd_payload_address,
    output [31:0] m9_dBus_cmd_payload_data,
    output [3:0] m9_dBus_cmd_payload_mask,
    output [2:0] m9_dBus_cmd_payload_size,
    output m9_dBus_cmd_payload_last,
    input m9_dBus_rsp_valid,
    input m9_dBus_rsp_last,
    input m9_dBus_rsp_error,
    input [31:0] m9_dBus_rsp_data,
    //dbus interface master10
    output m10_dBus_cmd_valid,
    input m10_dBus_cmd_ready,
    output m10_dBus_cmd_payload_wr,
    output [31:0] m10_dBus_cmd_payload_address,
    output [31:0] m10_dBus_cmd_payload_data,
    output [3:0] m10_dBus_cmd_payload_mask,
    output [2:0] m10_dBus_cmd_payload_size,
    output m10_dBus_cmd_payload_last,
    input m10_dBus_rsp_valid,
    input m10_dBus_rsp_last,
    input m10_dBus_rsp_error,
    input [31:0] m10_dBus_rsp_data,
    //dbus interface master11
    output m11_dBus_cmd_valid,
    input m11_dBus_cmd_ready,
    output m11_dBus_cmd_payload_wr,
    output [31:0] m11_dBus_cmd_payload_address,
    output [31:0] m11_dBus_cmd_payload_data,
    output [3:0] m11_dBus_cmd_payload_mask,
    output [2:0] m11_dBus_cmd_payload_size,
    output m11_dBus_cmd_payload_last,
    input m11_dBus_rsp_valid,
    input m11_dBus_rsp_last,
    input m11_dBus_rsp_error,
    input [31:0] m11_dBus_rsp_data,
    //dbus interface master12
    output m12_dBus_cmd_valid,
    input m12_dBus_cmd_ready,
    output m12_dBus_cmd_payload_wr,
    output [31:0] m12_dBus_cmd_payload_address,
    output [31:0] m12_dBus_cmd_payload_data,
    output [3:0] m12_dBus_cmd_payload_mask,
    output [2:0] m12_dBus_cmd_payload_size,
    output m12_dBus_cmd_payload_last,
    input m12_dBus_rsp_valid,
    input m12_dBus_rsp_last,
    input m12_dBus_rsp_error,
    input [31:0] m12_dBus_rsp_data,
    //dbus interface master13
    output m13_dBus_cmd_valid,
    input m13_dBus_cmd_ready,
    output m13_dBus_cmd_payload_wr,
    output [31:0] m13_dBus_cmd_payload_address,
    output [31:0] m13_dBus_cmd_payload_data,
    output [3:0] m13_dBus_cmd_payload_mask,
    output [2:0] m13_dBus_cmd_payload_size,
    output m13_dBus_cmd_payload_last,
    input m13_dBus_rsp_valid,
    input m13_dBus_rsp_last,
    input m13_dBus_rsp_error,
    input [31:0] m13_dBus_rsp_data,
    //dbus interface master14
    output m14_dBus_cmd_valid,
    input m14_dBus_cmd_ready,
    output m14_dBus_cmd_payload_wr,
    output [31:0] m14_dBus_cmd_payload_address,
    output [31:0] m14_dBus_cmd_payload_data,
    output [3:0] m14_dBus_cmd_payload_mask,
    output [2:0] m14_dBus_cmd_payload_size,
    output m14_dBus_cmd_payload_last,
    input m14_dBus_rsp_valid,
    input m14_dBus_rsp_last,
    input m14_dBus_rsp_error,
    input [31:0] m14_dBus_rsp_data,
    //dbus interface master15
    output m15_dBus_cmd_valid,
    input m15_dBus_cmd_ready,
    output m15_dBus_cmd_payload_wr,
    output [31:0] m15_dBus_cmd_payload_address,
    output [31:0] m15_dBus_cmd_payload_data,
    output [3:0] m15_dBus_cmd_payload_mask,
    output [2:0] m15_dBus_cmd_payload_size,
    output m15_dBus_cmd_payload_last,
    input m15_dBus_rsp_valid,
    input m15_dBus_rsp_last,
    input m15_dBus_rsp_error,
    input [31:0] m15_dBus_rsp_data) ;
    wire [(MUX_NUM - 1):0] w_dBus_cmd_valid ;
    wire [(MUX_NUM - 1):0] w_addr_match ;
    wire [(MUX_NUM - 1):0] w_dBus_cmd_ready ;
    wire [(MUX_NUM - 1):0] w_dBus_cmd_payload_wr ;
    wire [31:0] w_dBus_cmd_payload_address [(MUX_NUM - 1):0] ;
    wire [31:0] w_dBus_cmd_payload_data [(MUX_NUM - 1):0] ;
    wire [3:0] w_dBus_cmd_payload_mask [(MUX_NUM - 1):0] ;
    wire [2:0] w_dBus_cmd_payload_size [(MUX_NUM - 1):0] ;
    wire [(MUX_NUM - 1):0] w_dBus_cmd_payload_last ;
    wire [(MUX_NUM - 1):0] w_dBus_rsp_valid ;
    wire [(MUX_NUM - 1):0] w_dBus_rsp_last ;
    wire [(MUX_NUM - 1):0] w_dBus_rsp_error ;
    wire [31:0] w_dBus_rsp_data [(MUX_NUM - 1):0] ;
    wire [3:0] segment7 ; //bit31:28
    wire [3:0] segment6 ; //bit27:24
    wire [3:0] segment5 ; //bit23:20
    wire [3:0] segment4 ; //bit19:16
    wire [3:0] segment3 ; //bit15:12
    wire [3:0] segment2 ; //bit11:8
    wire [3:0] segment1 ; //bit7:4
    wire [3:0] segment0 ; //bit3:0
    wire [31:0] dbus_addr ;
    assign segment7 = dBus_cmd_payload_address[31:28] ;
    assign segment6 = dBus_cmd_payload_address[27:24] ;
    assign segment5 = dBus_cmd_payload_address[23:20] ;
    assign segment4 = dBus_cmd_payload_address[19:16] ;
    assign segment3 = dBus_cmd_payload_address[15:12] ;
    assign segment2 = dBus_cmd_payload_address[11:8] ;
    assign segment1 = dBus_cmd_payload_address[7:4] ;
    assign segment0 = dBus_cmd_payload_address[3:0] ;
    assign dbus_addr = dBus_cmd_payload_address ;
    genvar slot ;
    generate
        for (slot = 0;(slot < MUX_NUM);slot = (slot + 1))
        begin : gen_mux0
            // assign w_dBus_cmd_valid           [slot] = dBus_cmd_valid          ;
            assign w_dBus_cmd_payload_wr[slot] = dBus_cmd_payload_wr ;
            assign w_dBus_cmd_payload_address[slot] = dBus_cmd_payload_address ;
            assign w_dBus_cmd_payload_data[slot] = dBus_cmd_payload_data ;
            assign w_dBus_cmd_payload_mask[slot] = dBus_cmd_payload_mask ;
            assign w_dBus_cmd_payload_size[slot] = dBus_cmd_payload_size ;
            assign w_dBus_cmd_payload_last[slot] = dBus_cmd_payload_last ;
        end
    endgenerate
    //assume data response always behind dBus_cmd_ready
    reg [(MUX_NUM - 1):0] valid_r0 ;
    reg [(MUX_NUM - 1):0] valid_r1 ;
    integer j ;
    // always @(posedge clk or negedge rst_n) begin
    //     if (!rst_n) begin
    //         valid_r <= {MUX_NUM{1'b0}};
    //     end else begin
    //         for (j = 0; j<MUX_NUM; j=j+1) begin
    //             if (dBus_cmd_ready && dBus_cmd_valid) begin
    //                 valid_r[j] <= w_dBus_cmd_valid[j];
    //             end
    //         end
    //     end
    // end
    // always @(*) begin
    //     for (j = 0; j<MUX_NUM; j=j+1) begin
    //         valid_r[j] = w_addr_match[j];
    //     end
    // end
    always
        @(posedge clk or
            negedge rst_n)
        begin
            if ((!rst_n))
                begin
                    valid_r0 <=  {MUX_NUM{1'b0}} ;
                    valid_r1 <=  {MUX_NUM{1'b0}} ;
                end
            else
                if ((dBus_cmd_valid == 1'b1))
                    begin
                        for (j = 0 ; (j < MUX_NUM) ; j = (j + 1))
                            begin
                                valid_r0[j] <=  w_addr_match[j] ;
                                valid_r1[j] <=  valid_r0[j] ;
                            end
                    end
        end
    reg w_reg ;
    wire localip_wr ;
    assign localip_wr = (((w_addr_match[2] | w_addr_match[3]) | w_addr_match[4]) & (dBus_cmd_payload_wr & dBus_cmd_valid)) ;
    always
        @(posedge clk or
            negedge rst_n)
        begin
            if ((!rst_n))
                begin
                    w_reg <=  1'b0 ;
                end
            else
                if (localip_wr)
                    begin
                        w_reg <=  1'b1 ;
                    end
                else
                    begin
                        w_reg <=  1'b0 ;
                    end
        end
    reg cmd_ready ;
    reg rsp_valid ;
    reg rsp_last ;
    reg rsp_error ;
    reg [31:0] rsp_data ;
    reg access_err ;
    integer i ;
    always
        @(*)
        begin
            cmd_ready = 1'b0 ;
            rsp_valid = 1'b0 ;
            rsp_last = 1'b0 ;
            rsp_error = 1'b0 ;
            rsp_data = 32'b0 ;
            for (i = 0 ; (i < MUX_NUM) ; i = (i + 1))
                begin
                    // no priority
                    // cmd_ready = ( w_dBus_cmd_valid[i] & w_dBus_cmd_ready[i]        ) | cmd_ready ;
                    // rsp_valid = ( valid_r[i]          & w_dBus_rsp_valid[i]        ) | rsp_valid ;
                    // rsp_last  = ( valid_r[i]          & w_dBus_rsp_last[i]         ) | rsp_last  ;
                    // rsp_error = ( valid_r[i]          & w_dBus_rsp_error[i]        ) | rsp_error ;
                    // rsp_data  = ( valid_r[i]          ? w_dBus_rsp_data[i] : 32'b0 ) | rsp_data  ;
                    // have priority
                    if ((w_dBus_cmd_valid[i] & w_dBus_cmd_ready[i]))
                        begin
                            cmd_ready = 1'b1 ;
                        end
                    if (((valid_r0[i] || valid_r1[i]) & w_dBus_rsp_valid[i]))
                        begin
                            rsp_valid = 1'b1 ;
                        end
                    if ((((valid_r0[i] || valid_r1[i]) & w_dBus_rsp_last[i]) & w_dBus_rsp_valid[i]))
                        begin
                            rsp_last = 1'b1 ;
                        end
                    if ((((valid_r0[i] || valid_r1[i]) & w_dBus_rsp_error[i]) & w_dBus_rsp_valid[i]))
                        begin
                            rsp_error = 1'b1 ;
                        end
                    if (((valid_r0[i] || valid_r1[i]) & w_dBus_rsp_valid[i]))
                        begin
                            rsp_data = w_dBus_rsp_data[i] ;
                        end
                end
        end
    // assign access_err = (|w_addr_match == 1'b0) & dBus_cmd_valid;
    always
        @(posedge clk or
            negedge rst_n)
        begin
            if ((!rst_n))
                begin
                    access_err <=  1'b0 ;
                end
            else
                if (((((|w_addr_match) == 1'b0) & dBus_cmd_valid) | ((dBus_cmd_payload_exclusive & dBus_cmd_valid) & (~w_addr_match[0]))))
                    begin
                        access_err <=  1'b1 ;
                    end
                else
                    begin
                        access_err <=  1'b0 ;
                    end
        end
    always
        @(posedge clk or
            negedge rst_n)
        begin
            if ((!rst_n))
                begin
                    dBus_sync_valid <=  1'b0 ;
                end
            else
                if (((dBus_cmd_valid & dBus_cmd_payload_wr) & dBus_cmd_ready))
                    begin
                        dBus_sync_valid <=  1'b1 ;
                    end
                else
                    begin
                        dBus_sync_valid <=  1'b0 ;
                    end
        end
    assign dBus_cmd_ready = (cmd_ready | access_err) ;
    assign dBus_rsp_valid = (rsp_valid | access_err) ;
    assign dBus_rsp_last = rsp_last ;
    assign dBus_rsp_error = (rsp_error | access_err) ;
    assign dBus_rsp_data = rsp_data ;
    wire [((32 * 16) - 1):0] MX_ADDR_BASE ;
    wire [((32 * 16) - 1):0] MX_ADDR_END ;
    assign MX_ADDR_BASE = {M15_ADDR_BASE,
                M14_ADDR_BASE,
                M13_ADDR_BASE,
                M12_ADDR_BASE,
                M11_ADDR_BASE,
                M10_ADDR_BASE,
                M9_ADDR_BASE,
                M8_ADDR_BASE,
                M7_ADDR_BASE,
                M6_ADDR_BASE,
                M5_ADDR_BASE,
                M4_ADDR_BASE,
                M3_ADDR_BASE,
                M2_ADDR_BASE,
                M1_ADDR_BASE,
                M0_ADDR_BASE} ;
    assign MX_ADDR_END = {M15_ADDR_END,
                M14_ADDR_END,
                M13_ADDR_END,
                M12_ADDR_END,
                M11_ADDR_END,
                M10_ADDR_END,
                M9_ADDR_END,
                M8_ADDR_END,
                M7_ADDR_END,
                M6_ADDR_END,
                M5_ADDR_END,
                M4_ADDR_END,
                M3_ADDR_END,
                M2_ADDR_END,
                M1_ADDR_END,
                M0_ADDR_END} ;
    // address match and cmd_valid
    genvar bus_sel ;
    generate
        for (bus_sel = 0;(bus_sel < MUX_NUM);bus_sel = (bus_sel + 1))
        begin : genblk2
            assign w_addr_match[bus_sel] = (((dbus_addr | ADDR_MASK) >= (MX_ADDR_BASE[(((bus_sel + 1) * 32) - 1):(bus_sel * 32)] | ADDR_MASK)) && ((dbus_addr | ADDR_MASK) <= (MX_ADDR_END[(((bus_sel + 1) * 32) - 1):(bus_sel * 32)] | ADDR_MASK))) ;
            assign w_dBus_cmd_valid[bus_sel] = (w_addr_match[bus_sel] & dBus_cmd_valid) ;
        end
    endgenerate
