    input [31:0] s_dBus_cmd_payload_data,
    input [3:0] s_dBus_cmd_payload_mask,
    input [2:0] s_dBus_cmd_payload_size,
    input s_dBus_cmd_payload_last,
    input s_dBus_cmd_payload_exclusive,
    output s_dBus_rsp_valid,
    output s_dBus_rsp_last,
    output s_dBus_rsp_error,
    output [31:0] s_dBus_rsp_data,
    output s_dBus_rsp_exclusive,
    //output interface
    output m_dBus_cmd_valid,
    input m_dBus_cmd_ready,
    output m_dBus_cmd_payload_wr,
    output m_dBus_cmd_payload_uncached,
    output [31:0] m_dBus_cmd_payload_address,
    output [31:0] m_dBus_cmd_payload_data,
    output [3:0] m_dBus_cmd_payload_mask,
    output [2:0] m_dBus_cmd_payload_size,
    output m_dBus_cmd_payload_last,
    output m_dBus_cmd_payload_exclusive,
    input m_dBus_rsp_valid,
    input m_dBus_rsp_last,
    input m_dBus_rsp_error,
    input [31:0] m_dBus_rsp_data,
    input m_dBus_rsp_exclusive) ;
    reg reg_dBus_cmd_valid ;
    reg reg_dBus_cmd_ready ;
    reg reg_dBus_cmd_payload_wr ;
    reg reg_dBus_cmd_payload_uncached ;
    reg [31:0] reg_dBus_cmd_payload_address ;
    reg [31:0] reg_dBus_cmd_payload_data ;
    reg [3:0] reg_dBus_cmd_payload_mask ;
    reg [2:0] reg_dBus_cmd_payload_size ;
    reg reg_dBus_cmd_payload_last ;
    reg reg_dBus_cmd_payload_exclusive ;
    reg reg_dBus_rsp_valid ;
    reg reg_dBus_rsp_last ;
    reg reg_dBus_rsp_error ;
    reg [31:0] reg_dBus_rsp_data ;
    reg reg_dBus_rsp_exclusive ;
    always
        @(posedge clk or
            negedge rst_n)
        begin
            if ((!rst_n))
                begin
                    reg_dBus_cmd_valid <=  1'b0 ;
                    reg_dBus_cmd_payload_wr <=  1'b0 ;
                    reg_dBus_cmd_payload_uncached <=  1'b0 ;
                    reg_dBus_cmd_payload_address <=  32'b0 ;
                    reg_dBus_cmd_payload_data <=  32'b0 ;
                    reg_dBus_cmd_payload_mask <=  4'b0 ;
                    reg_dBus_cmd_payload_size <=  3'b0 ;
                    reg_dBus_cmd_payload_last <=  1'b0 ;
                    reg_dBus_cmd_payload_exclusive <=  1'b0 ;
                end
            else
                if (((s_dBus_cmd_valid & (~reg_dBus_cmd_valid)) & (~reg_dBus_cmd_ready)))
                    begin
                        reg_dBus_cmd_valid <=  s_dBus_cmd_valid ;
                        reg_dBus_cmd_payload_wr <=  s_dBus_cmd_payload_wr ;
                        reg_dBus_cmd_payload_uncached <=  s_dBus_cmd_payload_uncached ;
                        reg_dBus_cmd_payload_address <=  s_dBus_cmd_payload_address ;
                        reg_dBus_cmd_payload_data <=  s_dBus_cmd_payload_data ;
                        reg_dBus_cmd_payload_mask <=  s_dBus_cmd_payload_mask ;
                        reg_dBus_cmd_payload_size <=  s_dBus_cmd_payload_size ;
                        reg_dBus_cmd_payload_last <=  s_dBus_cmd_payload_last ;
                        reg_dBus_cmd_payload_exclusive <=  s_dBus_cmd_payload_exclusive ;
                    end
                else
                    if (m_dBus_cmd_ready)
                        begin
                            reg_dBus_cmd_valid <=  1'b0 ;
                            // reg_dBus_cmd_payload_wr        <= 1'b0;
                            // reg_dBus_cmd_payload_uncached  <= 1'b0;
                            // reg_dBus_cmd_payload_address   <= 32'b0;
                            // reg_dBus_cmd_payload_data      <= 32'b0;
                            // reg_dBus_cmd_payload_mask      <= 4'b0;
                            // reg_dBus_cmd_payload_size      <= 3'b0;
                            // reg_dBus_cmd_payload_last      <= 1'b0;
                        end
        end
    always
        @(posedge clk or
            negedge rst_n)
        begin
            if ((!rst_n))
                begin
                    reg_dBus_cmd_ready <=  1'b0 ;
                end
            else
                if ((reg_dBus_cmd_valid & m_dBus_cmd_ready))
                    begin
                        reg_dBus_cmd_ready <=  1'b1 ;
                    end
                else
                    begin
                        reg_dBus_cmd_ready <=  1'b0 ;
                    end
        end
    always
        @(posedge clk or
            negedge rst_n)
        begin
            if ((!rst_n))
                begin
                    reg_dBus_rsp_valid <=  1'b0 ;
                    reg_dBus_rsp_last <=  1'b0 ;
                    reg_dBus_rsp_error <=  1'b0 ;
                    reg_dBus_rsp_data <=  32'b0 ;
                    reg_dBus_rsp_exclusive <=  1'b0 ;
                end
            else
                begin
                    reg_dBus_rsp_valid <=  m_dBus_rsp_valid ;
                    reg_dBus_rsp_last <=  m_dBus_rsp_last ;
                    reg_dBus_rsp_error <=  m_dBus_rsp_error ;
                    reg_dBus_rsp_data <=  m_dBus_rsp_data ;
                    reg_dBus_rsp_exclusive <=  m_dBus_rsp_exclusive ;
                end
        end
    assign s_dBus_cmd_ready = reg_dBus_cmd_ready ;
    assign s_dBus_rsp_valid = reg_dBus_rsp_valid ;
    assign s_dBus_rsp_last = reg_dBus_rsp_last ;
    assign s_dBus_rsp_error = reg_dBus_rsp_error ;
    assign s_dBus_rsp_data = reg_dBus_rsp_data ;
    assign s_dBus_rsp_exclusive = reg_dBus_rsp_exclusive ;
    assign m_dBus_cmd_valid = reg_dBus_cmd_valid ;
    assign m_dBus_cmd_payload_wr = reg_dBus_cmd_payload_wr ;
    assign m_dBus_cmd_payload_uncached = reg_dBus_cmd_payload_uncached ;
    assign m_dBus_cmd_payload_address = reg_dBus_cmd_payload_address ;
    assign m_dBus_cmd_payload_data = reg_dBus_cmd_payload_data ;
    assign m_dBus_cmd_payload_mask = reg_dBus_cmd_payload_mask ;
    assign m_dBus_cmd_payload_size = reg_dBus_cmd_payload_size ;
    assign m_dBus_cmd_payload_last = reg_dBus_cmd_payload_last ;
    assign m_dBus_cmd_payload_exclusive = reg_dBus_cmd_payload_exclusive ;
endmodule



