        AlmostFull) ;
    input [7:0] Data ;
    input Clock ;
    input WrEn ;
    input RdEn ;
    input Reset ;
    output [7:0] Q ;
    output Empty ;
    output Full ;
    output AlmostEmpty ;
    output AlmostFull ;
    parameter lat_family = "MachXO3D" ;
    generate
        if (((lat_family == "SC") || (lat_family == "SCM")))
            begin : genblk1
                pmi_fifo_dc #(.pmi_data_width_w(8),
                        .pmi_data_width_r(8),
                        .pmi_data_depth_w(16),
                        .pmi_data_depth_r(16),
                        .pmi_full_flag(16),
                        .pmi_empty_flag(0),
                        .pmi_almost_full_flag(8),
                        .pmi_almost_empty_flag(4),
                        .pmi_regmode("noreg"),
                        .pmi_family("MachXO3D"),
                        .module_type("pmi_fifo_dc"),
                        .pmi_implementation("LUT")) tx_fifo_inst_dc (.Data(Data),
                            .WrClock(Clock),
                            .RdClock(Clock),
                            .WrEn(WrEn),
                            .RdEn(RdEn),
                            .Reset(Reset),
                            .RPReset(Reset),
                            .Q(Q),
                            .Empty(Empty),
                            .Full(Full),
                            .AlmostEmpty(AlmostEmpty),
                            .AlmostFull(AlmostFull)) ;
            end
        else
            begin : genblk1
                pmi_fifo #(.pmi_data_width(8),
                        .pmi_data_depth(16),
                        .pmi_full_flag(16),
                        .pmi_empty_flag(0),
                        .pmi_almost_full_flag(8),
                        .pmi_almost_empty_flag(4),
                        .pmi_regmode("noreg"),
                        .pmi_family("MachXO3D"),
                        .module_type("pmi_fifo"),
                        .pmi_implementation("LUT")) tx_fifo_inst (.Data(Data),
                            .Clock(Clock),
                            .WrEn(WrEn),
                            .RdEn(RdEn),
                            .Reset(Reset),
                            .Q(Q),
                            .Empty(Empty),
                            .Full(Full),
                            .AlmostEmpty(AlmostEmpty),
                            .AlmostFull(AlmostFull)) ;
            end
    endgenerate
endmodule



`resetall
`timescale 1ns/1ps
module cpu0_ipgen_lscc_uart_apb_intface #(parameter CLK_IN_MHZ = 25,
        parameter BAUD_RATE = 115200,
        parameter CLK_DIVISOR = (CLK_IN_MHZ / BAUD_RATE),
        parameter UART_WB_ADR_WIDTH = 4,
        parameter UART_WB_DAT_WIDTH = 8,
        parameter FIFO = 0,
        parameter LCR_DATA_BITS = 8,
        parameter LCR_STOP_BITS = 1,
        parameter LCR_PARITY_ENABLE = 0,
        parameter LCR_PARITY_ODD = 0,
        parameter LCR_PARITY_STICK = 0,
        parameter LCR_SET_BREAK = 0,
        parameter STDOUT_SIM = 0,
        parameter STDOUT_SIMFAST = 0) (
    // system clock and reset
    input reset,
    input clk,
    //    // wishbone interface signals
    //    input cyc_i,
    //    input stb_i,
    //    input we_i,
    //    input [2:0] cti_i,
    //    input [1:0] bte_i,
    //    input [UART_WB_ADR_WIDTH-1:0] adr_i,
    //    input [UART_WB_DAT_WIDTH-1:0] dat_i,
    //    output reg ack_o,
    //    output [UART_WB_DAT_WIDTH-1:0] dat_o,
    // -----------------------------------------
    // APB Interface
    // -----------------------------------------
    //input         pclk   ,
    //input         presetn,
    input psel,
    input [3:0] paddr,
    input [7:0] pwdata,
    input pwrite,
    input penable,
    output reg pready,
    output [7:0] prdata,
    output reg intr,
    // Registers
    input [(UART_WB_DAT_WIDTH - 1):0] rbr,
    input [(UART_WB_DAT_WIDTH - 1):0] rbr_fifo,
    output [(UART_WB_DAT_WIDTH - 1):0] thr,
    // Rising edge of registers read/write strobes
    output rbr_rd,
    output reg thr_wr,
    output lsr_rd,
    // Receiver/Transmitter control
    output [1:0] databits,
    output [1:0] stopbits,
    output parity_en,
    output parity_even,
    output parity_stick,
    output tx_break,
    // Receiver/Transmitter status
    input rx_rdy,
    input overrun_err,
    input parity_err,
    input frame_err,
    input break_int,
    input thrr,
    input temt,
    input fifo_empty,
    output fifo_empty_thr,
    output fifo_full_thr,
    input thr_rd,
    input fifo_almost_full,
    output reg [15:0] divisor) ;
    localparam LCR_PARITY_EVEN = (LCR_PARITY_ODD ? 0 : 1) ;
    reg dlab_r ;
    wire [6:0] lcr_default ;
    assign lcr_default[1:0] = (LCR_DATA_BITS - 5) ;
    assign lcr_default[6:2] = {LCR_SET_BREAK[0],
                LCR_PARITY_STICK[0],
                LCR_PARITY_EVEN[0],
                LCR_PARITY_ENABLE[0],
                LCR_STOP_BITS[1]} ;
    //   generate
    //      if (LCR_DATA_BITS == 5)
    //    assign lcr_default[1:0] = 2'b00;
    //      else if (LCR_DATA_BITS == 6)
    //    assign lcr_default[1:0] = 2'b01;
    //      else if (LCR_DATA_BITS == 7)
    //    assign lcr_default[1:0] = 2'b10;
    //      else
    //    assign lcr_default[1:0] = 2'b11;
    //   endgenerate
    //
    //   generate
    //      if (LCR_STOP_BITS == 1)
    //    assign lcr_default[2] = 1'b0;
    //      else
    //    assign lcr_default[2] = 1'b1;
    //   endgenerate
    //
    //   generate
    //      if (LCR_PARITY_ENABLE == 0)
    //    assign lcr_default[3] = 1'b0;
    //      else
    //    assign lcr_default[3] = 1'b1;
    //   endgenerate
    //
    //   generate
    //      if (LCR_PARITY_ODD == 0)
    //    assign lcr_default[4] = 1'b1;
    //      else
    //    assign lcr_default[4] = 1'b0;
    //   endgenerate
    //
    //   generate
    //      if (LCR_PARITY_STICK == 0)
    //    assign lcr_default[5] = 1'b0;
    //      else
    //    assign lcr_default[5] = 1'b1;
    //   endgenerate
    //
    //   generate
    //      if (LCR_SET_BREAK == 0)
    //    assign lcr_default[6] = 1'b0;
    //      else
    //    assign lcr_default[6] = 1'b1;
    //   endgenerate
    wire [(UART_WB_DAT_WIDTH - 1):0] thr_fifo ;
    reg [(UART_WB_DAT_WIDTH - 1):0] thr_nonfifo ;
    reg [7:0] data_8bit ;
    generate
        if ((FIFO == 1))
            begin: genblk1
                assign thr = thr_fifo ;
            end
        else
            begin: genblk1
                assign thr = thr_nonfifo ;
            end
    endgenerate
    reg [6:0] lsr ;
    reg [6:0] lcr ;
    wire [3:0] iir ;
    reg [2:0] ier ;
    wire rx_rdy_int ;
    wire thre_int ;
    wire dataerr_int ;
    wire data_err ;
    wire wr_strobe ;
    wire thr_wr_strobe ;
    wire rbr_rd_strobe ;
    wire iir_rd_strobe ;
    reg iir_rd_strobe_delay ;
    wire lsr_rd_strobe ;
    wire div_wr_strobe ;
    reg lsr2_r,
        lsr3_r,
        lsr4_r ;
    wire rbr_rd_fifo ;
    reg rbr_rd_nonfifo ;
    generate
        if ((FIFO == 1))
            begin: genblk2
                assign rbr_rd = rbr_rd_fifo ;
            end
        else
            begin: genblk2
                assign rbr_rd = rbr_rd_nonfifo ;
            end
    endgenerate
    // FIFO signals for FIFO mode
    wire fifo_almost_full_thr ;
    wire fifo_almost_empty_thr ;
    wire [7:0] fifo_din_thr ;
    reg fifo_wr_thr ;
    reg fifo_wr_q_thr ;
    wire fifo_wr_pulse_thr ;
    // UART baud 16x clock generator
    always
        @(posedge clk or
            posedge reset)
        begin
            if (reset)
                //divisor <= ((CLK_IN_MHZ*1000*1000)/(BAUD_RATE));
                divisor <=  CLK_DIVISOR[15:0] ;
            else
                if (div_wr_strobe)
                    if (paddr[0])
                        //   adr_i[0])
                        //divisor <= {pwdata[7:0]  ,divisor[7:0]};
                        divisor[15:8] <=  pwdata[7:0] ;
                    else
                        //divisor <= {divisor[15:8],pwdata[7:0] };
                        divisor[7:0] <=  pwdata[7:0] ;
        end
    // UART Registers Address Map
    localparam A_RBR = 4'b0000 ;
    localparam A_THR = 4'b0000 ;
    localparam A_IER = 4'b0001 ;
    localparam A_IIR = 4'b0010 ;
    localparam A_LCR = 4'b0011 ;
    localparam A_LSR = 4'b0101 ;
    localparam A_DIV = 3'b100 ;
    always
        @(posedge clk or
            posedge reset)
        begin
            if (reset)
                thr_wr <=  1'b0 ;
            else
                thr_wr <=  thr_wr_strobe ;
        end// always
    assign lsr_rd = lsr_rd_strobe ;
    assign rbr_rd_fifo = rbr_rd_strobe ;
    always
        @(posedge clk or
            posedge reset)
        begin
            if (reset)
                rbr_rd_nonfifo <=  1'b0 ;
            else
                rbr_rd_nonfifo <=  rbr_rd_strobe ;
        end// always
    ////////////////////////////////////////////////////////////////////////////////
    // Registers Read/Write Control Signals
    ////////////////////////////////////////////////////////////////////////////////
    generate
        if ((FIFO == 1))
            begin: genblk3
                assign wr_strobe = (((((paddr == A_THR) && psel) && pwrite) && (~fifo_full_thr)) && (~pready)) ;
            end
        else
            begin: genblk3
                assign wr_strobe = ((((paddr == A_THR) && psel) && pwrite) && pready) ;
            end
        if (((STDOUT_SIMFAST == 1) && (STDOUT_SIM == 1)))
            begin : genblk4
                //assign thr_wr_strobe = wr_strobe;
                assign thr_wr_strobe = 1'b0 ;
            end
        else
            begin : genblk4
                assign thr_wr_strobe = wr_strobe ;
            end
    endgenerate
    generate
        if ((FIFO == 1))
            begin: genblk5
                assign rbr_rd_strobe = (((((paddr == A_RBR) && psel) && (~pwrite)) && (~fifo_empty)) && (~pready)) ;
            end
        else
            begin: genblk5
                assign rbr_rd_strobe = (((paddr == A_RBR) && psel) && (~pwrite)) ;
            end
    endgenerate
    generate
        if ((FIFO == 1))
            begin: genblk6
                assign iir_rd_strobe = ((((paddr == A_IIR) && psel) && (~pwrite)) && (~pready)) ;
            end
        else
            begin: genblk6
                assign iir_rd_strobe = (((paddr == A_IIR) && psel) && (~pwrite)) ;
            end
    endgenerate
    generate
        if ((FIFO == 1))
            begin: genblk7
                assign lsr_rd_strobe = ((((paddr == A_LSR) && psel) && (~pwrite)) && (~pready)) ;
            end
        else
            begin: genblk7
                assign lsr_rd_strobe = (((paddr == A_LSR) && psel) && (~pwrite)) ;
            end
    endgenerate
    assign div_wr_strobe = (((((paddr[3:1] == A_DIV) && psel) && pwrite) && penable) && pready) ;
    ////////////////////////////////////////////////////////////////////////////////
    // Registers Read/Write Operation
    ////////////////////////////////////////////////////////////////////////////////
    generate
        if ((FIFO == 1))
            begin : fifo_regrd
                //   always @(cyc_i or stb_i or we_i or adr_i or rbr_fifo or iir
                //`ifdef MODEM
                //        or msr
                //`endif
                //        or lsr)
                always
                    @(*)
                    begin
                        case (paddr)
                        A_RBR :
                            data_8bit <=  rbr_fifo ;
                        A_IER :
                            data_8bit <=  {5'b00000,
                                    ier} ;
                        A_IIR :
                            data_8bit <=  {4'b1100,
                                    iir} ;
                        A_LCR :
                            // Indicates FIFOs are enabled
                            data_8bit <=  {1'b0,
                                    lcr} ;
                        A_LSR :
                            data_8bit <=  {1'b0,
                                    lsr} ;
                        default :
                            data_8bit <=  8'b00000000 ;
                        endcase
                    end
            end
        else
            begin : nfifo_regrd
                // Register Read
                always
                    @(posedge clk or
                        posedge reset)
                    begin
                        if (reset)
                            data_8bit <=  8'b00000000 ;
                        else
                            //          else if (cyc_i && stb_i && ~we_i)
                            if ((psel && (~pwrite)))
                                case (paddr)
                                A_RBR :
                                    data_8bit <=  rbr ;
                                A_IER :
                                    data_8bit <=  {5'b00000,
                                            ier} ;
                                A_IIR :
                                    data_8bit <=  {4'b0000,
                                            iir} ;
                                A_LCR :
                                    data_8bit <=  {1'b0,
                                            lcr} ;
                                A_LSR :
                                    data_8bit <=  {1'b0,
                                            lsr} ;
                                default :
                                    data_8bit <=  8'b00000000 ;
                                endcase
                    end// always
            end
    endgenerate
    //   assign dat_o = data_8bit;
    assign prdata = data_8bit ;
    generate
        if ((FIFO == 0))
            begin : nfifo_regwr
                always
                    @(posedge clk or
                        posedge reset)
                    begin
                        if (reset)
                            begin
                                thr_nonfifo <=  {UART_WB_DAT_WIDTH{1'b0}} ;
                                ier <=  3'b000 ;
                                lcr <=  lcr_default ;
                            end
                        else
                            //          else if (cyc_i && stb_i && we_i) begin
                            if (((psel && pwrite) && penable))
                                begin
                                    case (paddr)
                                    A_THR :
                                        thr_nonfifo <=  pwdata[(UART_WB_DAT_WIDTH - 1):0] ;
                                    A_IER :
                                        ier <=  pwdata[2:0] ;
                                    A_LCR :
                                        lcr <=  pwdata[6:0] ;
                                    default :
                                        ;
                                    endcase
                                end
                    end// always
            end
        else
            begin : fifo_regwr
                always
                    @(posedge clk or
                        posedge reset)
                    begin
                        if (reset)
                            begin
                                ier <=  3'b000 ;
                                lcr <=  lcr_default ;
                            end
                        else
                            //          else if (cyc_i && stb_i && we_i)
                            if (((psel && pwrite) && penable))
                                case (paddr)
                                A_IER :
                                    ier <=  pwdata[2:0] ;
                                A_LCR :
                                    lcr <=  pwdata[6:0] ;
                                default :
                                    ;
                                endcase
                    end// always
            end
    endgenerate
    generate
        if ((FIFO == 1))
            begin : tx_fifo_inst
                assign fifo_wr_pulse_thr = thr_wr_strobe ;
                assign fifo_din_thr = pwdata ; //dat_i[7:0];
                cpu0_ipgen_lscc_uart_txcver_fifo TX_FIFO (.Data(fifo_din_thr),
                            .Clock(clk),
                            .WrEn(fifo_wr_pulse_thr),
                            .RdEn(thr_rd),
                            .Reset(reset),
                            .Q(thr_fifo),
                            .Empty(fifo_empty_thr),
                            .Full(fifo_full_thr),
                            .AlmostEmpty(fifo_almost_empty_thr),
                            .AlmostFull(fifo_almost_full_thr)) ;
            end
    endgenerate
    ////////////////////////////////////////////////////////////////////////////////
    //  Line Control Register
    ////////////////////////////////////////////////////////////////////////////////
    // databits : "00"=5-bit, "01"=6-bit, "10"=7-bit, "11"=8-bit
    assign databits = lcr[1:0] ;
    // stopbits : "00"=1-bit, "01"=1.5-bit(5-bit data), "10"=2-bit(6,7,8-bit data)
    assign stopbits = ((lcr[2] == 1'b0) ? 2'b00 : ((lcr[2:0] == 3'b100) ? 2'b01 : 2'b10)) ;
    // parity_en : '0'=Parity Bit Enable, '1'=Parity Bit Disable
    assign parity_en = lcr[3] ;
    // parity_even : '0'=Even Parity Selected, '1'=Odd Parity Selected
    assign parity_even = lcr[4] ;
    // parity_stick : '0'=Stick Parity Disable, '1'=Stick Parity Enable
    assign parity_stick = lcr[5] ;
    // tx_break : '0'=Disable BREAK assertion, '1'=Assert BREAK
    assign tx_break = lcr[6] ;
    ////////////////////////////////////////////////////////////////////////////////
    //  Line Status Register
    ////////////////////////////////////////////////////////////////////////////////
    generate
        if ((FIFO == 1))
            begin : fifo_lsr
                always
                    @(posedge clk or
                        posedge reset)
                    if (reset)
                        lsr2_r <=  1'b0 ;
                    else
                        if (parity_err)
                            lsr2_r <=  1'b1 ;
                        else
                            if (lsr_rd_strobe)
                                lsr2_r <=  1'b0 ;
                always
                    @(posedge clk or
                        posedge reset)
                    if (reset)
                        lsr3_r <=  1'b0 ;
                    else
                        if (frame_err)
                            lsr3_r <=  1'b1 ;
                        else
                            if (lsr_rd_strobe)
                                lsr3_r <=  1'b0 ;
                always
                    @(posedge clk or
                        posedge reset)
                    if (reset)
                        lsr4_r <=  1'b0 ;
                    else
                        if (break_int)
                            lsr4_r <=  1'b1 ;
                        else
                            if (lsr_rd_strobe)
                                lsr4_r <=  1'b0 ;
                always
                    @(posedge clk)
                    lsr <=  {temt,
                            thrr,
                            lsr4_r,
                            lsr3_r,
                            lsr2_r,
                            overrun_err,
                            rx_rdy} ;
            end
        else
            begin : nfifo_lsr
                always
                    @(temt or
                        thrr or
                        break_int or
                        frame_err or
                        parity_err or
                        overrun_err or
                        rx_rdy)
                    lsr = {temt,
                            thrr,
                            break_int,
                            frame_err,
                            parity_err,
                            overrun_err,
                            rx_rdy} ;
            end
    endgenerate
    ////////////////////////////////////////////////////////////////////////////////
    // Interrupt Arbitrator
    ////////////////////////////////////////////////////////////////////////////////
    // Int is the common interrupt line for all internal UART events
    always
        @(posedge clk or
            posedge reset)
        begin
            if (reset)
                intr <=  1'b0 ;
            else
                intr <=  ((rx_rdy_int | thre_int) | dataerr_int) ;
        end// always
    // Receiving Data Error Flags including Overrun, Parity, Framing and Break
    generate
        if ((FIFO == 1))
            begin: genblk12
                assign data_err = (((overrun_err | lsr2_r) | lsr3_r) | lsr4_r) ;
            end
        else
            begin: genblk12
                assign data_err = (((overrun_err | parity_err) | frame_err) | break_int) ;
            end
    endgenerate
    // Whenever bit0, 1, 2,or 3 is set to '1', A_WB Modem Status Interrupt is generated
    generate
        if ((FIFO == 1))
            begin: genblk13
                always
                    @(posedge clk or
                        posedge reset)
                    if (reset)
                        iir_rd_strobe_delay <=  1'b0 ;
                    else
                        iir_rd_strobe_delay <=  iir_rd_strobe ;
            end
    endgenerate
    // State Machine Definition
    localparam idle = 3'b000 ;
    localparam int0 = 3'b001 ;
    localparam int1 = 3'b010 ;
    localparam int2 = 3'b011 ;
    localparam int3 = 3'b100 ;
    reg [2:0] cs_state ;
    generate
        if ((FIFO == 1))
            begin : fifo_int
                always
                    @(posedge clk or
                        posedge reset)
                    begin
                        if (reset)
                            cs_state <=  idle ;
                        else
                            case (cs_state)
                            idle :
                                begin
                                    if (((ier[2] == 1'b1) && (data_err == 1'b1)))
                                        cs_state <=  int0 ;
                                    else
                                        if (((ier[0] == 1'b1) && (fifo_almost_full || (!fifo_empty))))
                                            cs_state <=  int1 ;
                                        else
                                            if (((ier[1] == 1'b1) && (thrr == 1'b1)))
                                                cs_state <=  int2 ;
                                end
                            int0 :
                                begin
                                    if (((lsr_rd_strobe == 1'b1) || (ier[2] == 1'b0)))
                                        begin
                                            if (((ier[0] == 1'b1) && fifo_almost_full))
                                                cs_state <=  int1 ;
                                            else
                                                cs_state <=  idle ;
                                        end
                                end
                            int1 :
                                begin
                                    if (((data_err == 1'b1) && (ier[2] == 1'b1)))
                                        cs_state <=  int0 ;
                                    else
                                        if (((!fifo_almost_full) || (ier[0] == 1'b0)))
                                            cs_state <=  idle ;
                                end
                            int2 :
                                begin
                                    if (((iir_rd_strobe_delay || (thrr == 1'b0)) || (ier[1] == 1'b0)))
                                        cs_state <=  idle ;
                                end
                            default :
                                cs_state <=  idle ;
                            endcase
                    end// always
            end
        else
            begin : nfifo_int
                always
                    @(posedge clk or
                        posedge reset)
                    begin
                        if (reset)
                            cs_state <=  idle ;
                        else
                            case (cs_state)
                            idle :
                                begin
                                    if (((ier[2] == 1'b1) && (data_err == 1'b1)))
                                        cs_state <=  int0 ;
                                    else
                                        if (((ier[0] == 1'b1) && (rx_rdy == 1'b1)))
                                            cs_state <=  int1 ;
                                        else
                                            if (((ier[1] == 1'b1) && (thrr == 1'b1)))
                                                cs_state <=  int2 ;
                                end
                            int0 :
                                begin
                                    if (((lsr_rd_strobe == 1'b1) || (ier[2] == 1'b0)))
                                        begin
                                            if (((ier[0] == 1'b1) && rx_rdy))
                                                cs_state <=  int1 ;
                                            else
                                                cs_state <=  idle ;
                                        end
                                end
                            int1 :
                                begin
                                    if (((data_err == 1'b1) && (ier[2] == 1'b1)))
                                        cs_state <=  int0 ;
                                    else
                                        if (((rx_rdy == 1'b0) || (ier[0] == 1'b0)))
                                            cs_state <=  idle ;
                                end
                            int2 :
                                begin
                                    if (((iir_rd_strobe || (thrr == 1'b0)) || (ier[1] == 1'b0)))
                                        cs_state <=  idle ;
                                end
                            default :
                                cs_state <=  idle ;
                            endcase
                    end// always
            end
    endgenerate
    // ACK signal generate
    always
        @(posedge clk or
            posedge reset)
        if (reset)
            pready <=  1'b0 ;
        else
            if (pready)
                pready <=  1'b0 ;
            else
                if (psel)
                    pready <=  1'b1 ;
    // Set Receiver Line Status Interrupt
    assign dataerr_int = ((cs_state == int0) ? 1'b1 : 1'b0) ;
    // Set Received Data Available Interrupt
    assign rx_rdy_int = ((cs_state == int1) ? 1'b1 : 1'b0) ;
    // Set thr Empty Interrupt
    assign thre_int = ((cs_state == int2) ? 1'b1 : 1'b0) ;
    // Set MODEM Status Interrupt
    // Update IIR
    assign iir = ((cs_state == int0) ? 4'b0110 : ((cs_state == int1) ? 4'b0100 : ((cs_state == int2) ? 4'b0010 : 4'b0001))) ; // No Interrupt Pending//
    localparam lb_size = 256 ;
    generate
        if ((STDOUT_SIM == 1))
            begin : genblk15
                integer lb [(lb_size - 1):0] ;
                integer lb_index ;
                integer display_character ;
                integer total_characters ;
                initial
                    begin
                        for (lb_index = 0 ; (lb_index < lb_size) ; lb_index = (lb_index + 1))
                            lb[lb_index] = 0 ;
                        lb_index = (lb_size - 1) ;
                        total_characters = 0 ;
                    end
                always
                    @(negedge clk)
                    if ((((reset == 1'b0) && wr_strobe) && (pready == 1'b1)))
                        //(ack_o == 1'b0))
                        case (pwdata)
                        10,
                                13 :
                            /*dat_i[7:0]*/
                            // Dump the Line Buffer when we receive a Carriage Return or Line Feed
                            begin
                                lb[lb_index] = "\n" ;
                                total_characters = ((lb_size - 1) - (lb_index - 1)) ;
                                for (lb_index = (lb_size - 1) ; (lb_index > ((lb_size - 1) - total_characters)) ; lb_index = (lb_index - 1))
                                    begin
                                        display_character = lb[lb_index] ;
                                        $write ("%c",
                                                display_character) ;
                                    end
                                for (lb_index = 0 ; (lb_index < lb_size) ; lb_index = (lb_index + 1))
                                    lb[lb_index] = 0 ;
                                lb_index = (lb_size - 1) ;
                                total_characters = 0 ;
                            end
                        default :
                            // All other characters are just added to the Line Buffer.
                            begin
                                lb[lb_index] = pwdata ;//dat_i[7:0];
                                lb_index = (lb_index - 1) ;
                                total_characters = (total_characters + 1) ;
                                // Dump the Line Buffer when it is full
                                if ((total_characters == (lb_size - 1)))
                                    begin
                                        for (lb_index = (lb_size - 1) ; (lb_index >= 0) ; lb_index = (lb_index - 1))
                                            begin
                                                display_character = lb[lb_index] ;
                                                $write ("%c",
                                                        display_character) ;
                                            end
                                        for (lb_index = 0 ; (lb_index < lb_size) ; lb_index = (lb_index + 1))
                                            lb[lb_index] = 0 ;
                                        lb_index = (lb_size - 1) ;
                                        total_characters = 0 ;
                                    end
                            end
                        endcase
            end
    endgenerate
endmodule



