    localparam A_THR = 4'b0000 ;
    localparam A_IER = 4'b0001 ;
    localparam A_IIR = 4'b0010 ;
    localparam A_LCR = 4'b0011 ;
    localparam A_LSR = 4'b0101 ;
    localparam A_DIV = 3'b100 ;
    always
        @(posedge clk or
            posedge reset)
        begin
            if (reset)
                thr_wr <=  1'b0 ;
            else
                thr_wr <=  thr_wr_strobe ;
        end// always
    assign lsr_rd = lsr_rd_strobe ;
    assign rbr_rd_fifo = rbr_rd_strobe ;
    always
        @(posedge clk or
            posedge reset)
        begin
            if (reset)
                rbr_rd_nonfifo <=  1'b0 ;
            else
                rbr_rd_nonfifo <=  rbr_rd_strobe ;
        end// always
    ////////////////////////////////////////////////////////////////////////////////
    // Registers Read/Write Control Signals
    ////////////////////////////////////////////////////////////////////////////////
    generate
        if ((FIFO == 1))
            begin: genblk3
                assign wr_strobe = ((((paddr == A_THR) && psel) && pwrite) && (~fifo_full_thr)) ; // && ~pready;
            end
        else
            begin: genblk3
                assign wr_strobe = (((paddr == A_THR) && psel) && pwrite) ; // && pready;
            end
        if (((STDOUT_SIMFAST == 1) && (STDOUT_SIM == 1)))
            begin : genblk4
                // `ifdef SIMULATION
                //         assign thr_wr_strobe = 1'b0;
                // `else
                //         //assign thr_wr_strobe = wr_strobe;
                //         assign thr_wr_strobe = 1'b0;
                // `endif
                assign thr_wr_strobe = 1'b0 ;
            end
        else
            begin : genblk4
                assign thr_wr_strobe = wr_strobe ;
            end
    endgenerate
    generate
        if ((FIFO == 1))
            begin: genblk5
                assign rbr_rd_strobe = ((((paddr == A_RBR) && psel) && (~pwrite)) && (~fifo_empty)) ; // && ~pready;
            end
        else
            begin: genblk5
                assign rbr_rd_strobe = (((paddr == A_RBR) && psel) && (~pwrite)) ;
            end
    endgenerate
    generate
        if ((FIFO == 1))
            begin: genblk6
                assign iir_rd_strobe = (((paddr == A_IIR) && psel) && (~pwrite)) ; // && ~pready;
            end
        else
            begin: genblk6
                assign iir_rd_strobe = (((paddr == A_IIR) && psel) && (~pwrite)) ;
            end
    endgenerate
    generate
        if ((FIFO == 1))
            begin: genblk7
                assign lsr_rd_strobe = (((paddr == A_LSR) && psel) && (~pwrite)) ; // && ~pready;
            end
        else
            begin: genblk7
                assign lsr_rd_strobe = (((paddr == A_LSR) && psel) && (~pwrite)) ;
            end
    endgenerate
    assign div_wr_strobe = ((((paddr[3:1] == A_DIV) && psel) && pwrite) && penable) ; // && pready;
    ////////////////////////////////////////////////////////////////////////////////
    // Registers Read/Write Operation
    ////////////////////////////////////////////////////////////////////////////////
    generate
        if ((FIFO == 1))
            begin : fifo_regrd
                //   always @(cyc_i or stb_i or we_i or adr_i or rbr_fifo or iir
                //`ifdef MODEM
                //        or msr
                //`endif
                //        or lsr)
                always
                    @(*)
                    begin
                        case (paddr)
                        A_RBR :
                            data_8bit <=  rbr_fifo ;
                        A_IER :
                            data_8bit <=  {5'b00000,
                                    ier} ;
                        A_IIR :
                            data_8bit <=  {4'b1100,
                                    iir} ;
                        A_LCR :
                            // Indicates FIFOs are enabled
                            data_8bit <=  {1'b0,
                                    lcr} ;
                        A_LSR :
                            data_8bit <=  {1'b0,
                                    lsr} ;
                        default :
                            data_8bit <=  8'b00000000 ;
                        endcase
                    end
            end
        else
            begin : nfifo_regrd
                // Register Read
                always
                    @(posedge clk or
                        posedge reset)
                    begin
                        if (reset)
                            data_8bit <=  8'b00000000 ;
                        else
                            //          else if (cyc_i && stb_i && ~we_i)
                            if ((psel && (~pwrite)))
                                case (paddr)
                                A_RBR :
                                    data_8bit <=  rbr ;
                                A_IER :
                                    data_8bit <=  {5'b00000,
                                            ier} ;
                                A_IIR :
                                    data_8bit <=  {4'b0000,
                                            iir} ;
                                A_LCR :
                                    data_8bit <=  {1'b0,
                                            lcr} ;
                                A_LSR :
                                    data_8bit <=  {1'b0,
                                            lsr} ;
                                default :
                                    data_8bit <=  8'b00000000 ;
                                endcase
                    end// always
            end
    endgenerate
    //   assign dat_o = data_8bit;
    assign prdata = data_8bit ;
    generate
        if ((FIFO == 0))
            begin : nfifo_regwr
                always
                    @(posedge clk or
                        posedge reset)
                    begin
                        if (reset)
                            begin
                                thr_nonfifo <=  {BUS_DAT_WIDTH{1'b0}} ;
                                ier <=  3'b000 ;
                                lcr <=  lcr_default ;
                            end
                        else
                            //          else if (cyc_i && stb_i && we_i) begin
                            if (((psel && pwrite) && penable))
                                begin
                                    case (paddr)
                                    A_THR :
                                        thr_nonfifo <=  pwdata[(BUS_DAT_WIDTH - 1):0] ;
                                    A_IER :
                                        ier <=  pwdata[2:0] ;
                                    A_LCR :
                                        lcr <=  pwdata[6:0] ;
                                    default :
                                        ;
                                    endcase
                                end
                    end// always
            end
        else
            begin : fifo_regwr
                always
                    @(posedge clk or
                        posedge reset)
                    begin
                        if (reset)
                            begin
                                ier <=  3'b000 ;
                                lcr <=  lcr_default ;
                            end
                        else
                            //          else if (cyc_i && stb_i && we_i)
                            if (((psel && pwrite) && penable))
                                case (paddr)
                                A_IER :
                                    ier <=  pwdata[2:0] ;
                                A_LCR :
                                    lcr <=  pwdata[6:0] ;
                                default :
                                    ;
                                endcase
                    end// always
            end
    endgenerate
    generate
        if ((FIFO == 1))
            begin : tx_fifo_inst
                assign fifo_wr_pulse_thr = thr_wr_strobe ;
                assign fifo_din_thr = pwdata ; //dat_i[7:0];
                cpu0_ipgen_lscc_uart_txcver_fifo TX_FIFO (.Data(fifo_din_thr),
                            .Clock(clk),
                            .WrEn(fifo_wr_pulse_thr),
                            .RdEn(thr_rd),
                            .Reset(reset),
                            .Q(thr_fifo),
                            .Empty(fifo_empty_thr),
                            .Full(fifo_full_thr),
                            .AlmostEmpty(fifo_almost_empty_thr),
                            .AlmostFull(fifo_almost_full_thr)) ;
            end
    endgenerate
    ////////////////////////////////////////////////////////////////////////////////
    //  Line Control Register
    ////////////////////////////////////////////////////////////////////////////////
    // databits : "00"=5-bit, "01"=6-bit, "10"=7-bit, "11"=8-bit
    assign databits = lcr[1:0] ;
    // stopbits : "00"=1-bit, "01"=1.5-bit(5-bit data), "10"=2-bit(6,7,8-bit data)
    assign stopbits = ((lcr[2] == 1'b0) ? 2'b00 : ((lcr[2:0] == 3'b100) ? 2'b01 : 2'b10)) ;
    // parity_en : '0'=Parity Bit Enable, '1'=Parity Bit Disable
    assign parity_en = lcr[3] ;
    // parity_even : '0'=Even Parity Selected, '1'=Odd Parity Selected
    assign parity_even = lcr[4] ;
    // parity_stick : '0'=Stick Parity Disable, '1'=Stick Parity Enable
    assign parity_stick = lcr[5] ;
    // tx_break : '0'=Disable BREAK assertion, '1'=Assert BREAK
    assign tx_break = lcr[6] ;
    ////////////////////////////////////////////////////////////////////////////////
    //  Line Status Register
    ////////////////////////////////////////////////////////////////////////////////
    generate
        if ((FIFO == 1))
            begin : fifo_lsr
                always
                    @(posedge clk or
                        posedge reset)
                    if (reset)
                        lsr2_r <=  1'b0 ;
                    else
                        if (parity_err)
                            lsr2_r <=  1'b1 ;
                        else
                            if (lsr_rd_strobe)
                                lsr2_r <=  1'b0 ;
                always
                    @(posedge clk or
                        posedge reset)
                    if (reset)
                        lsr3_r <=  1'b0 ;
                    else
                        if (frame_err)
                            lsr3_r <=  1'b1 ;
                        else
                            if (lsr_rd_strobe)
                                lsr3_r <=  1'b0 ;
                always
                    @(posedge clk or
                        posedge reset)
                    if (reset)
                        lsr4_r <=  1'b0 ;
                    else
                        if (break_int)
                            lsr4_r <=  1'b1 ;
                        else
                            if (lsr_rd_strobe)
                                lsr4_r <=  1'b0 ;
                always
                    @(posedge clk)
                    lsr <=  {temt,
                            thrr,
                            lsr4_r,
                            lsr3_r,
                            lsr2_r,
                            overrun_err,
                            rx_rdy} ;
            end
        else
            begin : nfifo_lsr
                always
                    @(temt or
                        thrr or
                        break_int or
                        frame_err or
                        parity_err or
                        overrun_err or
                        rx_rdy)
                    lsr = {temt,
                            thrr,
                            break_int,
                            frame_err,
                            parity_err,
                            overrun_err,
                            rx_rdy} ;
            end
    endgenerate
    ////////////////////////////////////////////////////////////////////////////////
    // Interrupt Arbitrator
    ////////////////////////////////////////////////////////////////////////////////
    // Int is the common interrupt line for all internal UART events
    always
        @(posedge clk or
            posedge reset)
        begin
            if (reset)
                intr <=  1'b0 ;
            else
                intr <=  ((rx_rdy_int | thre_int) | dataerr_int) ;
        end// always
    // Receiving Data Error Flags including Overrun, Parity, Framing and Break
    generate
        if ((FIFO == 1))
            begin: genblk12
                assign data_err = (((overrun_err | lsr2_r) | lsr3_r) | lsr4_r) ;
            end
        else
            begin: genblk12
                assign data_err = (((overrun_err | parity_err) | frame_err) | break_int) ;
            end
    endgenerate
    // Whenever bit0, 1, 2,or 3 is set to '1', A_WB Modem Status Interrupt is generated
    generate
        if ((FIFO == 1))
            begin: genblk13
                always
                    @(posedge clk or
                        posedge reset)
                    if (reset)
                        iir_rd_strobe_delay <=  1'b0 ;
                    else
                        iir_rd_strobe_delay <=  iir_rd_strobe ;
            end
    endgenerate
    // State Machine Definition
    localparam idle = 3'b000 ;
    localparam int0 = 3'b001 ;
    localparam int1 = 3'b010 ;
    localparam int2 = 3'b011 ;
    localparam int3 = 3'b100 ;
    reg [2:0] cs_state ;
    generate
        if ((FIFO == 1))
            begin : fifo_int
                always
                    @(posedge clk or
                        posedge reset)
                    begin
                        if (reset)
                            cs_state <=  idle ;
                        else
                            case (cs_state)
                            idle :
                                begin
                                    if (((ier[2] == 1'b1) && (data_err == 1'b1)))
                                        cs_state <=  int0 ;
                                    else
                                        if (((ier[0] == 1'b1) && (fifo_almost_full || (!fifo_empty))))
                                            cs_state <=  int1 ;
                                        else
                                            if (((ier[1] == 1'b1) && (thrr == 1'b1)))
                                                cs_state <=  int2 ;
                                end
                            int0 :
                                begin
                                    if (((lsr_rd_strobe == 1'b1) || (ier[2] == 1'b0)))
                                        begin
                                            if (((ier[0] == 1'b1) && fifo_almost_full))
                                                cs_state <=  int1 ;
                                            else
                                                cs_state <=  idle ;
                                        end
                                end
                            int1 :
                                begin
                                    if (((data_err == 1'b1) && (ier[2] == 1'b1)))
                                        cs_state <=  int0 ;
                                    else
                                        if (((!fifo_almost_full) || (ier[0] == 1'b0)))
                                            cs_state <=  idle ;
                                end
                            int2 :
                                begin
                                    if (((iir_rd_strobe_delay || (thrr == 1'b0)) || (ier[1] == 1'b0)))
