            begin : nfifo_int
                always
                    @(posedge clk or
                        posedge reset)
                    begin
                        if (reset)
                            cs_state <=  idle ;
                        else
                            case (cs_state)
                            idle :
                                begin
                                    if (((ier[2] == 1'b1) && (data_err == 1'b1)))
                                        cs_state <=  int0 ;
                                    else
                                        if (((ier[0] == 1'b1) && (rx_rdy == 1'b1)))
                                            cs_state <=  int1 ;
                                        else
                                            if (((ier[1] == 1'b1) && (thrr == 1'b1)))
                                                cs_state <=  int2 ;
                                end
                            int0 :
                                begin
                                    if (((lsr_rd_strobe == 1'b1) || (ier[2] == 1'b0)))
                                        begin
                                            if (((ier[0] == 1'b1) && rx_rdy))
                                                cs_state <=  int1 ;
                                            else
                                                cs_state <=  idle ;
                                        end
                                end
                            int1 :
                                begin
                                    if (((data_err == 1'b1) && (ier[2] == 1'b1)))
                                        cs_state <=  int0 ;
                                    else
                                        if (((rx_rdy == 1'b0) || (ier[0] == 1'b0)))
                                            cs_state <=  idle ;
                                end
                            int2 :
                                begin
                                    if (((iir_rd_strobe || (thrr == 1'b0)) || (ier[1] == 1'b0)))
