                        if (((reset == 1'b0) && wr_strobe))
                            /* && (pready == 1'b1)*/
                            begin
                                //(ack_o == 1'b0))
                                case (pwdata)
                                10,
                                        13 :
                                    /*dat_i[7:0]*/
                                    begin
                                        // Dump the Line Buffer when we receive a Carriage Return or Line Feed
                                        lb[lb_index] = "\n" ;
                                        total_characters = ((lb_size - 1) - (lb_index - 1)) ;
                                        for (lb_index = (lb_size - 1) ; (lb_index > ((lb_size - 1) - total_characters)) ; lb_index = (lb_index - 1))
                                            begin
                                                display_character = lb[lb_index] ;
                                                $write ("%c",
                                                        display_character) ;
                                            end
                                        for (lb_index = 0 ; (lb_index < lb_size) ; lb_index = (lb_index + 1))
                                            begin
                                                lb[lb_index] = 0 ;
                                            end
                                        lb_index = (lb_size - 1) ;
                                        total_characters = 0 ;
                                    end
                                default :
                                    begin
                                        // All other characters are just added to the Line Buffer.
                                        lb[lb_index] = pwdata ;//dat_i[7:0];
                                        lb_index = (lb_index - 1) ;
                                        total_characters = (total_characters + 1) ;
                                        // Dump the Line Buffer when it is full
                                        if ((total_characters == (lb_size - 1)))
                                            begin
                                                for (lb_index = (lb_size - 1) ; (lb_index >= 0) ; lb_index = (lb_index - 1))
                                                    begin
                                                        display_character = lb[lb_index] ;
                                                        $write ("%c",
                                                                display_character) ;
                                                    end
                                                for (lb_index = 0 ; (lb_index < lb_size) ; lb_index = (lb_index + 1))
                                                    begin
                                                        lb[lb_index] = 0 ;
                                                    end
                                                lb_index = (lb_size - 1) ;
                                                total_characters = 0 ;
                                            end
                                    end
                                endcase
                            end
                    end
            end
    endgenerate
endmodule



