//
// =============================================================================
//                        REVISION HISTORY
// Version      : 1.0
// Changes Made : Initial Creation
//
// Version      : 7.0SP2
// Changes Made : No Change
//
// Version      : 7.1, 3.0
// Changes Made : Fix one TSR bit setting issue, only update it after STOP bit is
//                totally shifted out.
//
// Version      : 3.1
// Changes Made : Initial Creation
//                Baudrate Generation is modified.
//                RX and TX path of the UART is updated to faster clock
//                16 word deep FIFO is implemented when FIFO option is
//                selected
//
// Version      : 3.5
// Changes Made : WISHBONE Data Bus can be 8 bits or 32 bits. All UART registers
//                occupy byte instead of 4 bytes (i.e. registers are accessible
//                using 3 bits only instead of original 5 bits).
//
// Version      : 3.7
// Changes Made : Bug fixed for the TX FIFO cannot accept new data if TX FIFO is
//                not empty. New FIFO supports Transmitter Hold Register Ready bit
//                instead of Tranmitter Hold Register Empty bit.
// ============================================================================
module cpu0_ipgen_lscc_uart_txmitt #(parameter UART_WB_DAT_WIDTH = 8,
        parameter FIFO = 0) (reset,  // Global reset and clock
    clk,
        thr,  // Register THR
    thr_wr,  // THR write strobe
    sout,  // Transmitter output
    databits,  // Transmitter control
    stopbits,
        parity_en,
        parity_even,
        parity_stick,
        tx_break,
        thrr,  // Transmitter status
    temt,
        fifo_empty_thr,
        fifo_full_thr,
        thr_rd,
        thr_ready,
        divisor) ;
    input reset ;
    input clk ;
    input [(UART_WB_DAT_WIDTH - 1):0] thr ;
    input thr_wr ;
    input [1:0] databits ;
    input [1:0] stopbits ;
    input parity_en ;
    input parity_even ;
    input parity_stick ;
    input tx_break ;
    input fifo_empty_thr ;
    input fifo_full_thr ;
    output thr_rd ;
    output thrr ;
    output temt ;
    output sout ;
    output reg thr_ready ;
    input [15:0] divisor ;
    reg tx_output ;
    reg [(UART_WB_DAT_WIDTH - 1):0] tsr ;
    reg tx_parity ;
    reg tsr_empty ;
    reg thr_empty ;
    reg tx_in_start_s ;
    reg tx_in_shift_s ;
    reg tx_in_stop_s ;
    reg tx_in_shift_s1 ; //tx_in_shift_s delayed 1 clock
    reg tx_in_stop_s1 ; //tx_in_stop_s delayed 1 clock
    reg txclk_ena ;
    reg txclk_enb ;
    reg [2:0] tx_cnt ;
    reg [3:0] count_v ;
    reg thr_rd_int ;
    reg thr_rd_delay ;
    reg last_word ;
    // State Machine Definition - 1hot encoding
    localparam ST_W = 7 ;
    localparam start = 7'h01 ;
    localparam shift = 7'h02 ;
    localparam parity = 7'h04 ;
    localparam stop_1bit = 7'h08 ;
    localparam stop_2bit = 7'h10 ;
    localparam stop_halfbit = 7'h20 ;
    localparam start1 = 7'h40 ;
    reg [(ST_W - 1):0] tx_state ;
    reg [15:0] counter ;
    wire [15:0] divisor_2 ;
    wire [15:0] counter_minus_1 ;
    wire counter_eq_0 ;
    wire counter_eq_1 ;
    assign divisor_2 = {1'b0,
                divisor[15:1]} ;
    assign counter_eq_0 = (~|counter) ;
    assign counter_eq_1 = (counter == 16'b0000_0000_0000_0001) ;
    assign counter_minus_1 = (counter - 1'b1) ;
    generate
        if ((FIFO == 1))
            begin: genblk1
                // Generate Single cycle THR FIFO read signal
                always
                    @(posedge clk or
                        posedge reset)
                    if (reset)
                        thr_rd_delay <=  1'b0 ;
                    else
                        thr_rd_delay <=  thr_rd_int ;
            end
        assign thr_rd = (thr_rd_int & (~thr_rd_delay)) ;
    endgenerate
    ////////////////////////////////////////////////////////////////////////////////
    // Transmitter Finite State Machine
    ////////////////////////////////////////////////////////////////////////////////
    generate
        if ((FIFO == 1))
            begin : fifo_fsm
                always
                    @(posedge clk or
                        posedge reset)
                    begin
                        if (reset)
                            thr_rd_int <=  1'b0 ;
                        else
                            begin
                                if ((((tx_state == start) && (!fifo_empty_thr)) && (!thr_rd_int)))
                                    thr_rd_int <=  1'b1 ;
                                else
                                    if ((tx_state == shift))
                                        thr_rd_int <=  1'b0 ;
                            end
                    end// always
                always
                    @(posedge clk or
                        posedge reset)
                    begin
                        if (reset)
                            begin
                                tx_cnt <=  0 ;
                                tsr <=  0 ;
                                tx_output <=  1'b1 ;
                                tx_parity <=  1'b1 ;
                                tx_state <=  start ;
                                last_word <=  1'b0 ;
                                counter <=  16'b0000000000000000 ;
                            end
                        else
                            begin
                                case (tx_state)
                                start :
                                    begin
                                        if (thr_rd_delay)
                                            tx_state <=  start1 ;
                                    end
                                start1 :
                                    begin
                                        if (last_word)
                                            last_word <=  1'b0 ;
                                        if (counter_eq_0)
                                            counter <=  divisor ;
                                        else
                                            begin
                                                if (counter_eq_1)
                                                    begin
                                                        counter <=  0 ;
                                                        tx_state <=  shift ;
                                                        tx_parity <=  (~parity_even) ;// TxParity initialization
                                                        tx_cnt <=  0 ;
                                                        tsr <=  thr ;
                                                    end
                                                else
                                                    counter <=  counter_minus_1 ;
                                            end
                                        tx_output <=  1'b0 ;
                                    end
                                shift :
                                    begin
                                        tx_output <=  tsr[0] ;
                                        if (counter_eq_0)
                                            counter <=  divisor ;
                                        else
                                            begin
                                                if (counter_eq_1)
                                                    begin
                                                        tx_parity <=  (tx_parity ^ tsr[0]) ;
                                                        counter <=  0 ;
                                                        tsr <=  {1'b0,
                                                                tsr[7:1]} ;// Shift serial data out
                                                        tx_cnt <=  (tx_cnt + 1) ;
                                                        if ((((((databits == 2'b00) && (tx_cnt == 3'h4)) || ((databits == 2'b01) && (tx_cnt == 3'h5))) || ((databits == 2'b10) && (tx_cnt == 3'h6))) || ((databits == 2'b11) && (tx_cnt == 3'h7))))
                                                            tx_state <=  (parity_en ? parity : stop_1bit) ;
                                                    end
                                                else
                                                    counter <=  counter_minus_1 ;
                                            end
                                    end
                                parity :
                                    begin
                                        if (counter_eq_0)
                                            counter <=  divisor ;
                                        else
                                            begin
                                                if (counter_eq_1)
                                                    begin
                                                        counter <=  0 ;
                                                        tx_state <=  stop_1bit ;
                                                    end
                                                else
                                                    counter <=  counter_minus_1 ;
                                            end
                                        tx_output <=  (parity_stick ? (~parity_even) : tx_parity) ;
                                    end
                                stop_1bit :
                                    begin
                                        if (counter_eq_0)
                                            counter <=  divisor ;
                                        else
                                            begin
                                                if (counter_eq_1)
                                                    begin
                                                        counter <=  0 ;
                                                        if (fifo_empty_thr)
                                                            last_word <=  1'b1 ;
                                                        if ((stopbits == 2'b00)) // 2 stop bits(for 6,7,8-bit data)
                                                            // 1 stop bit
                                                            tx_state <=  start ;
                                                        else
                                                            if ((stopbits == 2'b01))
                                                                // 1.5 stop bits(for 5-bit data only)
                                                                tx_state <=  stop_halfbit ;
                                                            else
                                                                tx_state <=  stop_2bit ;
                                                    end
                                                else
                                                    counter <=  counter_minus_1 ;
                                            end
                                        tx_output <=  1'b1 ;
                                    end
                                stop_2bit :
                                    begin
                                        if (counter_eq_0)
                                            counter <=  divisor ;
                                        else
                                            begin
                                                if (counter_eq_1)
                                                    begin
                                                        counter <=  0 ;
                                                        tx_state <=  start ;
                                                    end
                                                else
                                                    counter <=  counter_minus_1 ;
                                            end
                                        tx_output <=  1'b1 ;
                                    end
                                stop_halfbit :
                                    begin
                                        if (counter_eq_0)
                                            counter <=  divisor_2 ;
                                        else
                                            begin
                                                if (counter_eq_1)
                                                    begin
                                                        counter <=  0 ;
                                                        tx_state <=  start ;
                                                    end
                                                else
                                                    counter <=  counter_minus_1 ;
                                            end
                                        tx_output <=  1'b1 ;
                                    end
                                default :
                                    tx_state <=  start ;
                                endcase
                            end
                    end// always
            end
        else
            begin : nfifo_fsm
                always
                    @(posedge clk or
                        posedge reset)
                    begin
                        if (reset)
                            begin
                                tx_cnt <=  0 ;
                                tsr <=  0 ;
                                tx_output <=  1'b1 ;
                                tx_parity <=  1'b1 ;
                                tx_state <=  start ;
                                counter <=  16'b0000000000000000 ;
                            end
                        else
                            begin
                                case (tx_state)
                                start :
                                    begin
                                        if ((!thr_ready))
                                            tx_state <=  start1 ;
                                    end
                                start1 :
                                    begin
                                        if (counter_eq_0)
                                            counter <=  divisor ;
                                        else
                                            begin
                                                if (counter_eq_1)
                                                    begin
                                                        counter <=  0 ;
                                                        tx_state <=  shift ;
                                                        tx_parity <=  (~parity_even) ;// TxParity initialization
                                                        tx_cnt <=  0 ;
                                                        tsr <=  thr ;
                                                    end
                                                else
                                                    counter <=  counter_minus_1 ;
                                            end
                                        tx_output <=  1'b0 ;
                                    end
                                shift :
                                    begin
                                        tx_output <=  tsr[0] ;
                                        if (counter_eq_0)
                                            counter <=  divisor ;
                                        else
                                            begin
                                                if (counter_eq_1)
                                                    begin
                                                        tx_parity <=  (tx_parity ^ tsr[0]) ;
                                                        counter <=  0 ;
                                                        tsr <=  {1'b0,
                                                                tsr[7:1]} ;// Shift serial data out
                                                        tx_cnt <=  (tx_cnt + 1) ;
                                                        if ((((((databits == 2'b00) && (tx_cnt == 3'h4)) || ((databits == 2'b01) && (tx_cnt == 3'h5))) || ((databits == 2'b10) && (tx_cnt == 3'h6))) || ((databits == 2'b11) && (tx_cnt == 3'h7))))
                                                            tx_state <=  (parity_en ? parity : stop_1bit) ;
                                                    end
                                                else
                                                    counter <=  counter_minus_1 ;
                                            end
                                    end
                                parity :
                                    begin
                                        if (counter_eq_0)
                                            counter <=  divisor ;
                                        else
                                            begin
                                                if (counter_eq_1)
                                                    begin
                                                        counter <=  0 ;
                                                        tx_state <=  stop_1bit ;
                                                    end
                                                else
                                                    counter <=  counter_minus_1 ;
                                            end
                                        tx_output <=  (parity_stick ? (~parity_even) : tx_parity) ;
                                    end
                                stop_1bit :
                                    begin
                                        if (counter_eq_0)
                                            counter <=  divisor ;
                                        else
                                            begin
                                                if (counter_eq_1)
                                                    begin
                                                        counter <=  0 ;
                                                        if ((stopbits == 2'b00)) // 2 stop bits(for 6,7,8-bit data)
                                                            // 1 stop bit
                                                            tx_state <=  start ;
                                                        else
                                                            if ((stopbits == 2'b01))
                                                                // 1.5 stop bits(for 5-bit data only)
                                                                tx_state <=  stop_halfbit ;
                                                            else
                                                                tx_state <=  stop_2bit ;
                                                    end
                                                else
                                                    counter <=  counter_minus_1 ;
                                            end
                                        tx_output <=  1'b1 ;
                                    end
                                stop_2bit :
                                    begin
                                        if (counter_eq_0)
                                            counter <=  divisor ;
                                        else
                                            begin
                                                if (counter_eq_1)
                                                    begin
                                                        counter <=  0 ;
                                                        tx_state <=  start ;
                                                    end
                                                else
                                                    counter <=  counter_minus_1 ;
                                            end
                                        tx_output <=  1'b1 ;
                                    end
                                stop_halfbit :
                                    begin
                                        if (counter_eq_0)
                                            counter <=  divisor_2 ;
                                        else
                                            begin
                                                if (counter_eq_1)
                                                    begin
                                                        counter <=  0 ;
                                                        tx_state <=  start ;
                                                    end
                                                else
                                                    counter <=  counter_minus_1 ;
                                            end
                                        tx_output <=  1'b1 ;
                                    end
                                default :
                                    tx_state <=  start ;
                                endcase
                            end
                    end
            end
    endgenerate
    ////////////////////////////////////////////////////////////////////////////////
    // Generate tsr_empty and thr_empty signals
    ////////////////////////////////////////////////////////////////////////////////
    // tsr_empty : will be set whenever tsr is empty
    generate
        begin : genblk3
            if ((FIFO == 1))
                begin : genblk1
                    always
                        @(posedge clk or
                            posedge reset)
                        begin
                            if (reset)
                                tsr_empty <=  1'b1 ;
                            else
                                if ((((tx_in_stop_s == 1'b0) && (tx_in_stop_s1 == 1'b1)) && last_word))
                                    tsr_empty <=  1'b1 ;
                                else
                                    // Set TsrEmpty flag to '1' when StopBit(s) is all transmitted
                                    if (((tx_in_shift_s == 1'b1) && (tx_in_shift_s1 == 1'b0))) //Reset TsrEmpty flag to '0' when data is transferred from THR to TSR
                                        tsr_empty <=  1'b0 ;
                        end
                end
            else
                begin : genblk1
                    always
                        @(posedge clk or
                            posedge reset)
                        begin
                            if (reset)
                                tsr_empty <=  1'b1 ;
                            else
                                if (((tx_in_stop_s == 1'b0) && (tx_in_stop_s1 == 1'b1)))
                                    tsr_empty <=  1'b1 ;
                                else
                                    // Set TsrEmpty flag to '1' when StopBit(s) is all transmitted
                                    if (((tx_in_shift_s == 1'b1) && (tx_in_shift_s1 == 1'b0))) //Reset TsrEmpty flag to '0' when data is transferred from THR to TSR
                                        tsr_empty <=  1'b0 ;
                        end
                end
        end
    endgenerate
    generate
        if ((FIFO == 1))
            begin : genblk4
                always
                    @(posedge clk or
                        posedge reset)
                    begin
                        if (reset)
                            thr_empty <=  1'b1 ;
                        else
                            if (thr_wr)
                                thr_empty <=  1'b0 ;
                            else
                                // Reset ThrEmpty flag to '0' when data is written into THR by CPU
                                if (((fifo_empty_thr && tx_in_shift_s) && (!tx_in_shift_s1)))
                                    // Set ThrEmpty flag to '1' THR FIFO is empty
                                    thr_empty <=  1'b1 ;
                    end
            end
        else
            begin : genblk4
                always
                    @(posedge clk or
                        posedge reset)
                    begin
                        if (reset)
                            thr_empty <=  1'b1 ;
                        else
                            if (thr_wr)
                                thr_empty <=  1'b0 ;
                            else
                                // Reset ThrEmpty flag to '0' when data is written into THR by CPU
                                if ((tx_in_shift_s && (!tx_in_shift_s1)))
                                    // Set ThrEmpty flag to '1' when data is transferred from THR to TSR
                                    thr_empty <=  1'b1 ;
                    end
            end
    endgenerate
    ////////////////////////////////////////////////////////////////////////////////
    // Generate thr_ready signals
    ////////////////////////////////////////////////////////////////////////////////
    generate
        if ((FIFO == 1))
            begin : fifo_thrrdy
                always
                    @(posedge clk or
                        posedge reset)
                    begin
                        if (reset) // Reset thr_ready flag to '1' when THR FIFO is not full
                            thr_ready <=  1'b1 ;
                        else
                            thr_ready <=  (~fifo_full_thr) ;
                    end
            end
        else
            begin : nfifo_thrrdy
                always
                    @(posedge clk or
                        posedge reset)
                    begin
                        if (reset)
                            thr_ready <=  1'b1 ;
                        else
                            if (thr_wr)
                                thr_ready <=  1'b0 ;
                            else
                                // Reset thr_ready flag to '0' when data is written into THR by CPU
                                if ((tx_in_shift_s && (!tx_in_shift_s1)))
                                    // Set thr_ready flag to '1' when data is transferred from THR to TSR
                                    thr_ready <=  1'b1 ;
                    end
            end
    endgenerate
    ////////////////////////////////////////////////////////////////////////////////
    // Delayed signals for edge detections
    ////////////////////////////////////////////////////////////////////////////////
    always
        @(posedge clk or
            posedge reset)
        begin
            if (reset)
                begin
                    tx_in_shift_s1 <=  1'b0 ;
                    tx_in_stop_s1 <=  1'b0 ;
                end
            else
                begin
                    tx_in_shift_s1 <=  tx_in_shift_s ;
                    tx_in_stop_s1 <=  tx_in_stop_s ;
                end
        end
    ////////////////////////////////////////////////////////////////////////////////
    // Transmitter FSM state indication signals
    ////////////////////////////////////////////////////////////////////////////////
    // tx_in_shift_s : will be set whenever transmitter is in shift state
    always
        @(posedge clk or
            posedge reset)
        begin
            if (reset)
                tx_in_shift_s <=  1'b0 ;
            else
                if ((tx_state == shift))
                    tx_in_shift_s <=  1'b1 ;
                else
                    tx_in_shift_s <=  1'b0 ;
        end
    // tx_in_stop_s : will be set whenever transmitter is in stop_1bit state
    always
        @(posedge clk or
            posedge reset)
        begin
            if (reset)
                tx_in_stop_s <=  1'b0 ;
            else
                if ((tx_state == stop_1bit))
                    tx_in_stop_s <=  1'b1 ;
                else
                    tx_in_stop_s <=  1'b0 ;
        end
    ////////////////////////////////////////////////////////////////////////////////
    // Generate thrr/temt flags
    ////////////////////////////////////////////////////////////////////////////////
    // Transmitter Holding Register Ready Indicator
    //assign thrr = thr_ready;
    assign thrr = thr_empty ; // UART 16550 definition of THRE
    // Transmitter Empty Indicator is set to '1' whenever thr and tsr are
    // both empty, and reset to '0' when either thr or tsr contain a character
    assign temt = (((thr_empty == 1'b1) && (tsr_empty == 1'b1)) ? 1'b1 : 1'b0) ;
    // Serial Data Output
    // If Break Control bit is set to 1, the serial output is forced to Zero
    assign sout = ((tx_break == 1'b1) ? 1'b0 : tx_output) ;
endmodule



`resetall
`timescale 1ns/1ps
// TXMITT_FILE
module cpu0_ipgen_lscc_uart #(parameter APB_ENABLE = 0,
        parameter SYS_CLOCK_FREQ = 50000000,
        parameter BAUD_RATE = 115200,
        parameter CLK_DIVISOR = (SYS_CLOCK_FREQ / BAUD_RATE),
        parameter BUS_ADR_WIDTH = 6,
        parameter BUS_DAT_WIDTH = 32,
        parameter FIFO = 0,
        parameter LCR_DATA_BITS = 8,
        parameter LCR_STOP_BITS = 1,
        parameter LCR_PARITY_ENABLE = 0,
        parameter LCR_PARITY_ODD = 0,
        parameter LCR_PARITY_STICK = 0,
        parameter LCR_SET_BREAK = 0,
        parameter STDOUT_SIM = 0,
        parameter STDOUT_SIMFAST = 0,
        parameter MODEM_ENA = 0) (
    // Set this instead when SYS_CLOCK_FREQ is floating point
    // Not supported for this release
    //    parameter RXRDY_ENA         = 0,
    //    parameter TXRDY_ENA         = 0
    input clk,
    input resetn,
    // -----------------------------------------
    // APB Interface
    // -----------------------------------------
    // -----------------------------------------
    // Local Bus Interface
    // -----------------------------------------
    input lb_cmd_valid,
    output lb_cmd_ready,
    input lb_cmd_wr,
    input [(BUS_ADR_WIDTH - 1):0] lb_cmd_address,
    input [(BUS_DAT_WIDTH - 1):0] lb_cmd_data,
    input [1:0] lb_cmd_size,
    output lb_rsp_ready,
    output lb_rsp_error,
    output [(BUS_DAT_WIDTH - 1):0] lb_rsp_data,
    output INTR,
    // Receiver interface
    input SIN,
    //`ifdef RXRDY_ENABLE
    output RXRDY_N,
    //`endif
    // Modem interface
    //`ifdef MODEM
    input DCD_N,
    input CTS_N,
    input DSR_N,
    input RI_N,
    output DTR_N,
    output RTS_N,
    //`endif
    // Transmitter interface
    //`ifdef TXRDY_ENABLE
    output TXRDY_N,
    //`endif
    output SOUT) ;
    wire apb_psel_i ;
    wire [(BUS_ADR_WIDTH - 1):0] apb_paddr_i ;
    wire [(BUS_DAT_WIDTH - 1):0] apb_pwdata_i ;
    wire apb_pwrite_i ;
    wire apb_penable_i ;
    wire apb_pready_o ;
    wire [(BUS_DAT_WIDTH - 1):0] apb_prdata_o ;
    wire apb_pslverr_o ;
    wire CLK = clk ;
    wire RESET = (~resetn) ;
    wire thr_ready ;
    wire [7:0] prdata_uart ;
    assign apb_pslverr_o = 1'b0 ;
    assign apb_prdata_o = {24'h0,
                prdata_uart} ;
    //`ifndef RXRDY_ENABLE
    //   wire            RXRDY_N;
    //`endif
    //`ifndef TXRDY_ENABLE
    //   wire            TXRDY_N;
    //`endif
    wire [7:0] RBR_FIFO ;
    wire [7:0] RBR ;
    wire [7:0] THR ;
    wire [1:0] databits ;
    wire [1:0] stopbits ;
    wire parity_en ;
    wire parity_stick ;
    wire tx_break ;
    wire thr_wr ;
    wire rbr_rd ;
    wire lsr_rd ;
    wire rx_rdy ;
    wire parity_err ;
    wire frame_err ;
    wire overrun_err ;
    wire break_int ;
    wire THRR ;
    wire TEMT ;
    wire fifo_empty ;
    wire fifo_empty_thr ;
    wire fifo_full_thr ;
    wire thr_rd ;
    wire fifo_almost_full ;
    wire [15:0] divisor ;
    wire intr ;
    //   assign               UART_RTY_O = 1'b0;
    //   assign               UART_ERR_O = 1'b0;
    generate
        if ((APB_ENABLE == 1))
            begin : genblk1
                cpu0_ipgen_lscc_uart_apb_intface #(.CLK_IN_MHZ(SYS_CLOCK_FREQ),
                        .BAUD_RATE(BAUD_RATE),
                        .CLK_DIVISOR(CLK_DIVISOR),
                        .UART_WB_ADR_WIDTH((BUS_ADR_WIDTH - 2)),
                        .UART_WB_DAT_WIDTH(8),
                        .FIFO(FIFO),
                        .LCR_DATA_BITS(LCR_DATA_BITS),
                        .LCR_STOP_BITS(LCR_STOP_BITS),
                        .LCR_PARITY_ENABLE(LCR_PARITY_ENABLE),
                        .LCR_PARITY_ODD(LCR_PARITY_ODD),
                        .LCR_PARITY_STICK(LCR_PARITY_STICK),
