`timescale 1ns/1ps
module cpu0_ipgen_dffr #(parameter DW = 32) (
    input [(DW - 1):0] dnxt,
    output [(DW - 1):0] qout,
    input clk,
    input rst_n) ;
    reg [(DW - 1):0] qout_r ;
    always
        @(posedge clk or
            negedge rst_n)
        begin : DFFR_PROC
            if ((rst_n == 1'b0))
                qout_r <=  {DW{1'b0}} ;
            else
                qout_r <= #(1)   dnxt ;
        end
    assign qout = qout_r ;
endmodule



`timescale 1ns/1ps
/** generate interrupt pending
*  1. assert IP
*  2. target 'claims IP'
*     clears IP bit
*     blocks IP from asserting again
*  3. target 'completes'
*/
module cpu0_ipgen_gateway #(parameter ADDR_WIDTH = 32,
        parameter DATA_WIDTH = 32,
        parameter IRQ_NUM = 32,
        parameter HART_NUM = 2,
        parameter PRIORITY_W = 3,
        parameter IRQ_ARRAY = (((IRQ_NUM - 1) / DATA_WIDTH) + 1),
        parameter IRQ_WIDTH = $clog2(IRQ_NUM)) (
    //Number of interrupt IRQ_NUM, maxmum 1024
    //Number of interrupt HART_NUM, hart
    //priority width, not exceed 32
    input clk,
    input rstn,
    input [(IRQ_NUM - 1):0] irq_src,  //from outside, maybe a pulse(at least one cycle), or high-level
    input [(HART_NUM - 1):0] hart_claim,  //hart read claim register
    input [(IRQ_NUM - 1):0] complete [(HART_NUM - 1):0],  //every bit corresponsing to one source, from register
    output reg [(IRQ_NUM - 1):0] irq_penging [(HART_NUM - 1):0],  //realtime irq pending
    input [(IRQ_WIDTH - 1):0] max_pend_id //maxmum claim ID
         [(HART_NUM - 1):0]) ;
    reg [(IRQ_NUM - 1):0] src_rqs_ready [(HART_NUM - 1):0] ;
    reg [(IRQ_NUM - 1):0] pending_ready [(HART_NUM - 1):0] ;
    reg [(IRQ_NUM - 1):0] src_rqs ;
    integer j ;
    integer k ;
    always
        @(posedge clk)
        begin : GATEWAY_S
            for (j = 0 ; (j < HART_NUM) ; j = (j + 1))
                begin : GATEWAY_S0
                    if ((rstn == 1'b0))
                        begin : GATEWAY_S1
                            src_rqs_ready[j] <=  {IRQ_NUM{1'b1}} ;
                            src_rqs_ready[j][0] <=  1'b0 ;
                        end
                    else
                        begin : GATEWAY_S2
                            for (k = 1 ; (k < IRQ_NUM) ; k = (k + 1))
                                begin : GATEWAY_S3
                                    if (complete[j][k])
                                        begin : GATEWAY_S4
                                            src_rqs_ready[j][k] <=  1'b1 ;
                                        end
                                    else
                                        if (src_rqs[k])
                                            begin : GATEWAY_S5
                                                src_rqs_ready[j][k] <=  1'b0 ;
                                            end
                                end
                        end
                end
        end
    integer i ;
    always
        @(*)
        begin : SRC_RQS_S0
            src_rqs = {IRQ_NUM{1'b1}} ;
            for (i = 0 ; (i < HART_NUM) ; i = (i + 1))
                begin : SRC_RQS_S1
                    src_rqs = ((src_rqs & irq_src) & src_rqs_ready[i]) ;
                end
        end
    genvar n ;
    genvar m ;
    generate
        for (n = 0;(n < HART_NUM);n = (n + 1))
        begin : PENDING
            for (m = 0;(m < IRQ_NUM);m = (m + 1))
            begin : GATEWAY_S3
                always
                    @(posedge clk or
                        negedge rstn)
                    begin : PENDING_S1
                        if ((rstn == 1'b0))
                            begin : PENDING_S2
                                irq_penging[n][m] <=  1'b0 ;
                            end
                        else
                            if (((hart_claim[n] == 1'b1) && (max_pend_id[n] == m)))
                                begin : PENDING_S3
                                    irq_penging[n][m] <=  1'b0 ;
                                end
                            else
                                begin : PENDING_S4
                                    irq_penging[n][m] <=  (src_rqs[m] | irq_penging[n][m]) ;
                                end
                    end
            end
        end
    endgenerate
endmodule



`timescale 1ns/1ps
/** generate interrupt pending
*  1. assert IP
*  2. target 'claims IP'
*     clears IP bit
*     blocks IP from asserting again
*  3. target 'completes'
*/
module cpu0_ipgen_interrupt #(parameter ADDR_WIDTH = 32,
        parameter DATA_WIDTH = 32,
        parameter IRQ_NUM = 32,
        parameter HART_NUM = 2,
        parameter PRIORITY_W = 3,
        parameter IRQ_ARRAY = (((IRQ_NUM - 1) / DATA_WIDTH) + 1),
        parameter IRQ_WIDTH = $clog2(IRQ_NUM),
        parameter INSERT_REG = 1) (
    //Number of interrupt IRQ_NUM, maxmum 1024
    //Number of interrupt HART_NUM, hart
    //priority width, not exceed 32
    //parameter IRQ_MODE   =  IRQ_NUM'hFFFFFFFF            , //interrupt mode: 0 edge, 1 level
    input clk,
    input rstn,
    output [(IRQ_WIDTH - 1):0] max_pend_id [(HART_NUM - 1):0],  //maxmum claim ID to hart
    output [(HART_NUM - 1):0] max_pend_irq,  //interrupt alert to hart
    input [(PRIORITY_W - 1):0] threshold [(HART_NUM - 1):0],  //hart priority threshold
    input [(PRIORITY_W - 1):0] src_priority [(IRQ_NUM - 1):0],  //priority for each source
    input [(IRQ_NUM - 1):0] irq_penging [(HART_NUM - 1):0],  //realtime irq pending
    input [(IRQ_NUM - 1):0] irq_enable //every bit corresponsing to one source
         [(HART_NUM - 1):0]) ;
    localparam IRQ_NUM_MAX = (2 ** IRQ_WIDTH) ; //1024;
    localparam IRQ_WIDTH_MAX = $clog2(IRQ_NUM_MAX) ;
    wire [(PRIORITY_W - 1):0] pri_active [(HART_NUM - 1):0][(IRQ_NUM_MAX - 1):0] ;
    wire [(PRIORITY_W - 1):0] pri_active_r [(HART_NUM - 1):0][(IRQ_NUM_MAX - 1):0] ;
    wire [(IRQ_WIDTH_MAX - 1):0] max_id [(HART_NUM - 1):0] ;
    wire [(PRIORITY_W - 1):0] max_priority [(HART_NUM - 1):0] ;
    wire [(PRIORITY_W - 1):0] max_priority_r [(HART_NUM - 1):0] ;
    genvar i ;
    genvar j ;
    generate
        for (i = 0;(i < HART_NUM);i = (i + 1))
        begin : IRQ_ACT_S0
            assign pri_active[i][0] = 0 ;
            for (j = 1;(j < IRQ_NUM);j = (j + 1))
            begin : ACTIVE_PRIORITY0
                assign pri_active[i][j] = (src_priority[j] & {PRIORITY_W{(irq_enable[i][j] & irq_penging[i][j])}}) ;
            end
            for (j = IRQ_NUM;(j < IRQ_NUM_MAX);j = (j + 1))
            begin : ACTIVE_PRIORITY1
                assign pri_active[i][j] = {PRIORITY_W{1'b0}} ;
            end
            cpu0_ipgen_priority_index #(.IRQ_NUM(IRQ_NUM_MAX),
                    .PRIORITY_W(PRIORITY_W)) priority_index_inst (.src_priority(pri_active_r[i]),
                        .max_id(max_id[i]),
                        .max_priority(max_priority[i])) ;
            if ((INSERT_REG == 1))
                begin : PEND_REG0
                    cpu0_ipgen_dffr #(PRIORITY_W) max_pend_irq_dffr (max_priority[i],
                                max_priority_r[i],
                                clk,
                                rstn) ;
                    cpu0_ipgen_dffr #(IRQ_WIDTH) max_pend_id_dffr (max_id[i][(IRQ_WIDTH - 1):0],
                                max_pend_id[i],
                                clk,
                                rstn) ;
                end
            else
                begin : PEND_REG1
                    assign max_priority_r[i] = max_priority[i] ;
                    assign max_pend_id[i] = max_id[i][(IRQ_WIDTH - 1):0] ;
                end
            assign max_pend_irq[i] = (max_priority_r[i] > threshold[i]) ;
            if ((INSERT_REG == 1))
                begin : ACTIVE_REG
                    assign pri_active_r[i][0] = 0 ;
                    for (j = 1;(j < IRQ_NUM);j = (j + 1))
                    begin : ACTIVE_REG0
                        cpu0_ipgen_dffr #(PRIORITY_W) pri_active_dffr (pri_active[i][j],
                                    pri_active_r[i][j],
                                    clk,
                                    rstn) ;
                    end
                    for (j = IRQ_NUM;(j < IRQ_NUM_MAX);j = (j + 1))
                    begin : ACTIVE_REG1
                        assign pri_active_r[i][j] = {PRIORITY_W{1'b0}} ;
                    end
                end
            else
                begin : ACTIVE_REG2
                    assign pri_active_r[i] = pri_active[i] ;
                end
        end
    endgenerate
endmodule



`timescale 1ns/1ps
/*
change list:
20211214 v1.0 first version
*/
module cpu0_ipgen_plic_localbus_register #(parameter ADDR_WIDTH = 32,
        parameter DATA_WIDTH = 32,
        parameter IRQ_NUM = 32,
        parameter HART_NUM = 2,
        parameter PRIORITY_W = 3,
        parameter IRQ_ARRAY = (((IRQ_NUM - 1) / DATA_WIDTH) + 1),
        parameter IRQ_WIDTH = $clog2(IRQ_NUM)) (
    //Number of interrupt IRQ_NUM, maxmum 1024
    //Number of interrupt HART_NUM, hart
    //priority width, not exceed 32
    //parameter IRQ_MODE   =  IRQ_NUM'hFFFFFFFF            , //interrupt mode: 0 edge, 1 level
    input clk,
    input rstn,
    //local bus
    input cmd_valid,
    output cmd_ready,
    input cmd_payload_wr,
    input [(ADDR_WIDTH - 1):0] cmd_payload_address,
    input [(DATA_WIDTH - 1):0] cmd_payload_data,
    input [1:0] cmd_payload_size,  //not use only support size=2
    output rsp_ready,
    output reg rsp_error,
    output [(DATA_WIDTH - 1):0] rsp_data,
    //registers
    output reg [(PRIORITY_W - 1):0] src_priority [(IRQ_NUM - 1):0],  //Priority for each source
    output reg [(IRQ_NUM - 1):0] irq_enable [(HART_NUM - 1):0],  //every bit corresponsing to one source
    output reg [(PRIORITY_W - 1):0] threshold [(HART_NUM - 1):0],  //range: priority value
    output reg [(IRQ_NUM - 1):0] complete [(HART_NUM - 1):0],  //every bit corresponsing to one source, to gateway; //allow new irq request in this channel
    output [(HART_NUM - 1):0] hart_claim,  //hart read claim register;                          //clear pending bit at this channel
    input [(IRQ_WIDTH - 1):0] max_pend_id [(HART_NUM - 1):0],  //maxmum claim ID
    input [(IRQ_NUM - 1):0] irq_penging //realtime irq pending
         [(HART_NUM - 1):0]) ;
    //local parameter
    //signals declear
    wire bus_read ;
    wire bus_write ;
    wire [(ADDR_WIDTH - 3):0] bus_addr ;
    wire [(DATA_WIDTH - 1):0] bus_data ;
    reg [(DATA_WIDTH - 1):0] rd_data ;
    reg rd_ready ;
    assign bus_read = ((cmd_valid == 1) && (cmd_payload_wr == 0)) ;
    assign bus_write = ((cmd_valid == 1) && (cmd_payload_wr == 1)) ;
    assign bus_addr = cmd_payload_address[(ADDR_WIDTH - 1):2] ;
    assign bus_data = cmd_payload_data ;
    assign cmd_ready = 1 ;
    assign rsp_data = rd_data ;
    assign rsp_ready = rd_ready ;
    always
        @(posedge clk or
            negedge rstn)
        begin
            if ((!rstn))
                begin
                    rsp_error <=  1'b0 ;
                end
            else
                if ((cmd_valid & (cmd_payload_size != 2'b10)))
                    begin
                        rsp_error <=  1'b1 ;
                    end
                else
                    begin
                        rsp_error <=  1'b0 ;
                    end
        end
    //register write
    //PRIORITY
    /*
1.A priority value of 0 is reserved to mean "never interrupt" and effectively disables the interrupt.
2.Priority 1 is the lowest active priority, and priority 7 is the highest.
3.Ties between global interrupts of the same priority are broken by the Interrupt ID,
  interrupts with the lowest ID have the highest effective priority.
*/
    integer i ;
    always
        @(posedge clk)
        begin : PRIORITY_WRITE_S0
            for (i = 1 ; (i < IRQ_NUM) ; i = (i + 1))
                begin : PRIORITY_WRITE_S1
                    if ((rstn == 1'b0))
                        begin : PRIORITY_WRITE_S2
                            src_priority[i] <=  {PRIORITY_W{1'b0}} ;
                        end
                    else
                        if (((bus_write == 1'b1) && (bus_addr == ((32'h0000 >> 2) + i))))
                            begin : PRIORITY_WRITE_S3
                                src_priority[i] <=  bus_data[(PRIORITY_W - 1):0] ;
                            end
                end
            src_priority[0] <=  {PRIORITY_W{1'b0}} ;
        end
    //ENABLE
    genvar j ;
    genvar k ;
    generate
        for (j = 0;(j < HART_NUM);j = (j + 1))
        begin : IRQ_ENABLE_WRITE
            for (k = 0;(k < IRQ_ARRAY);k = (k + 1))
            begin : IRQ_ENABLE_WRITE_S1
                if (((IRQ_ARRAY - 1) == k))
                    begin : IRQ_ENABLE_WRITE_S2
                        //last array
                        if (((IRQ_NUM % 32) == 0))
                            begin : IRQ_ENABLE_WRITE_S3
                                always
                                    @(posedge clk or
                                        negedge rstn)
                                    begin : IRQ_ENABLE_WRITE_S4
                                        if ((rstn == 1'b0))
                                            begin : IRQ_ENABLE_WRITE_S5
                                                irq_enable[j][(k * 32) +: 32] <=  {32{1'b0}} ;
                                            end
                                        else
                                            if (((bus_write == 1'b1) && (bus_addr == (((32'h2000 + (j * 128)) >> 2) + k))))
                                                begin : IRQ_ENABLE_WRITE_S6
                                                    irq_enable[j][(k * 32) +: 32] <=  bus_data ;//fix data size = 32, or 32->DATA_WIDTH
                                                end
                                        if ((k == 0))
                                            begin
                                                irq_enable[j][0] <=  1'b0 ;
                                            end
                                    end
                            end
                        else
                            begin : IRQ_ENABLE_WRITE_S7
                                always
                                    @(posedge clk)
                                    begin : IRQ_ENABLE_WRITE_S8
                                        if ((rstn == 1'b0))
                                            begin : IRQ_ENABLE_WRITE_S9
                                                irq_enable[j][(((k * 32) + (IRQ_NUM % 32)) - 1) -: (IRQ_NUM % 32)] <=  {(IRQ_NUM % 32){1'b0}} ;
                                            end
                                        else
                                            if (((bus_write == 1'b1) && (bus_addr == (((32'h2000 + (j * 128)) >> 2) + k))))
                                                begin : IRQ_ENABLE_WRITE_SA
                                                    irq_enable[j][(((k * 32) + (IRQ_NUM % 32)) - 1) -: (IRQ_NUM % 32)] <=  bus_data[((IRQ_NUM % 32) - 1):0] ;//fix data size = 32, or 32->DATA_WIDTH
                                                end
                                        if ((k == 0))
                                            begin
                                                irq_enable[j][0] <=  1'b0 ;
                                            end
                                    end
                            end
                    end
                else
                    begin : IRQ_ENABLE_WRITE_SB
                        //not last array
                        always
                            @(posedge clk or
                                negedge rstn)
                            begin : IRQ_ENABLE_WRITE_SC
                                if ((rstn == 1'b0))
                                    begin : IRQ_ENABLE_WRITE_SD
                                        irq_enable[j][(k * 32) +: 32] <=  {32{1'b0}} ;
                                    end
                                else
                                    if (((bus_write == 1'b1) && (bus_addr == (((32'h2000 + (j * 128)) >> 2) + k))))
                                        begin : IRQ_ENABLE_WRITE_SE
                                            irq_enable[j][(k * 32) +: 32] <=  bus_data ;//fix data size = 32, or 32->DATA_WIDTH
                                        end
                                if ((k == 0))
                                    begin
                                        irq_enable[j][0] <=  1'b0 ;
                                    end
                            end
                    end
            end
        end
    endgenerate
    //Thredhold
    integer m ;
    always
        @(posedge clk)
        begin : THREDHOLD_WRITE_S0
            for (m = 0 ; (m < HART_NUM) ; m = (m + 1))
                begin : THREDHOLD_WRITE_S1
                    if ((rstn == 1'b0))
                        begin : THREDHOLD_WRITE_S2
                            threshold[m] <=  {PRIORITY_W{1'b0}} ;
                        end
                    else
                        if (((bus_write == 1'b1) && (bus_addr == ((32'h200000 + (m * 4096)) >> 2))))
                            begin : THREDHOLD_WRITE_S3
                                threshold[m] <=  bus_data[(PRIORITY_W - 1):0] ;
                            end
                end
        end
    //Complete a pulse
    integer n ;
    integer q ;
    always
        @(posedge clk)
        begin : COMPLETE_WRITE_S0
            for (n = 0 ; (n < HART_NUM) ; n = (n + 1))
                begin : COMPLETE_WRITE_S1
                    if ((rstn == 1'b0))
                        begin : COMPLETE_WRITE_S2
                            complete[n] <=  {IRQ_NUM{1'b0}} ;
                        end
                    else
                        begin : COMPLETE_WRITE_S3
                            for (q = 1 ; (q < IRQ_NUM) ; q = (q + 1))
                                begin : COMPLETE_WRITE_S4
                                    if ((((bus_write == 1'b1) && (bus_addr == ((32'h200004 + (n * 4096)) >> 2))) && (bus_data[(IRQ_WIDTH - 1):0] == q)))
                                        begin : COMPLETE_WRITE_S5
                                            complete[n][q] <=  1'b1 ;
                                        end
                                    else
                                        begin : COMPLETE_WRITE_S6
                                            complete[n][q] <=  1'b0 ;
                                        end
                                end
                            complete[n][0] <=  1'b0 ;
                        end
                end
        end
    //register read
    integer p ;
    genvar r ;
    integer s ;
    reg [(DATA_WIDTH - 1):0] src_prior_r ;
    reg [(DATA_WIDTH - 1):0] pending_r ;
    reg [(DATA_WIDTH - 1):0] threshold_r ;
    reg [(HART_NUM - 1):0] hart_claim_s ;
    reg [(DATA_WIDTH - 1):0] irq_enable_r [(IRQ_ARRAY - 1):0] ;
    reg [(DATA_WIDTH - 1):0] irq_pend_r [(IRQ_ARRAY - 1):0] ;
    reg [(DATA_WIDTH - 1):0] irq_enb_pnd_r ;
    always
        @(*)
        begin : REGISTER_READ_PRIORITY
            src_prior_r = {DATA_WIDTH{1'b0}} ;
            for (s = 0 ; (s < IRQ_NUM) ; s = (s + 1))
                begin : REGISTER_READ_PRIORITY0
                    if ((bus_addr == ((32'h0000 >> 2) + s)))
                        begin : REGISTER_READ_PRIORITY1
                            src_prior_r = {{(32 - PRIORITY_W){/*src_prior_r|*/ 1'b0}},
                                    src_priority[s]} ;
                        end
                end
        end
    always
        @(*)
        begin : REGISTER_READ_CLAIM_THRESHOLD
            pending_r = {DATA_WIDTH{1'b0}} ;
            threshold_r = {DATA_WIDTH{1'b0}} ;
            hart_claim_s = {HART_NUM{1'b0}} ;
            for (p = 0 ; (p < HART_NUM) ; p = (p + 1))
                begin : REGISTER_READ_CLAIM_THRESHOLD
                    if ((bus_addr == ((32'h200004 + (p * 4096)) >> 2)))
                        begin : REGISTER_READ_CLAIM
                            pending_r = {{(32 - IRQ_WIDTH){/*pending_r|*/ 1'b0}},
                                    max_pend_id[p]} ;
                            hart_claim_s[p] = (bus_read == 1'b1) ;//1'b1;
                        end/*&& bus_read == 1'b1*/
                    if ((bus_addr == ((32'h200000 + (p * 4096)) >> 2)))
                        begin : REGISTER_READ_THRESHOLD
                            threshold_r = threshold[p] ;/*threshold_r|*/
                        end
                end
        end
    generate
        for (r = 0;(r < IRQ_ARRAY);r = (r + 1))
        begin : REGISTER_READ_ENABLE_PEND
            if (((IRQ_ARRAY - 1) == r))
                begin : REGISTER_READ_ENABLE_PEND0
                    //last array
                    if (((IRQ_NUM % 32) == 0))
                        begin : REGISTER_READ_ENABLE_PEND00
                            always
                                @(*)
                                begin : REGISTER_READ_ENABLE_PEND000
                                    irq_enable_r[r] = {DATA_WIDTH{1'b0}} ;
                                    for (p = 0 ; (p < HART_NUM) ; p = (p + 1))
                                        begin : REGISTER_READ_CLAIM_THRESHOLD0
                                            if ((bus_addr == (((32'h2000 + (p * 128)) >> 2) + r)))
                                                begin : REGISTER_READ_ENABLE0
                                                    irq_enable_r[r] = irq_enable[p][(r * 32) +: 32] ;/*irq_enable_r[r]|*/
                                                end
                                        end
                                end
                            always
                                @(*)
                                begin : REGISTER_READ_ENABLE_PEND001
                                    irq_pend_r[r] = {DATA_WIDTH{1'b0}} ;
                                    for (p = 0 ; (p < HART_NUM) ; p = (p + 1))
                                        begin : REGISTER_READ_CLAIM_THRESHOLD1
                                            if ((bus_addr == (((32'h1000 + (p * 128)) >> 2) + r)))
                                                begin : REGISTER_READ_PEND0
                                                    irq_pend_r[r] = irq_penging[p][(r * 32) +: 32] ;/*irq_pend_r[r]|*/
                                                end
                                        end
                                end
                        end
                    else
                        begin : REGISTER_READ_ENABLE_PEND01
                            always
                                @(*)
                                begin : REGISTER_READ_ENABLE_PEND010
                                    irq_enable_r[r] = {DATA_WIDTH{1'b0}} ;
                                    for (p = 0 ; (p < HART_NUM) ; p = (p + 1))
                                        begin : REGISTER_READ_CLAIM_THRESHOLD2
                                            if ((bus_addr == (((32'h2000 + (p * 128)) >> 2) + r)))
                                                begin : REGISTER_READ_ENABLE1
                                                    irq_enable_r[r] = irq_enable[p][(((r * 32) + (IRQ_NUM % 32)) - 1) -: (IRQ_NUM % 32)] ;/*irq_enable_r[r]|*///fix data size = 32, or 32->DATA_WIDTH
                                                end
                                        end
                                end
                            always
                                @(*)
                                begin : REGISTER_READ_ENABLE_PEND011
                                    irq_pend_r[r] = {DATA_WIDTH{1'b0}} ;
                                    for (p = 0 ; (p < HART_NUM) ; p = (p + 1))
                                        begin : REGISTER_READ_CLAIM_THRESHOLD3
                                            if ((bus_addr == (((32'h1000 + (p * 128)) >> 2) + r)))
                                                begin : REGISTER_READ_PEND1
                                                    irq_pend_r[r] = irq_penging[p][(((r * 32) + (IRQ_NUM % 32)) - 1) -: (IRQ_NUM % 32)] ;/*irq_pend_r[r]|*///fix data size = 32, or 32->DATA_WIDTH
                                                end
                                        end
                                end
                        end
                end
            else
                begin : REGISTER_READ_ENABLE_PEND1
                    //not last array
                    always
                        @(*)
                        begin : REGISTER_READ_ENABLE_PEND10
                            irq_enable_r[r] = {DATA_WIDTH{1'b0}} ;
                            for (p = 0 ; (p < HART_NUM) ; p = (p + 1))
                                begin : REGISTER_READ_CLAIM_THRESHOLD4
                                    if ((bus_addr == (((32'h2000 + (p * 128)) >> 2) + r)))
                                        begin : REGISTER_READ_ENABLE2
                                            irq_enable_r[r] = irq_enable[p][(r * 32) +: 32] ;/*irq_enable_r[r]|*/
                                        end
                                end
                        end
                    always
                        @(*)
                        begin : REGISTER_READ_ENABLE_PEND11
                            irq_pend_r[r] = {DATA_WIDTH{1'b0}} ;
                            for (p = 0 ; (p < HART_NUM) ; p = (p + 1))
                                begin : REGISTER_READ_CLAIM_THRESHOLD5
                                    if ((bus_addr == (((32'h1000 + (p * 128)) >> 2) + r)))
                                        begin : REGISTER_READ_PEND2
                                            irq_pend_r[r] = irq_penging[p][(r * 32) +: 32] ;/*irq_pend_r[r]|*/
                                        end
                                end
                        end
                end
        end
    endgenerate
    always
        @(*)
        begin
            irq_enb_pnd_r = {DATA_WIDTH{1'b0}} ;
            for (p = 0 ; (p < IRQ_ARRAY) ; p = (p + 1))
                begin : REGISTER_READ_ENABLE_PEND_M
                    irq_enb_pnd_r = ((irq_enb_pnd_r | irq_enable_r[p]) | irq_pend_r[p]) ;
                end
        end
    always
        @(posedge clk or
            negedge rstn)
        begin
            if ((rstn == 1'b0))
                begin
                    rd_data <=  {32{1'b0}} ;
                    rd_ready <=  1'b0 ;
                    // hart_claim <= {HART_NUM{1'b0}};
                end
            else
                if ((bus_read == 1'b1))
                    begin
                        rd_data <=  (((src_prior_r | pending_r) | threshold_r) | irq_enb_pnd_r) ;
                        rd_ready <=  1'b1 ;
                        // hart_claim <= hart_claim_s;
                    end
                else
                    begin
                        // hart_claim <= {HART_NUM{1'b0}};
                        rd_ready <=  1'b0 ;
                    end
        end
    assign hart_claim = hart_claim_s ;
endmodule



`timescale 1ns/1ps
/*
change list:
20211214 v1.0.0 first version
20220211 v1.0.1 revise priority arbitration method
*/
module cpu0_ipgen_plic_top #(parameter ADDR_WIDTH = 22,
        parameter DATA_WIDTH = 32,
        parameter IRQ_NUM = 64,
        parameter HART_NUM = 2,
        parameter PRIO_NUM = 8) (
    //now is 22bits. offset address, depends on resgisters
    //interrupt number, maxmum 1024
    //hart number
    //priority number
    input clk,
    input rstn,
    //local bus
    input cmd_valid,
    output cmd_ready,
    input cmd_payload_wr,
    input [(ADDR_WIDTH - 1):0] cmd_payload_address,
    input [(DATA_WIDTH - 1):0] cmd_payload_data,
    input [1:0] cmd_payload_size,  //not use only support size=2
    output rsp_ready,
    output rsp_error,
    output [(DATA_WIDTH - 1):0] rsp_data,
    //interrupt
    input [(IRQ_NUM - 1):0] irq_src,
    output [(HART_NUM - 1):0] irq_hart) ;
    localparam PRIORITY_W = $clog2(PRIO_NUM) ;
    localparam IRQ_ARRAY = (((IRQ_NUM - 1) / DATA_WIDTH) + 1) ;
    localparam IRQ_WIDTH = $clog2(IRQ_NUM) ;
    wire [(PRIORITY_W - 1):0] src_priority [(IRQ_NUM - 1):0] ; //Priority for each source
    wire [(IRQ_NUM - 1):0] irq_enable [(HART_NUM - 1):0] ; //every bit corresponsing to one source
    wire [(PRIORITY_W - 1):0] threshold [(HART_NUM - 1):0] ; //range: priority value
    wire [(IRQ_NUM - 1):0] complete [(HART_NUM - 1):0] ; //every bit corresponsing to one source, to gateway
    wire [(HART_NUM - 1):0] hart_claim ; //hart read claim register
    wire [(IRQ_WIDTH - 1):0] max_pend_id [(HART_NUM - 1):0] ; //maxmum claim ID
    wire [(IRQ_NUM - 1):0] irq_penging [(HART_NUM - 1):0] ; //realtime irq pending
    cpu0_ipgen_plic_localbus_register #(.ADDR_WIDTH(ADDR_WIDTH),
            .DATA_WIDTH(DATA_WIDTH),
            .IRQ_NUM(IRQ_NUM),
            .HART_NUM(HART_NUM),
            .PRIORITY_W(PRIORITY_W)) plic_localbus_register_inst (.clk(clk),
                .rstn(rstn),
                .cmd_valid(cmd_valid),
                .cmd_ready(cmd_ready),
                .cmd_payload_wr(cmd_payload_wr),
                .cmd_payload_address(cmd_payload_address),
                .cmd_payload_data(cmd_payload_data),
                .cmd_payload_size(cmd_payload_size),
                .rsp_ready(rsp_ready),
                .rsp_error(rsp_error),
                .rsp_data(rsp_data),
                .src_priority(src_priority),
                .irq_enable(irq_enable),
                .threshold(threshold),
                .complete(complete),
                .hart_claim(hart_claim),
                .max_pend_id(max_pend_id),
                .irq_penging(irq_penging)) ;
    cpu0_ipgen_gateway #(.ADDR_WIDTH(ADDR_WIDTH),
            .DATA_WIDTH(DATA_WIDTH),
            .IRQ_NUM(IRQ_NUM),
            .HART_NUM(HART_NUM),
            .PRIORITY_W(PRIORITY_W)) gateway_inst (.clk(clk),
                .rstn(rstn),
                .irq_src(irq_src),
                .hart_claim(hart_claim),
                .complete(complete),
                .irq_penging(irq_penging),
                .max_pend_id(max_pend_id)) ;
    cpu0_ipgen_interrupt #(.ADDR_WIDTH(ADDR_WIDTH),
            .DATA_WIDTH(DATA_WIDTH),
            .IRQ_NUM(IRQ_NUM),
            .HART_NUM(HART_NUM),
            .PRIORITY_W(PRIORITY_W)) interrupt_inst (.clk(clk),
                .rstn(rstn),
                .max_pend_id(max_pend_id),
                .max_pend_irq(irq_hart),
                .threshold(threshold),
                .src_priority(src_priority),
                .irq_penging(irq_penging),
                .irq_enable(irq_enable)) ;
endmodule



`timescale 1ns/1ps
module cpu0_ipgen_priority_index #(parameter IRQ_NUM = 32,
        parameter PRIORITY_W = 3,
        parameter IRQ_WIDTH = $clog2(IRQ_NUM)) (
    //Number of interrupt IRQ_NUM, maxmum 1024, IRQ_NUM % 2 must be 0
    //priority width, not exceed 32
    input [(PRIORITY_W - 1):0] src_priority [(IRQ_NUM - 1):0],  //priority for each source
    output [(IRQ_WIDTH - 1):0] max_id,
    output [(PRIORITY_W - 1):0] max_priority) ;
    wire irq_prio_lvl_10_lt [(1024 - 1):0] ; // The level-10 max priority array
    wire irq_prio_lvl_9_lt [(512 - 1):0] ; // The level-9  max priority array
    wire irq_prio_lvl_8_lt [(256 - 1):0] ; // The level-8  max priority array
    wire irq_prio_lvl_7_lt [(128 - 1):0] ; // The level-7  max priority array
    wire irq_prio_lvl_6_lt [(64 - 1):0] ; // The level-6  max priority array
    wire irq_prio_lvl_5_lt [(32 - 1):0] ; // The level-5  max priority array
    wire irq_prio_lvl_4_lt [(16 - 1):0] ; // The level-4  max priority array
    wire irq_prio_lvl_3_lt [(8 - 1):0] ; // The level-3  max priority array
    wire irq_prio_lvl_2_lt [(4 - 1):0] ; // The level-2  max priority array
    wire irq_prio_lvl_1_lt [(2 - 1):0] ; // The level-1  max priority array
    wire irq_prio_top_lt ; // The level-0  max priority
    wire [(PRIORITY_W - 1):0] irq_prio_lvl_10 [(1024 - 1):0] ; // The level-10 max priority array
    wire [(PRIORITY_W - 1):0] irq_prio_lvl_9 [(512 - 1):0] ; // The level-9  max priority array
    wire [(PRIORITY_W - 1):0] irq_prio_lvl_8 [(256 - 1):0] ; // The level-8  max priority array
    wire [(PRIORITY_W - 1):0] irq_prio_lvl_7 [(128 - 1):0] ; // The level-7  max priority array
    wire [(PRIORITY_W - 1):0] irq_prio_lvl_6 [(64 - 1):0] ; // The level-6  max priority array
    wire [(PRIORITY_W - 1):0] irq_prio_lvl_5 [(32 - 1):0] ; // The level-5  max priority array
    wire [(PRIORITY_W - 1):0] irq_prio_lvl_4 [(16 - 1):0] ; // The level-4  max priority array
    wire [(PRIORITY_W - 1):0] irq_prio_lvl_3 [(8 - 1):0] ; // The level-3  max priority array
    wire [(PRIORITY_W - 1):0] irq_prio_lvl_2 [(4 - 1):0] ; // The level-2  max priority array
    wire [(PRIORITY_W - 1):0] irq_prio_lvl_1 [(2 - 1):0] ; // The level-1  max priority array
    wire [(PRIORITY_W - 1):0] irq_prio_top ; // The level-0  max priority
    wire [(IRQ_WIDTH - 1):0] irq_id_lvl_10 [(1024 - 1):0] ; // The level-10 max id array
    wire [(IRQ_WIDTH - 1):0] irq_id_lvl_9 [(512 - 1):0] ; // The level-9  max id array
    wire [(IRQ_WIDTH - 1):0] irq_id_lvl_8 [(256 - 1):0] ; // The level-8  max id array
    wire [(IRQ_WIDTH - 1):0] irq_id_lvl_7 [(128 - 1):0] ; // The level-7  max id array
    wire [(IRQ_WIDTH - 1):0] irq_id_lvl_6 [(64 - 1):0] ; // The level-6  max id array
    wire [(IRQ_WIDTH - 1):0] irq_id_lvl_5 [(32 - 1):0] ; // The level-5  max id array
    wire [(IRQ_WIDTH - 1):0] irq_id_lvl_4 [(16 - 1):0] ; // The level-4  max id array
    wire [(IRQ_WIDTH - 1):0] irq_id_lvl_3 [(8 - 1):0] ; // The level-3  max id array
    wire [(IRQ_WIDTH - 1):0] irq_id_lvl_2 [(4 - 1):0] ; // The level-2  max id array
    wire [(IRQ_WIDTH - 1):0] irq_id_lvl_1 [(2 - 1):0] ; // The level-1  max id array
    wire [(IRQ_WIDTH - 1):0] irq_id_top ; // The level-0  max id
    genvar i ;
    generate
        // Generate the level-10 signals
        assign irq_prio_lvl_10[0] = {PRIORITY_W{1'b0}} ;
        assign irq_id_lvl_10[0] = {IRQ_WIDTH{1'b0}} ;
        for (i = 1;(i < IRQ_NUM);i = (i + 1))
        begin : TIE_USED
            assign irq_prio_lvl_10[i] = src_priority[i] ;
            assign irq_id_lvl_10[i] = i[(IRQ_WIDTH - 1):0] ;
        end
        for (i = IRQ_NUM;(i < 1024);i = (i + 1))
        begin : TIE_ZERO_UNUSED
            assign irq_prio_lvl_10[i] = {PRIORITY_W{1'b0}} ;
            assign irq_id_lvl_10[i] = i[(IRQ_WIDTH - 1):0] ;
        end
        // Generate the level-9 comp
        for (i = 0;(i < 512);i = (i + 1))
        begin : lvl_9_comp_gen
            assign irq_prio_lvl_9_lt[i] = (irq_prio_lvl_10[(2 * i)] < irq_prio_lvl_10[((2 * i) + 1)]) ;
            assign irq_prio_lvl_9[i] = (irq_prio_lvl_9_lt[i] ? irq_prio_lvl_10[((2 * i) + 1)] : irq_prio_lvl_10[(2 * i)]) ;
            assign irq_id_lvl_9[i] = (irq_prio_lvl_9_lt[i] ? irq_id_lvl_10[((2 * i) + 1)] : irq_id_lvl_10[(2 * i)]) ;
        end
        // Generate the level-8 comp
        for (i = 0;(i < 256);i = (i + 1))
        begin : lvl_8_comp_gen
            assign irq_prio_lvl_8_lt[i] = (irq_prio_lvl_9[(2 * i)] < irq_prio_lvl_9[((2 * i) + 1)]) ;
            assign irq_prio_lvl_8[i] = (irq_prio_lvl_8_lt[i] ? irq_prio_lvl_9[((2 * i) + 1)] : irq_prio_lvl_9[(2 * i)]) ;
            assign irq_id_lvl_8[i] = (irq_prio_lvl_8_lt[i] ? irq_id_lvl_9[((2 * i) + 1)] : irq_id_lvl_9[(2 * i)]) ;
        end
        // Generate the level-7 comp
        for (i = 0;(i < 128);i = (i + 1))
        begin : lvl_7_comp_gen
            assign irq_prio_lvl_7_lt[i] = (irq_prio_lvl_8[(2 * i)] < irq_prio_lvl_8[((2 * i) + 1)]) ;
            assign irq_prio_lvl_7[i] = (irq_prio_lvl_7_lt[i] ? irq_prio_lvl_8[((2 * i) + 1)] : irq_prio_lvl_8[(2 * i)]) ;
            assign irq_id_lvl_7[i] = (irq_prio_lvl_7_lt[i] ? irq_id_lvl_8[((2 * i) + 1)] : irq_id_lvl_8[(2 * i)]) ;
        end
        // Generate the level-6 comp
        for (i = 0;(i < 64);i = (i + 1))
        begin : lvl_6_comp_gen
            assign irq_prio_lvl_6_lt[i] = (irq_prio_lvl_7[(2 * i)] < irq_prio_lvl_7[((2 * i) + 1)]) ;
            assign irq_prio_lvl_6[i] = (irq_prio_lvl_6_lt[i] ? irq_prio_lvl_7[((2 * i) + 1)] : irq_prio_lvl_7[(2 * i)]) ;
            assign irq_id_lvl_6[i] = (irq_prio_lvl_6_lt[i] ? irq_id_lvl_7[((2 * i) + 1)] : irq_id_lvl_7[(2 * i)]) ;
        end
        // Generate the level-5 comp
        for (i = 0;(i < 32);i = (i + 1))
        begin : lvl_5_comp_gen
            assign irq_prio_lvl_5_lt[i] = (irq_prio_lvl_6[(2 * i)] < irq_prio_lvl_6[((2 * i) + 1)]) ;
            assign irq_prio_lvl_5[i] = (irq_prio_lvl_5_lt[i] ? irq_prio_lvl_6[((2 * i) + 1)] : irq_prio_lvl_6[(2 * i)]) ;
            assign irq_id_lvl_5[i] = (irq_prio_lvl_5_lt[i] ? irq_id_lvl_6[((2 * i) + 1)] : irq_id_lvl_6[(2 * i)]) ;
        end
        // Generate the level-4 comp
        for (i = 0;(i < 16);i = (i + 1))
        begin : lvl_4_comp_gen
            assign irq_prio_lvl_4_lt[i] = (irq_prio_lvl_5[(2 * i)] < irq_prio_lvl_5[((2 * i) + 1)]) ;
            assign irq_prio_lvl_4[i] = (irq_prio_lvl_4_lt[i] ? irq_prio_lvl_5[((2 * i) + 1)] : irq_prio_lvl_5[(2 * i)]) ;
            assign irq_id_lvl_4[i] = (irq_prio_lvl_4_lt[i] ? irq_id_lvl_5[((2 * i) + 1)] : irq_id_lvl_5[(2 * i)]) ;
        end
        // Generate the level-3 comp
        for (i = 0;(i < 8);i = (i + 1))
        begin : lvl_3_comp_gen
            assign irq_prio_lvl_3_lt[i] = (irq_prio_lvl_4[(2 * i)] < irq_prio_lvl_4[((2 * i) + 1)]) ;
            assign irq_prio_lvl_3[i] = (irq_prio_lvl_3_lt[i] ? irq_prio_lvl_4[((2 * i) + 1)] : irq_prio_lvl_4[(2 * i)]) ;
            assign irq_id_lvl_3[i] = (irq_prio_lvl_3_lt[i] ? irq_id_lvl_4[((2 * i) + 1)] : irq_id_lvl_4[(2 * i)]) ;
        end
        // Generate the level-2 comp
        for (i = 0;(i < 4);i = (i + 1))
        begin : lvl_2_comp_gen
            assign irq_prio_lvl_2_lt[i] = (irq_prio_lvl_3[(2 * i)] < irq_prio_lvl_3[((2 * i) + 1)]) ;
            assign irq_prio_lvl_2[i] = (irq_prio_lvl_2_lt[i] ? irq_prio_lvl_3[((2 * i) + 1)] : irq_prio_lvl_3[(2 * i)]) ;
            assign irq_id_lvl_2[i] = (irq_prio_lvl_2_lt[i] ? irq_id_lvl_3[((2 * i) + 1)] : irq_id_lvl_3[(2 * i)]) ;
        end
        // Generate the level-1 comp
        for (i = 0;(i < 2);i = (i + 1))
        begin : lvl_1_comp_gen
            assign irq_prio_lvl_1_lt[i] = (irq_prio_lvl_2[(2 * i)] < irq_prio_lvl_2[((2 * i) + 1)]) ;
            assign irq_prio_lvl_1[i] = (irq_prio_lvl_1_lt[i] ? irq_prio_lvl_2[((2 * i) + 1)] : irq_prio_lvl_2[(2 * i)]) ;
            assign irq_id_lvl_1[i] = (irq_prio_lvl_1_lt[i] ? irq_id_lvl_2[((2 * i) + 1)] : irq_id_lvl_2[(2 * i)]) ;
        end
        assign irq_prio_top_lt = (irq_prio_lvl_1[0] < irq_prio_lvl_1[1]) ;
        assign irq_prio_top = (irq_prio_top_lt ? irq_prio_lvl_1[1] : irq_prio_lvl_1[0]) ;
        assign irq_id_top = (irq_prio_top_lt ? irq_id_lvl_1[1] : irq_id_lvl_1[0]) ;
    endgenerate
    assign max_priority = irq_prio_top ;
    assign max_id = irq_id_top ;
endmodule



