module cpu0_ipgen_riscvrtos #(parameter MODE = "Balanced",
        parameter M_EXT = 1,
        parameter C_EXT = 1,
        parameter F_EXT = 1,
        parameter A_EXT = 1,
        parameter DEBUG_ENABLE = 1,
        parameter IBUS_WRAPPER = 0,
        parameter DBUS_WRAPPER = 0,
        parameter DEVICE = "LIFCL",
        parameter TCM_ENABLE = 1,
        parameter SYS_CACHE = 1,
        parameter SC_BASE_ADDR = 32'h00200000,
