                    assign cpu_dbus_cmd_payload_size = {1'b0,
                                lite_dBus_cmd_payload_size} ;
                    assign cpu_dbus_cmd_payload_uncached = 1'b0 ;
                    always_comb
                        begin
                            dBus_cmd_payload_mask = 4'b1111 ;
                            if ((lite_dBus_cmd_payload_size == 2'b00))
                                begin
                                    /*
				address[1:0]=00 mask=4'b0001
				address[1:0]=01 mask=4'b0010
				address[1:0]=10 mask=4'b0100
				address[1:0]=11 mask=4'b1000
				*/
                                    dBus_cmd_payload_mask = (4'b0001 << cpu_dbus_cmd_payload_address[1:0]) ;
                                end
                            else
                                if ((lite_dBus_cmd_payload_size == 2'b01))
                                    begin
