    localparam NUM_OF_INT_OUT = ((IRQ_SUPERVISOR_EN == 1) ? 2 : 1) ;
    wire irq0_reserved ;
    wire [(NUM_OF_INT_OUT - 1):0] irq_hart ;
    wire [(IRQ_NUM - 1):0] irq_plic ;
    assign irq0_reserved = 1'b0 ;
    generate
        if ((PLIC_EN == 1))
            begin : with_plic
                cpu0_ipgen_plic_top #(.ADDR_WIDTH(32'd22),
                        .DATA_WIDTH(32'd32),
                        .IRQ_NUM((IRQ_NUM + 2)),
                        .HART_NUM(NUM_OF_INT_OUT),
                        .PRIO_NUM((8'b1 << IRQ_PRIORITY_WIDTH))) plic_top_inst (// 1 hart, but two outputs, one for Machine mode and one for supervisor mode
                        //priority number
                        .clk(clk_system_i),
                            .rstn(system_resetn_o),
                            .cmd_valid(m4_dBus_cmd_valid),
                            .cmd_ready(m4_dBus_cmd_ready),
                            .cmd_payload_wr(m4_dBus_cmd_payload_wr),
                            .cmd_payload_address(m4_dBus_cmd_payload_address[21:0]),
                            .cmd_payload_data(m4_dBus_cmd_payload_data),
                            .cmd_payload_size(m4_dBus_cmd_payload_size[1:0]),  //not use only support size=2
                        .rsp_ready(m4_dBus_rsp_valid),
                            .rsp_error(m4_dBus_rsp_error),
                            .rsp_data(m4_dBus_rsp_data),
                            .irq_src({irq_plic,
                                watchdog_s1,
                                irq0_reserved}),
                            .irq_hart(irq_hart)) ;
                assign externalInterrupt = irq_hart[0] ;
            end
        else
            begin : no_plic
                assign m4_dBus_cmd_ready = 1'b0 ;
                assign m4_dBus_rsp_valid = 1'b0 ;
                assign m4_dBus_rsp_error = 1'b0 ;
                assign m4_dBus_rsp_data = 32'b0 ;
                assign externalInterrupt = EXTERNAL_IRQ ;
            end
    endgenerate
    genvar i ;
    generate
        for (i = 0;(i < IRQ_NUM);i = (i + 1))
        begin : irq_wire
            if (((CDC_Sync2[i] == 1'b1) && (PLIC_EN == 1)))
                begin : cdc_sync2
                    cpu0_ipgen_lscc_sync #(.SYNC_STAGE(2),
                            .DEST_RST_MODE("ASYNC"),
                            .RST_INIT(1'b0),
                            .REGMODE(1'b0)) sync2_inst (.dest_clk(clk_system_i),
                                .dest_rst_n(system_resetn_o),
