module cpu0_ipgen_clkdiv (
    input clk_i,
    input rst_n_i,
    output clk_o) ;
    reg [8:0] cnt ;
    always
        @(posedge clk_i or
            negedge rst_n_i)
        begin
            if ((!rst_n_i))
                begin
                    cnt <=  0 ;
                end
            else
                begin
                    cnt <=  (cnt + 1) ;
                end
        end
    assign clk_o = cnt[8] ;
endmodule



//---------------------------------------------------------------------
// Module: lscc_sync
//---------------------------------------------------------------------
// Copyright (c) 2024 by Lattice Semiconductor Corporation
//---------------------------------------------------------------------
//
//  Params:
//  + SYNC_STAGE    -   Number of register stages used in synchronizers
//                      Allowable range is from 2 to 4
//  + DEST_RST_MODE -   Reset mode
//                      (SYNC = Synchronous, ASYNC - Asynchronous)
//  + RST_INIT      -   Default reset value
//  + REGMODE       -   If enabled, there will be additional flop
//                      at the output before sending the output data
//
//  Ports:
//  + in_data       -   Input data in src_clk domain
//
//  + dest_rst_n    -   Destination reset (active low)
//  + dest_clk      -   Destination clock
//  + out_data      -   Output data after sync in dest_clk domain
//
//---------------------------------------------------------------------
// Uncomment this line if you would like to run simulation with SIM_META_EN
// manually (for debug purposes)
//`include "../verif/uvm_tb/tb_macro_list.sv"
(* LATTICE_IP_MODULE=1 *) module cpu0_ipgen_lscc_sync #(parameter SYNC_STAGE = 2,
        parameter DEST_RST_MODE = "ASYNC",
        parameter RST_INIT = 1'b0,
        parameter REGMODE = 1'b0) (
    input logic in_data,
    input logic dest_rst_n,
    input logic dest_clk,
    output logic out_data) ;
    //------------------------------------------------------------------------------
    // CDC
    //------------------------------------------------------------------------------
    logic dout_meta ;
    logic [(SYNC_STAGE - 2):0] dout ;
    generate
        if ((SYNC_STAGE == 2))
            begin : genblk1
                (* syn_preserve=1, CDC_Register=2 *) logic dout_cc ;
                if ((DEST_RST_MODE == "ASYNC"))
                    begin : genblk1
                        always_ff
                            @(posedge dest_clk or
                                negedge dest_rst_n)
                            begin
                                if ((~dest_rst_n))
                                    begin
                                        dout_cc <=  RST_INIT ;
                                    end
                                else
                                    begin
                                        dout_cc <=  in_data ;
                                    end
                            end
                    end
                else
                    begin : genblk1
                        always_ff
                            @(posedge dest_clk)
                            begin
                                if ((~dest_rst_n))
                                    begin
                                        dout_cc <=  RST_INIT ;
                                    end
                                else
                                    begin
                                        dout_cc <=  in_data ;
                                    end
                            end
                    end
                assign dout_meta = dout_cc ;
            end
        else
            if ((SYNC_STAGE == 3))
                begin : genblk1
                    (* syn_preserve=1, CDC_Register=3 *) logic dout_cc ;
                    if ((DEST_RST_MODE == "ASYNC"))
                        begin : genblk1
                            always_ff
                                @(posedge dest_clk or
                                    negedge dest_rst_n)
                                begin
                                    if ((~dest_rst_n))
                                        begin
                                            dout_cc <=  RST_INIT ;
                                        end
                                    else
                                        begin
                                            dout_cc <=  in_data ;
                                        end
                                end
                        end
                    else
                        begin : genblk1
                            always_ff
                                @(posedge dest_clk)
                                begin
                                    if ((~dest_rst_n))
                                        begin
                                            dout_cc <=  RST_INIT ;
                                        end
                                    else
                                        begin
                                            dout_cc <=  in_data ;
                                        end
                                end
                        end
                    assign dout_meta = dout_cc ;
                end
            else
                begin : genblk1
                    (* syn_preserve=1, CDC_Register=4 *) logic dout_cc ;
                    if ((DEST_RST_MODE == "ASYNC"))
                        begin : genblk1
                            always_ff
                                @(posedge dest_clk or
                                    negedge dest_rst_n)
                                begin
                                    if ((~dest_rst_n))
                                        begin
                                            dout_cc <=  RST_INIT ;
                                        end
                                    else
                                        begin
                                            dout_cc <=  in_data ;
                                        end
                                end
                        end
                    else
                        begin : genblk1
                            always_ff
                                @(posedge dest_clk)
                                begin
                                    if ((~dest_rst_n))
                                        begin
                                            dout_cc <=  RST_INIT ;
                                        end
                                    else
                                        begin
                                            dout_cc <=  in_data ;
                                        end
                                end
                        end
                    assign dout_meta = dout_cc ;
                end
    endgenerate
    generate
        if ((DEST_RST_MODE == "ASYNC"))
            begin : genblk2
                always_ff
                    @(posedge dest_clk or
                        negedge dest_rst_n)
                    begin
                        if ((~dest_rst_n))
                            begin
                                dout <=  {(SYNC_STAGE - 1){RST_INIT}} ;
                            end
                        else
                            begin
                                dout <=  ((SYNC_STAGE > 2) ? {dout[(SYNC_STAGE - 3):0],
                                        dout_meta} : dout_meta) ;
                            end
                    end
            end
        else
            begin : genblk2
                always_ff
                    @(posedge dest_clk)
                    begin
                        if ((~dest_rst_n))
                            begin
                                dout <=  {(SYNC_STAGE - 1){RST_INIT}} ;
                            end
                        else
                            begin
                                dout <=  ((SYNC_STAGE > 2) ? {dout[(SYNC_STAGE - 3):0],
                                        dout_meta} : dout_meta) ;
                            end
                    end
            end
    endgenerate
    generate
        if (REGMODE)
            begin : genblk3
                if ((DEST_RST_MODE == "ASYNC"))
                    begin : genblk1
                        always_ff
                            @(posedge dest_clk or
                                negedge dest_rst_n)
                            begin
                                if ((~dest_rst_n))
                                    out_data <=  RST_INIT ;
                                else
                                    out_data <=  dout[(SYNC_STAGE - 2)] ;
                            end
                    end
                else
                    begin : genblk1
                        always_ff
                            @(posedge dest_clk)
                            begin
                                if ((~dest_rst_n))
                                    out_data <=  RST_INIT ;
                                else
                                    out_data <=  dout[(SYNC_STAGE - 2)] ;
                            end
                    end
            end
        else
            begin : genblk3
                assign out_data = dout[(SYNC_STAGE - 2)] ;
            end
    endgenerate
endmodule


